   133→export const getOpportunityWithRelations = async ({
   134→  opportunityId,
   135→  phoneNumber,
   136→  organizationId,
   137→}: {
   138→  opportunityId?: string;
   139→  phoneNumber?: string;
   140→  organizationId?: string;
   141→}) => {
   142→  if (!opportunityId && !phoneNumber) {
   143→    throw new Error("Either opportunityId or phoneNumber is required");
   144→  }
   145→
   146→  const where: Prisma.OpportunityWhereInput = {
   147→    job: {
   148→      schemaVersion: "v2",
   149→      organizationId,
   150→      status: {
   151→        not: JobStatus.CLOSED,
   152→      },
   153→    },
   154→  };
   155→
   156→  if (opportunityId) {
   157→    where.id = opportunityId;
   158→  } else if (phoneNumber) {
   159→    where.candidate = {
   160→      phoneNumber: phoneNumber,
   161→    };
   162→  }
   163→
   164→  try {
   165→    const opportunities = await db.opportunity.findMany({
   166→      where,
   167→      include: {
   168→        job: {
   169→          include: {
   170→            organization: true,
   171→            variables: {
   172→              include: {
   173→                templateVariable: true,
   174→              },
   175→            },
   176→          },
   177→        },
   178→        candidate: true,
   179→        agentPhoneNumber: true,
   180→      },
   181→      orderBy: {
   182→        createdAt: "desc",
   183→      },
   184→    });
   185→
   186→    if (opportunities.length === 0) {
   187→      throw new NotFoundError(
   188→        `Opportunity not found: ${opportunityId ?? phoneNumber}`,
   189→      );
   190→    }
   191→
   192→    // Return first non-success opportunity if exists, otherwise first opportunity
   193→    const nonSuccessOpportunity = opportunities.find(
   194→      (o) => o.status !== OpportunityStatus.completed,
   195→    );
   196→    return nonSuccessOpportunity ?? opportunities[0]!;
   197→  } catch (e) {
   198→    console.log(`Error getting opportunity ${opportunityId ?? phoneNumber}`, e);
   199→    throw e;
   200→  }
   201→};
