   228→// Bulk add new opportunites. Overwrites existing opportunities data, but not candidate data
   229→export async function bulkAddOpportunities({
   230→  organizationId,
   231→  jobId,
   232→  opportunities,
   233→  addedByUserId,
   234→}: {
   235→  organizationId: string;
   236→  jobId: string;
   237→  opportunities: {
   238→    firstName: string;
   239→    lastName: string;
   240→    email?: string;
   241→    phoneNumber?: string;
   242→    candidateAtsId?: string;
   243→    recruiterAtsId?: string;
   244→    assignedToEmail?: string;
   245→    opportunityAtsId?: string;
   246→    source?: string;
   247→    timezone?: string;
   248→  }[];
   249→  addedByUserId: string;
   250→}) {
   251→  // make sure job is part of the organization
   252→  await db.job.findUniqueOrThrow({
   253→    where: {
   254→      id: jobId,
   255→      organizationId,
   256→    },
   257→  });
   258→
   259→  // Upsert the opportunities, based on candidate phonenumber or atsId
   260→  let numUpdated = 0;
   261→  let numCreated = 0;
   262→
   263→  await Promise.all(
   264→    opportunities.map(async (opportunity) => {
   265→      const candidateResult = await createCandidate({
   266→        organizationId,
   267→        data: {
   268→          firstName: opportunity.firstName,
   269→          lastName: opportunity.lastName,
   270→          email: opportunity.email,
   271→          phoneNumber: opportunity.phoneNumber,
   272→          organization: {
   273→            connect: { id: organizationId },
   274→          },
   275→          addedBy: {
   276→            connect: { id: addedByUserId },
   277→          },
   278→        },
   279→      });
   280→
   281→      const existingOpportunity = await findExistingOpportunity({
   282→        jobId,
   283→        candidateId: candidateResult.candidate.id,
   284→      });
   285→
   286→      if (existingOpportunity) {
   287→        await updateOpportunity({
   288→          organizationId,
   289→          opportunityId: existingOpportunity.id,
   290→          data: {
   291→            recruiterAtsId: opportunity.recruiterAtsId,
   292→            assignedToEmail: opportunity.assignedToEmail,
   293→            atsId: opportunity.opportunityAtsId,
   294→            source: opportunity.source,
   295→            addedBy: {
   296→              connect: { id: addedByUserId },
   297→            },
   298→          },
   299→        });
   300→        numUpdated++;
   301→      } else {
   302→        await createOpportunity({
   303→          organizationId,
   304→          data: {
   305→            recruiterAtsId: opportunity.recruiterAtsId,
   306→            assignedToEmail: opportunity.assignedToEmail,
   307→            atsId: opportunity.opportunityAtsId,
   308→            source: opportunity.source,
   309→            candidate: { connect: { id: candidateResult.candidate.id } },
   310→            job: { connect: { id: jobId } },
   311→          },
   312→        });
   313→        numCreated++;
   314→      }
   315→    }),
   316→  );
   317→
   318→  return { numUpdated, numCreated };
   319→}
