   417→export async function sendSMSImmediately({
   418→  opportunityId,
   419→  message,
   420→  opportunityNotificationId,
   421→  force = false,
   422→  sentById,
   423→  suggestedSmsMessageId,
   424→}: {
   425→  opportunityId: string;
   426→  message: string;
   427→  opportunityNotificationId?: string;
   428→  force?: boolean;
   429→  sentById?: string;
   430→  suggestedSmsMessageId?: string;
   431→}): Promise<boolean> {
   432→  const opportunity = await db.opportunity.findUnique({
   433→    where: {
   434→      id: opportunityId,
   435→    },
   436→    include: {
   437→      job: {
   438→        select: {
   439→          id: true,
   440→          status: true,
   441→          messagingEnabled: true,
   442→          organizationId: true,
   443→        },
   444→      },
   445→      candidate: {
   446→        select: {
   447→          phoneNumber: true,
   448→          doNotCall: true,
   449→        },
   450→      },
   451→      tags: {
   452→        include: {
   453→          tag: true,
   454→        },
   455→      },
   456→      smsMessages: true,
   457→    },
   458→  });
   459→
   460→  if (!opportunity?.candidate.phoneNumber) {
   461→    console.info(
   462→      `Opportunity phone number not found for opportunityId: ${opportunityId}, not sending SMS.`,
   463→    );
   464→    return false;
   465→  }
   466→
   467→  // Check for do not call tag when part of a sequence
   468→  if (opportunity.candidate.doNotCall) {
   469→    console.warn(
   470→      `Opportunity ${opportunityId} is marked as Do Not Call, not sending sequenced SMS.`,
   471→    );
   472→    return false;
   473→  }
   474→
   475→  // Only check job status and messaging if force is false
   476→  if (!force) {
   477→    if (opportunity.job.status !== JobStatus.ACTIVE.toString()) {
   478→      console.log(
   479→        "Scheduled SMS ignored since job is not active for opportunityId",
   480→        opportunityId,
   481→      );
   482→      return false;
   483→    }
   484→
   485→    if (!opportunity.job.messagingEnabled) {
   486→      console.log(
   487→        "Scheduled SMS ignored since messaging is disabled for job",
   488→        opportunity.job.id,
   489→      );
   490→      return false;
   491→    }
   492→  }
   493→
   494→  // Get the agent phone number for the opportunity
   495→  const { id: agentPhoneNumberId } = await getOpportunityAgentPhoneNumber(
   496→    opportunityId,
   497→    opportunity.job.organizationId,
   498→  );
   499→
   500→  const agentPhoneNumber = await db.agentPhoneNumber.findUniqueOrThrow({
   501→    where: { id: agentPhoneNumberId },
   502→  });
   503→
   504→  if (!agentPhoneNumber.telnyxMessagingProfileId) {
   505→    throw new Error(
   506→      "Telnyx agent phone number doesn't have a messaging profile. It's likely that the number does not support SMS.",
   507→    );
   508→  }
   509→
   510→  // Enforce 10DLC for US numbers
   511→  if (
   512→    agentPhoneNumber.countryCode === CountryCode.US.toString() &&
   513→    !agentPhoneNumber.telnyxCampaignId
   514→  ) {
   515→    console.warn(
   516→      `US-based agent phone number ${agentPhoneNumber.number} is NOT associated with a Telnyx campaign, not sending SMS.`,
   517→    );
   518→    return false;
   519→  }
   520→
   521→  const fromNumber = agentPhoneNumber.number;
   522→
   523→  const hasSentSms = opportunity.smsMessages.some(
   524→    (sms) => sms.direction === "OUTBOUND",
   525→  );
   526→
   527→  const compliantMessage = hasSentSms
   528→    ? message
   529→    : `${message} ${OPT_OUT_MESSAGE}`;
   530→
   531→  // Send the actual SMS
   532→  const smsResponse = await sendSMS(
   533→    fromNumber,
   534→    opportunity.candidate.phoneNumber,
   535→    compliantMessage,
   536→  );
   537→
   538→  let aiGenerated = false;
   539→  if (suggestedSmsMessageId) {
   540→    const suggestedSmsMessage = await db.suggestedSmsMessage.findUnique({
   541→      where: { id: suggestedSmsMessageId },
   542→    });
   543→    if (suggestedSmsMessage?.message === message) {
   544→      aiGenerated = true;
   545→    } else if (suggestedSmsMessage) {
   546→      const sentBy = sentById
   547→        ? await db.user.findUnique({ where: { id: sentById } })
   548→        : null;
   549→
   550→      const url = `https://app.purplefish.com/organizations/${opportunity.job.organizationId}/jobs/${opportunity.job.id}/opportunities/${opportunity.id}/messages`;
   551→
   552→      const slackMessage = `*AI:* ${suggestedSmsMessage.message}\n
   553→<${url}|*${sentBy?.firstName ?? "Human"}:*> ${message}`.trim();
   554→      try {
   555→        await sendSlackMessage(slackMessage, {
   556→          channel: "#inbound-sms-ai-feedback",
   557→        });
   558→      } catch (err) {
   559→        console.error("Error sending slack message on AI feedback", err);
   560→      }
   561→    }
   562→  }
   563→
   564→  await createSmsMessage({
   565→    phoneNumber: opportunity.candidate.phoneNumber,
   566→    message: compliantMessage,
   567→    direction: "OUTBOUND",
   568→    opportunityId,
   569→    candidateId: opportunity.candidateId,
   570→    agentPhoneNumberId: agentPhoneNumber.id,
   571→    parts: smsResponse.parts,
   572→    encoding: smsResponse.encoding,
   573→    telnyxMessageId: smsResponse.id,
   574→    sentById,
   575→    suggestedSmsMessageId,
   576→    aiGenerated,
   577→    opportunityNotificationId,
   578→  });
   579→
   580→  return true;
   581→}
