   583→export const createOpportunity = async ({
   584→  organizationId,
   585→  data,
   586→  atsCandidateMappingId,
   587→}: {
   588→  organizationId: string;
   589→  data: Prisma.OpportunityCreateInput;
   590→  atsCandidateMappingId?: string;
   591→}): Promise<Opportunity> => {
   592→  const candidateId = data.candidate.connect?.id;
   593→  const jobId = data.job.connect?.id;
   594→
   595→  if (!jobId) {
   596→    throw new Error("Job ID is required when creating an opportunity");
   597→  }
   598→
   599→  if (candidateId) {
   600→    const existingOpportunity = await findExistingOpportunity({
   601→      candidateId,
   602→      jobId,
   603→    });
   604→
   605→    if (existingOpportunity) {
   606→      return existingOpportunity;
   607→    }
   608→  }
   609→
   610→  const createdOpportunity = await db.opportunity.create({
   611→    data: {
   612→      ...data,
   613→      ...(atsCandidateMappingId && {
   614→        atsCandidateMapping: {
   615→          connect: { id: atsCandidateMappingId },
   616→        },
   617→      }),
   618→    },
   619→  });
   620→
   621→  const nextStageId = await moveOpportunityToNextStage({
   622→    opportunityId: createdOpportunity.id,
   623→  });
   624→
   625→  console.log(
   626→    `Opportunity ${createdOpportunity.id} created with atsId: ${createdOpportunity.atsId}, candidateId: ${createdOpportunity.candidateId}, source: ${createdOpportunity.source}, status: ${createdOpportunity.status}, stage: ${nextStageId}`,
   627→  );
   628→
   629→  // Create a public link token for the opportunity
   630→  await getOpportunityPublicLinkToken({
   631→    opportunityId: createdOpportunity.id,
   632→  });
   633→
   634→  await inngest.send({
   635→    name: "purplefish/opportunity.created",
   636→    data: {
   637→      organizationId,
   638→      opportunityId: createdOpportunity.id,
   639→    },
   640→  });
   641→
   642→  return createdOpportunity;
   643→};
