   645→export const updateOpportunity = async ({
   646→  organizationId,
   647→  opportunityId,
   648→  data,
   649→}: {
   650→  organizationId: string;
   651→  opportunityId: string;
   652→  data: Prisma.OpportunityUpdateInput;
   653→}): Promise<Opportunity> => {
   654→  // Fetch previous values for audit logging
   655→  const prev = await db.opportunity.findUnique({
   656→    where: { id: opportunityId },
   657→    select: { status: true, atsId: true },
   658→  });
   659→
   660→  // Log when status is being manually changed
   661→  if (data.status !== undefined && typeof data.status === "string") {
   662→    console.log(
   663→      `Manually updating opportunity ${opportunityId} status to: ${data.status}`,
   664→    );
   665→  }
   666→
   667→  const updatedOpportunity = await db.opportunity.update({
   668→    where: { id: opportunityId },
   669→    data,
   670→  });
   671→
   672→  await inngest.send({
   673→    name: "purplefish/opportunity.updated",
   674→    data: {
   675→      organizationId,
   676→      opportunityId: updatedOpportunity.id,
   677→    },
   678→  });
   679→
   680→  // Audit: status changes
   681→  if (
   682→    prev &&
   683→    data.status !== undefined &&
   684→    typeof data.status === "string" &&
   685→    prev.status !== updatedOpportunity.status
   686→  ) {
   687→    await createAuditLog({
   688→      userId: null,
   689→      action: "UPDATE",
   690→      modelName: "Opportunity",
   691→      recordId: opportunityId,
   692→      reason: "Status manually updated",
   693→      changes: {
   694→        title: "Status updated",
   695→        from: prev.status,
   696→        to: updatedOpportunity.status,
   697→      },
   698→    });
   699→  }
   700→
