  1453→export async function callOpportunityImmediately(
  1454→  opportunityId: string,
  1455→  force = false,
  1456→): Promise<{
  1457→  called: boolean;
  1458→  roomName?: string;
  1459→  reason?: string;
  1460→} | null> {
  1461→  const opportunity = await db.opportunity.findUnique({
  1462→    where: {
  1463→      id: opportunityId,
  1464→    },
  1465→    include: {
  1466→      candidate: {
  1467→        select: {
  1468→          id: true,
  1469→          phoneNumber: true,
  1470→          isBot: true,
  1471→          doNotCall: true,
  1472→          engagements: {
  1473→            select: {
  1474→              roomName: true,
  1475→            },
  1476→            where: {
  1477→              createdAt: {
  1478→                gte: new Date(Date.now() - 1000 * 60 * 24), // 24 hours
  1479→              },
  1480→            },
  1481→          },
  1482→        },
  1483→      },
  1484→      job: {
  1485→        select: {
  1486→          id: true,
  1487→          status: true,
  1488→          resumeCallsEnabled: true,
  1489→        },
  1490→      },
  1491→      tags: {
  1492→        include: {
  1493→          tag: true,
  1494→        },
  1495→      },
  1496→      engagements: true,
  1497→    },
  1498→  });
  1499→
  1500→  if (!opportunity) {
  1501→    throw new Error(`Opportunity ${opportunityId} not found`);
  1502→  }
  1503→  if (!opportunity.candidate.phoneNumber) {
  1504→    console.info(
  1505→      `Opportunity phone number not found for opportunityId: ${opportunityId}, not calling.`,
  1506→    );
  1507→    return { called: false, reason: "No Phone Number" };
  1508→  }
  1509→
  1510→  if (opportunity.candidate.doNotCall) {
  1511→    console.warn(
  1512→      `Opportunity ${opportunityId} is marked as Do Not Call, not proceeding with call.`,
  1513→    );
  1514→    return { called: false, reason: "Do Not Call" };
  1515→  }
  1516→
  1517→  // If force is false, we need to check if the opportunity is in a valid state to be called
  1518→  if (!force) {
  1519→    // Add some protection against too many outbound calls.
  1520→    if (
  1521→      opportunity.engagements.filter(
  1522→        (e) => e.roomName?.startsWith("profileId:") === true,
  1523→      ).length >= MAX_OUTBOUND_CALLS_PER_OPPORTUNITY
  1524→    ) {
  1525→      console.log(
  1526→        `Opportunity ${opportunityId} has too many outbound engagements, not calling.`,
  1527→      );
  1528→      return { called: false, reason: "Too Many Outbound Calls" };
  1529→    }
  1530→    if (
  1531→      opportunity.candidate.engagements.filter(
  1532→        (e) => e.roomName?.startsWith("profileId:") === true,
  1533→      ).length >= MAX_OUTBOUND_CALLS_PER_CANDIDATE_PER_DAY
  1534→    ) {
  1535→      console.log(
  1536→        `Candidate ${opportunity.candidate.id} has too many outbound engagements, not calling.`,
  1537→      );
  1538→      return { called: false, reason: "Too Many Outbound Calls" };
  1539→    }
  1540→    // if the opportunity state is success then we no longer need to call this opportunity
  1541→    if (
  1542→      opportunity.status === OpportunityStatus.completed &&
  1543→      !opportunity.candidate.isBot &&
  1544→      opportunity.job.resumeCallsEnabled
  1545→    ) {
  1546→      console.warn(
  1547→        `Opportunity ${opportunityId} is already in a success state, not calling.`,
  1548→      );
  1549→      return { called: false, reason: "Opportunity Already Called" };
  1550→    }
  1551→
  1552→    // Only check job status if force is false
  1553→    if (opportunity.job.status !== JobStatus.ACTIVE.toString()) {
  1554→      console.log(
  1555→        "Scheduled call ignored since job is not active for opportunityId",
  1556→        opportunityId,
  1557→      );
  1558→      return { called: false, reason: "Job Not Active" };
  1559→    }
  1560→
  1561→    if (!opportunity.candidate.isBot) {
  1562→      const engagement = await db.engagement.findFirst({
  1563→        where: {
  1564→          opportunityId,
  1565→        },
  1566→        orderBy: {
  1567→          createdAt: "desc",
  1568→        },
  1569→      });
  1570→
  1571→      if (engagement?.status === CallStatus.in_progress) {
  1572→        console.log(
  1573→          `Another call: ${engagement.id} is already in progress for opportunityId ${opportunityId}, not calling.`,
  1574→        );
  1575→        return { called: false, reason: "Call Already In Progress" };
  1576→      }
  1577→    }
  1578→  }
  1579→
  1580→  const name = generateRoomName(opportunity.id);
  1581→
  1582→  const roomService = new RoomServiceClient(
  1583→    env.LIVEKIT_URL,
  1584→    env.LIVEKIT_API_KEY,
  1585→    env.LIVEKIT_API_SECRET,
  1586→  );
  1587→
  1588→  const room = await roomService.createRoom({ name, emptyTimeout: 60 * 60 });
  1589→
  1590→  console.log(
  1591→    `Calling opportunity ${opportunityId} for job ${opportunity.job.id} (room: ${room.name})`,
  1592→  );
  1593→  return { called: true, roomName: room.name };
  1594→}
