  1596→const scheduleToCallOpportunity = async (
  1597→  opportunityId: string,
  1598→  scheduledTime: Date,
  1599→  opts?: {
  1600→    userId?: string;
  1601→    skipJitter?: boolean;
  1602→  },
  1603→) => {
  1604→  const opportunity = await db.opportunity.findUniqueOrThrow({
  1605→    where: {
  1606→      id: opportunityId,
  1607→    },
  1608→    select: {
  1609→      job: {
  1610→        select: {
  1611→          organizationId: true,
  1612→          id: true,
  1613→        },
  1614→      },
  1615→    },
  1616→  });
  1617→
  1618→  const existingPendingSequenceItem = await getNextPendingSequenceItem(
  1619→    opportunityId,
  1620→    SequenceItemChannel.phone,
  1621→  );
  1622→
  1623→  let newScheduledDate = scheduledTime;
  1624→
  1625→  // Only add jitter for bulk calls (when skipJitter is false)
  1626→  // For single opportunity calls (skipJitter true), use exact requested time
  1627→  if (!opts?.skipJitter) {
  1628→    newScheduledDate = addRandomMinutesToDate(newScheduledDate, 10);
  1629→    console.log(
  1630→      `Adding jitter to bulk call for ${opportunityId}. Original time: ${scheduledTime.toISOString()}, New time with jitter: ${newScheduledDate.toISOString()}`,
  1631→    );
  1632→  }
  1633→
  1634→  // If there is an existing pending sequence item, update it with the new scheduled time
  1635→  if (existingPendingSequenceItem) {
  1636→    if (opts?.userId) {
  1637→      await db.opportunitySequenceItem.update({
  1638→        where: { id: existingPendingSequenceItem.id },
  1639→        data: {
  1640→          triggeredByUserId: opts.userId,
  1641→        },
  1642→      });
  1643→    }
  1644→
  1645→    console.log(
  1646→      `Scheduling phone call for opportunity ${opportunityId} at ${newScheduledDate.toISOString()} for job ${opportunity.job.id}`,
  1647→    );
  1648→    return rescheduleSequenceItem(
  1649→      existingPendingSequenceItem.id,
  1650→      newScheduledDate,
  1651→    );
  1652→  } else {
  1653→    // Otherwise, create a new sequence item
  1654→    // Mark sequenceInitializedAt to prevent automatic full sequence creation
  1655→    await db.opportunity.update({
  1656→      where: { id: opportunityId },
  1657→      data: {
  1658→        sequenceInitializedAt: new Date(),
  1659→      },
  1660→    });
  1661→
  1662→    return createSequenceItem({
  1663→      opportunityId,
  1664→      channel: SequenceItemChannel.phone,
  1665→      scheduledAt: newScheduledDate,
  1666→      triggeredByUserId: opts?.userId,
  1667→    });
  1668→  }
  1669→};
