  1754→async function getOpportunityStatus(
  1755→  opportunityId: string,
  1756→): Promise<OpportunityStatus> {
  1757→  // Compute the status of the opportunity based on the latest engagement
  1758→  const engagements = await db.engagement.findMany({
  1759→    where: { opportunityId },
  1760→    orderBy: { createdAt: "desc" },
  1761→  });
  1762→
  1763→  // If there are no engagements, the opportunity is not contacted
  1764→  if (engagements.length < 1) {
  1765→    return OpportunityStatus.not_contacted;
  1766→  }
  1767→
  1768→  // A opportunity is considered completed if it has at least one completed engagement
  1769→  const completedEngagements = engagements.filter(
  1770→    (e) => e.status === CallStatus.completed,
  1771→  );
  1772→
  1773→  if (completedEngagements.length > 0) {
  1774→    // If the candidate has not recently declined the job in the most recent call, the opportunity is considered completed
  1775→    if (
  1776→      completedEngagements[0]?.subStatus !== CallSubStatus.candidate_declined
  1777→    ) {
  1778→      return OpportunityStatus.completed;
  1779→    } else {
  1780→      // Otherwise, consider that the candidate declined the job
  1781→      return OpportunityStatus.candidate_declined;
  1782→    }
  1783→  }
  1784→
  1785→  const remainingSequenceItems = await getRemainingSequenceItems(opportunityId);
  1786→
  1787→  if (remainingSequenceItems === 0) {
  1788→    return OpportunityStatus.sequence_ended;
  1789→  }
  1790→
  1791→  return OpportunityStatus.in_progress;
  1792→}
  1793→
  1794→export async function computeOpportunityStatus(
  1795→  opportunityId: string,
  1796→): Promise<OpportunityStatus> {
  1797→  // Capture previous status for audit logging
  1798→  const prev = await db.opportunity.findUnique({
  1799→    where: { id: opportunityId },
  1800→    select: { status: true },
  1801→  });
  1802→
  1803→  const status = await getOpportunityStatus(opportunityId);
  1804→
  1805→  const lastEngagement = await db.engagement.findFirst({
  1806→    where: { opportunityId },
  1807→    orderBy: { createdAt: "desc" },
  1808→  });
  1809→
  1810→  await db.opportunity.update({
  1811→    where: { id: opportunityId },
  1812→    data: { status, lastEngagementId: lastEngagement?.id },
  1813→  });
  1814→
  1815→  // Audit status change if it changed
  1816→  if (prev && prev.status !== status) {
  1817→    await createAuditLog({
  1818→      userId: null,
  1819→      action: "UPDATE",
  1820→      modelName: "Opportunity",
  1821→      recordId: opportunityId,
  1822→      reason: "Status recomputed from engagements",
  1823→      changes: {
  1824→        title: "Status updated",
  1825→        from: prev.status,
  1826→        to: status,
  1827→        lastEngagementId: lastEngagement?.id ?? null,
  1828→      },
  1829→    });
  1830→  }
  1831→
  1832→  // If the opportunity is completed, check if the candidate was rejected
  1833→  // If so, review the opportunity as rejected
  1834→  if (status === OpportunityStatus.completed) {
  1835→    const rejectedEngagement = await db.engagement.findFirst({
  1836→      where: {
  1837→        opportunityId,
  1838→        subStatus: CallSubStatus.rejected,
  1839→      },
  1840→      select: {
  1841→        opportunity: {
  1842→          select: {
  1843→            id: true,
  1844→            job: {
  1845→              select: { organizationId: true },
  1846→            },
  1847→          },
  1848→        },
  1849→      },
  1850→    });
  1851→    if (rejectedEngagement?.opportunity) {
  1852→      const opportunity = await db.opportunity.findUniqueOrThrow({
  1853→        where: { id: rejectedEngagement.opportunity.id },
  1854→      });
  1855→
  1856→      // Avoid auto-reviewing opportunities that have already been actioned
  1857→      if (!opportunity.actionedAt) {
  1858→        await reviewOpportunity(
  1859→          rejectedEngagement.opportunity.job.organizationId,
  1860→          rejectedEngagement.opportunity.id,
  1861→          OpportunityAction.REJECTED,
  1862→        );
  1863→      }
  1864→    }
  1865→  }
  1866→
  1867→  return status;
  1868→}
