  1870→export async function computeOpportunityRequirementCounts(
  1871→  opportunityId: string,
  1872→): Promise<{
  1873→  mandatoryRequirementCount: number;
  1874→  unmetMandatoryRequirementCount: number;
  1875→  metMandatoryRequirementCount: number;
  1876→  noDataMandatoryRequirementCount: number;
  1877→  metPreferredRequirementCount: number;
  1878→}> {
  1879→  // Compute the status of the profile based on the latest engagement
  1880→  const engagements = await db.engagement.findMany({
  1881→    where: { opportunityId },
  1882→    orderBy: { createdAt: "desc" },
  1883→  });
  1884→
  1885→  const completedEngagement = engagements.find(
  1886→    (e) => e.status === CallStatus.completed,
  1887→  );
  1888→
  1889→  // If there are no completed engagements, return 0 for all counts
  1890→  if (!completedEngagement) {
  1891→    return {
  1892→      mandatoryRequirementCount: 0,
  1893→      unmetMandatoryRequirementCount: 0,
  1894→      metMandatoryRequirementCount: 0,
  1895→      noDataMandatoryRequirementCount: 0,
  1896→      metPreferredRequirementCount: 0,
  1897→    };
  1898→  }
  1899→
  1900→  let mandatoryRequirementCount = 0;
  1901→  let unmetMandatoryRequirementCount = 0;
  1902→  let metMandatoryRequirementCount = 0;
  1903→  let noDataMandatoryRequirementCount = 0;
  1904→  let metPreferredRequirementCount = 0;
  1905→
  1906→  const lastEngagement = engagements[0];
  1907→  if (lastEngagement) {
  1908→    const scoreCard = lastEngagement.scoreCard as IScoreCard | null;
  1909→    const scores = scoreCard?.scores ?? [];
  1910→
  1911→    const mandatoryScores = scores.filter(
  1912→      (s) => s.type === JobQualificationType.MANDATORY,
  1913→    );
  1914→    const metMandatoryScores = mandatoryScores.filter((s) => s.score === "Met");
  1915→    const unmetMandatoryScores = mandatoryScores.filter(
  1916→      (s) => s.score === "Did not meet",
  1917→    );
  1918→    const noDataMandatoryScores = mandatoryScores.filter(
  1919→      (s) => s.score === "No data",
  1920→    );
  1921→    const preferredScores = scores.filter(
  1922→      (s) => s.type === JobQualificationType.PREFERRED,
  1923→    );
  1924→    const metPreferredScores = preferredScores.filter((s) => s.score === "Met");
  1925→
  1926→    mandatoryRequirementCount = mandatoryScores.length;
  1927→    unmetMandatoryRequirementCount = unmetMandatoryScores.length;
  1928→    metMandatoryRequirementCount = metMandatoryScores.length;
  1929→    noDataMandatoryRequirementCount = noDataMandatoryScores.length;
  1930→    metPreferredRequirementCount = metPreferredScores.length;
  1931→  }
  1932→
  1933→  return {
  1934→    mandatoryRequirementCount,
  1935→    unmetMandatoryRequirementCount,
  1936→    metMandatoryRequirementCount,
  1937→    noDataMandatoryRequirementCount,
  1938→    metPreferredRequirementCount,
  1939→  };
  1940→}
