  2005→}
  2006→
  2007→export async function getOpportunityLastInProgressScriptNodeId(
  2008→  opportunityId: string,
  2009→  isBot: boolean,
  2010→  resumeCallsEnabled: boolean,
  2011→  scriptNodes: ScriptNode[],
  2012→) {
  2013→  if (isBot || !resumeCallsEnabled) {
  2014→    // Treat every engagement as new.
  2015→    return null;
  2016→  }
  2017→
  2018→  // Filter to only top level nodes.
  2019→  scriptNodes = scriptNodes.filter((node) => !node.conditionToEnter);
  2020→
  2021→  // Find all the tasks we popped.
  2022→  const completedEvents = await db.engagementAgentTaskEvent.findMany({
  2023→    where: {
  2024→      engagement: {
  2025→        opportunityId,
  2026→      },
  2027→      type: EngagementAgentTaskEventType.task_popped,
  2028→    },
  2029→  });
  2030→
  2031→  // If we didn't pop any tasks, resume from the very beginning.
  2032→  if (completedEvents.length === 0) {
  2033→    return null;
  2034→  }
  2035→
  2036→  // Otherwise, find the _first_ node we didn't pop.
  2037→  for (const scriptNode of scriptNodes) {
  2038→    const completedEvent = completedEvents.find(
  2039→      (event) => event.taskId === scriptNode.id,
  2040→    );
  2041→    if (!completedEvent) {
  2042→      return scriptNode.id;
  2043→    }
  2044→  }
  2045→
  2046→  // If we popped everything, just resume from the very end so the agent says something.
  2047→  return scriptNodes[scriptNodes.length - 1]?.id || null;
  2048→}
  2049→
  2050→// Remove an opportunity and all its related data
  2051→/**
  2052→ * Checks if a sequence has completed and handles the opportunity status accordingly.
  2053→ * A sequence is considered complete when all items are either triggered or cancelled.
  2054→ *
  2055→ * @param opportunityId - The ID of the opportunity to check
  2056→ * @param lastProcessedItemId - The ID of the sequence item that was just processed
  2057→ * @returns true if the sequence was marked as ended, false otherwise
  2058→ */
  2059→export const checkAndHandleSequenceCompletion = async ({
  2060→  opportunityId,
  2061→  lastProcessedItemId,
  2062→}: {
  2063→  opportunityId: string;
  2064→  lastProcessedItemId: string;
  2065→}): Promise<boolean> => {
  2066→  // Get all sequence items for this opportunity
  2067→  // Order by scheduledAt to get them in sequence order
  2068→  const sequenceItems = await db.opportunitySequenceItem.findMany({
  2069→    where: { opportunityId },
  2070→    orderBy: { scheduledAt: "asc" },
  2071→  });
  2072→
  2073→  if (sequenceItems.length === 0) {
  2074→    return false;
  2075→  }
  2076→
  2077→  // Check if all items are either triggered or cancelled
  2078→  const allItemsProcessed = sequenceItems.every(
  2079→    (item) => item.triggeredAt !== null || item.cancelledAt !== null,
  2080→  );
  2081→
  2082→  if (!allItemsProcessed) {
  2083→    return false;
  2084→  }
  2085→
  2086→  // Find the last sequence item that was just processed
  2087→  const lastProcessedItem = sequenceItems.find(
  2088→    (item) => item.id === lastProcessedItemId,
  2089→  );
  2090→
  2091→  if (!lastProcessedItem) {
  2092→    return false;
  2093→  }
  2094→
  2095→  // Get the last item in the sequence by order
  2096→  const lastSequenceItem = sequenceItems[sequenceItems.length - 1];
  2097→  if (!lastSequenceItem) {
  2098→    return false;
  2099→  }
  2100→  const isLastItem = lastProcessedItem.id === lastSequenceItem.id;
  2101→
  2102→  // Determine if we should end the sequence based on the rules:
  2103→  // 1. If it's the last item and it's email/SMS, end immediately
  2104→  // 2. If it's the last item and it's phone that was cancelled (missing number), end immediately
  2105→  // 3. If all items are processed but last item was phone with number, let engagement handle it
  2106→  const shouldEndSequence =
  2107→    isLastItem &&
  2108→    (lastProcessedItem.channel === "email" ||
  2109→      lastProcessedItem.channel === "sms" ||
  2110→      lastProcessedItem.cancelledAt !== null);
  2111→
  2112→  // Also end sequence if all items are cancelled (no successful outreach)
  2113→  const allItemsCancelled = sequenceItems.every(
  2114→    (item) => item.cancelledAt !== null,
  2115→  );
  2116→
  2117→  if (shouldEndSequence || allItemsCancelled) {
  2118→    // Get the opportunity with job info for organization context
  2119→    const opportunity = await db.opportunity.findUnique({
  2120→      where: { id: opportunityId },
  2121→      select: {
  2122→        status: true,
  2123→        job: {
  2124→          select: {
  2125→            organizationId: true,
  2126→          },
  2127→        },
  2128→      },
  2129→    });
  2130→
  2131→    if (!opportunity) {
  2132→      return false;
  2133→    }
  2134→
  2135→    // Only update if not already in a terminal state
  2136→    if (
  2137→      opportunity.status !== OpportunityStatus.sequence_ended &&
  2138→      opportunity.status !== OpportunityStatus.completed &&
  2139→      opportunity.status !== OpportunityStatus.candidate_declined
  2140→    ) {
  2141→      console.log(
  2142→        `Marking opportunity ${opportunityId} as sequence_ended after processing last item ${lastProcessedItemId}`,
  2143→      );
  2144→
  2145→      await updateOpportunity({
  2146→        organizationId: opportunity.job.organizationId,
  2147→        opportunityId,
  2148→        data: {
  2149→          status: OpportunityStatus.sequence_ended,
  2150→        },
  2151→      });
  2152→
  2153→      // Trigger the stage transition which will archive the opportunity
  2154→      await moveOpportunityToNextStage({ opportunityId });
  2155→
  2156→      return true;
  2157→    }
  2158→  }
  2159→
  2160→  return false;
  2161→};
  2162→
