export const getOpportunityWithRelations = async ({
  opportunityId,
  phoneNumber,
  organizationId,
}: {
  opportunityId?: string;
  phoneNumber?: string;
  organizationId?: string;
}) => {
  if (!opportunityId && !phoneNumber) {
    throw new Error("Either opportunityId or phoneNumber is required");
  }

  const where: Prisma.OpportunityWhereInput = {
    job: {
      schemaVersion: "v2",
      organizationId,
      status: {
        not: JobStatus.CLOSED,
      },
    },
  };

  if (opportunityId) {
    where.id = opportunityId;
  } else if (phoneNumber) {
    where.candidate = {
      phoneNumber: phoneNumber,
    };
  }

  try {
    const opportunities = await db.opportunity.findMany({
      where,
      include: {
        job: {
          include: {
            organization: true,
            variables: {
              include: {
                templateVariable: true,
              },
            },
          },
        },
        candidate: true,
        agentPhoneNumber: true,
      },
      orderBy: {
        createdAt: "desc",
      },
    });

    if (opportunities.length === 0) {
      throw new NotFoundError(
        `Opportunity not found: ${opportunityId ?? phoneNumber}`,
      );
    }

    // Return first non-success opportunity if exists, otherwise first opportunity
    const nonSuccessOpportunity = opportunities.find(
      (o) => o.status !== OpportunityStatus.completed,
    );
    return nonSuccessOpportunity ?? opportunities[0]!;
  } catch (e) {
    console.log(`Error getting opportunity ${opportunityId ?? phoneNumber}`, e);
    throw e;
  }
};

export type OpportunityWithRelations = NonNullable<
  Awaited<ReturnType<typeof getOpportunityWithRelations>>
>;

export const findExistingOpportunity = async ({
  jobId,
  candidateId,
}: {
  jobId: string;
  candidateId: string;
}) => {
  const existingOpportunity = await db.opportunity.findFirst({
    where: {
      candidate: {
        id: candidateId,
      },
      job: {
        id: jobId,
      },
    },
  });

  return existingOpportunity;
};

// Bulk add new opportunites. Overwrites existing opportunities data, but not candidate data
export async function bulkAddOpportunities({
  organizationId,
  jobId,
  opportunities,
  addedByUserId,
}: {
  organizationId: string;
  jobId: string;
  opportunities: {
    firstName: string;
    lastName: string;
    email?: string;
    phoneNumber?: string;
    candidateAtsId?: string;
    recruiterAtsId?: string;
    assignedToEmail?: string;
    opportunityAtsId?: string;
    source?: string;
    timezone?: string;
  }[];
  addedByUserId: string;
}) {
  // make sure job is part of the organization
  await db.job.findUniqueOrThrow({
    where: {
      id: jobId,
      organizationId,
    },
  });

  // Upsert the opportunities, based on candidate phonenumber or atsId
  let numUpdated = 0;
  let numCreated = 0;

  await Promise.all(
    opportunities.map(async (opportunity) => {
      const candidateResult = await createCandidate({
        organizationId,
        data: {
          firstName: opportunity.firstName,
          lastName: opportunity.lastName,
          email: opportunity.email,
          phoneNumber: opportunity.phoneNumber,
          organization: {
            connect: { id: organizationId },
          },
          addedBy: {
            connect: { id: addedByUserId },
          },
        },
      });

      const existingOpportunity = await findExistingOpportunity({
        jobId,
        candidateId: candidateResult.candidate.id,
      });

      if (existingOpportunity) {
        await updateOpportunity({
          organizationId,
          opportunityId: existingOpportunity.id,
          data: {
            recruiterAtsId: opportunity.recruiterAtsId,
            assignedToEmail: opportunity.assignedToEmail,
            atsId: opportunity.opportunityAtsId,
            source: opportunity.source,
            addedBy: {
              connect: { id: addedByUserId },
            },
          },
        });
        numUpdated++;
      } else {
        await createOpportunity({
          organizationId,
          data: {
            recruiterAtsId: opportunity.recruiterAtsId,
            assignedToEmail: opportunity.assignedToEmail,
            atsId: opportunity.opportunityAtsId,
            source: opportunity.source,
            candidate: { connect: { id: candidateResult.candidate.id } },
            job: { connect: { id: jobId } },
          },
        });
        numCreated++;
      }
    }),
  );

  return { numUpdated, numCreated };
}

