export async function sendSMSImmediately({
  opportunityId,
  message,
  opportunityNotificationId,
  force = false,
  sentById,
  suggestedSmsMessageId,
}: {
  opportunityId: string;
  message: string;
  opportunityNotificationId?: string;
  force?: boolean;
  sentById?: string;
  suggestedSmsMessageId?: string;
}): Promise<boolean> {
  const opportunity = await db.opportunity.findUnique({
    where: {
      id: opportunityId,
    },
    include: {
      job: {
        select: {
          id: true,
          status: true,
          messagingEnabled: true,
          organizationId: true,
        },
      },
      candidate: {
        select: {
          phoneNumber: true,
          doNotCall: true,
        },
      },
      tags: {
        include: {
          tag: true,
        },
      },
      smsMessages: true,
    },
  });

  if (!opportunity?.candidate.phoneNumber) {
    console.info(
      `Opportunity phone number not found for opportunityId: ${opportunityId}, not sending SMS.`,
    );
    return false;
  }

  // Check for do not call tag when part of a sequence
  if (opportunity.candidate.doNotCall) {
    console.warn(
      `Opportunity ${opportunityId} is marked as Do Not Call, not sending sequenced SMS.`,
    );
    return false;
  }

  // Only check job status and messaging if force is false
  if (!force) {
    if (opportunity.job.status !== JobStatus.ACTIVE.toString()) {
      console.log(
        "Scheduled SMS ignored since job is not active for opportunityId",
        opportunityId,
      );
      return false;
    }

    if (!opportunity.job.messagingEnabled) {
      console.log(
        "Scheduled SMS ignored since messaging is disabled for job",
        opportunity.job.id,
      );
      return false;
    }
  }

  // Get the agent phone number for the opportunity
  const { id: agentPhoneNumberId } = await getOpportunityAgentPhoneNumber(
    opportunityId,
    opportunity.job.organizationId,
  );

  const agentPhoneNumber = await db.agentPhoneNumber.findUniqueOrThrow({
    where: { id: agentPhoneNumberId },
  });

  if (!agentPhoneNumber.telnyxMessagingProfileId) {
    throw new Error(
      "Telnyx agent phone number doesn't have a messaging profile. It's likely that the number does not support SMS.",
    );
  }

  // Enforce 10DLC for US numbers
  if (
    agentPhoneNumber.countryCode === CountryCode.US.toString() &&
    !agentPhoneNumber.telnyxCampaignId
  ) {
    console.warn(
      `US-based agent phone number ${agentPhoneNumber.number} is NOT associated with a Telnyx campaign, not sending SMS.`,
    );
    return false;
  }

  const fromNumber = agentPhoneNumber.number;

  const hasSentSms = opportunity.smsMessages.some(
    (sms) => sms.direction === "OUTBOUND",
  );

  const compliantMessage = hasSentSms
    ? message
    : `${message} ${OPT_OUT_MESSAGE}`;

  // Send the actual SMS
  const smsResponse = await sendSMS(
    fromNumber,
    opportunity.candidate.phoneNumber,
    compliantMessage,
  );

  let aiGenerated = false;
  if (suggestedSmsMessageId) {
    const suggestedSmsMessage = await db.suggestedSmsMessage.findUnique({
      where: { id: suggestedSmsMessageId },
    });
    if (suggestedSmsMessage?.message === message) {
      aiGenerated = true;
    } else if (suggestedSmsMessage) {
      const sentBy = sentById
        ? await db.user.findUnique({ where: { id: sentById } })
        : null;

      const url = `https://app.purplefish.com/organizations/${opportunity.job.organizationId}/jobs/${opportunity.job.id}/opportunities/${opportunity.id}/messages`;

      const slackMessage = `*AI:* ${suggestedSmsMessage.message}\n
<${url}|*${sentBy?.firstName ?? "Human"}:*> ${message}`.trim();
      try {
        await sendSlackMessage(slackMessage, {
          channel: "#inbound-sms-ai-feedback",
        });
      } catch (err) {
        console.error("Error sending slack message on AI feedback", err);
      }
    }
  }

  await createSmsMessage({
    phoneNumber: opportunity.candidate.phoneNumber,
    message: compliantMessage,
    direction: "OUTBOUND",
    opportunityId,
    candidateId: opportunity.candidateId,
    agentPhoneNumberId: agentPhoneNumber.id,
    parts: smsResponse.parts,
    encoding: smsResponse.encoding,
    telnyxMessageId: smsResponse.id,
    sentById,
    suggestedSmsMessageId,
    aiGenerated,
    opportunityNotificationId,
  });

  return true;
}

export const createOpportunity = async ({
  organizationId,
  data,
  atsCandidateMappingId,
}: {
  organizationId: string;
  data: Prisma.OpportunityCreateInput;
  atsCandidateMappingId?: string;
}): Promise<Opportunity> => {
  const candidateId = data.candidate.connect?.id;
  const jobId = data.job.connect?.id;

  if (!jobId) {
    throw new Error("Job ID is required when creating an opportunity");
  }

  if (candidateId) {
    const existingOpportunity = await findExistingOpportunity({
      candidateId,
      jobId,
    });

    if (existingOpportunity) {
      return existingOpportunity;
    }
  }

  const createdOpportunity = await db.opportunity.create({
    data: {
      ...data,
      ...(atsCandidateMappingId && {
        atsCandidateMapping: {
          connect: { id: atsCandidateMappingId },
        },
      }),
    },
  });

  const nextStageId = await moveOpportunityToNextStage({
    opportunityId: createdOpportunity.id,
  });

  console.log(
    `Opportunity ${createdOpportunity.id} created with atsId: ${createdOpportunity.atsId}, candidateId: ${createdOpportunity.candidateId}, source: ${createdOpportunity.source}, status: ${createdOpportunity.status}, stage: ${nextStageId}`,
  );

  // Create a public link token for the opportunity
  await getOpportunityPublicLinkToken({
    opportunityId: createdOpportunity.id,
  });

  await inngest.send({
    name: "purplefish/opportunity.created",
    data: {
      organizationId,
      opportunityId: createdOpportunity.id,
    },
  });

  return createdOpportunity;
};

export const updateOpportunity = async ({
  organizationId,
  opportunityId,
  data,
}: {
  organizationId: string;
  opportunityId: string;
  data: Prisma.OpportunityUpdateInput;
}): Promise<Opportunity> => {
  // Fetch previous values for audit logging
  const prev = await db.opportunity.findUnique({
    where: { id: opportunityId },
    select: { status: true, atsId: true },
  });

  // Log when status is being manually changed
  if (data.status !== undefined && typeof data.status === "string") {
    console.log(
      `Manually updating opportunity ${opportunityId} status to: ${data.status}`,
    );
  }

  const updatedOpportunity = await db.opportunity.update({
    where: { id: opportunityId },
    data,
  });

  await inngest.send({
    name: "purplefish/opportunity.updated",
    data: {
      organizationId,
      opportunityId: updatedOpportunity.id,
    },
  });

  // Audit: status changes
  if (
    prev &&
    data.status !== undefined &&
    typeof data.status === "string" &&
    prev.status !== updatedOpportunity.status
  ) {
    await createAuditLog({
      userId: null,
      action: "UPDATE",
      modelName: "Opportunity",
      recordId: opportunityId,
      reason: "Status manually updated",
      changes: {
        title: "Status updated",
        from: prev.status,
        to: updatedOpportunity.status,
      },
    });
  }

  // Audit: ATS ID changes
  if (prev && Object.prototype.hasOwnProperty.call(data, "atsId")) {
    // data.atsId can be Prisma input union; read the updated value from updatedOpportunity
    if (prev.atsId !== updatedOpportunity.atsId) {
      await createAuditLog({
        userId: null,
        action: "UPDATE",
        modelName: "Opportunity",
        recordId: opportunityId,
        reason: "ATS ID updated",
        changes: {
          title: "ATS ID updated",
          from: prev.atsId ?? null,
          to: updatedOpportunity.atsId ?? null,
        },
      });
    }
  }

  return updatedOpportunity;
};

export const getOpportunities = async (
  jobIds: string[],
  opts: {
    pageIndex: number;
    pageSize?: number;
    sorting?: SortingState;
    columnFilters?: ColumnFiltersState;
    query?: string;
    skipCount?: boolean;
    stageId?: string;
    assignedToEmail?: string;
  },
): Promise<{
  opportunities: OpportunitySummary[] | null;
  totalCount: number;
  stageCounts: Record<string, number>;
}> => {
  const pageIndex = opts.pageIndex;
  const pageSize = opts.pageSize ?? 30;

  const whereInputs: Prisma.OpportunityWhereInput[] = [];
  whereInputs.push({
    jobId: {
      in: jobIds,
    },
  });

  // Add stage filter if provided
  if (opts.stageId) {
    whereInputs.push({
      currentStageId: opts.stageId,
    });
  }

  // Add assignedToEmail filter if provided
  if (opts.assignedToEmail) {
    whereInputs.push({
      assignedToEmail: opts.assignedToEmail,
    });
  }

  // Search query must be processed before being used
  // https://github.com/prisma/prisma/issues/8939
  const trimmedQuery = opts.query?.trim();
  const searchQuery = trimmedQuery
    ? trimmedQuery
        .replace(/[<>@&|!(){}[\]^"~*?:/\\]/g, " ") // Remove special characters
        .replace(/\s+/g, " ") // Normalize whitespace
        .trim()
        .split(" ")
        .join(" & ")
    : undefined;
  const looseSearchQuery = trimmedQuery
    ? trimmedQuery
        .replace(/[<>@&|!(){}[\]^"~*?:/\\]/g, " ") // Remove special characters
        .replace(/\s+/g, " ") // Normalize whitespace
        .trim()
        .split(" ")
        .map((word) => `${word.trim()}:*`) // accept partial matches (starts with)
        .join(" | ") // join with OR
    : undefined;

  if (opts.query && searchQuery && looseSearchQuery) {
    whereInputs.push({
      OR: [
        // Search
        {
          candidate: {
            firstName: {
              search: searchQuery,
              mode: "insensitive",
            },
          },
        },
        {
          candidate: {
            lastName: {
              search: searchQuery,
              mode: "insensitive",
            },
          },
        },
        {
          candidate: {
            email: {
              search: searchQuery,
              mode: "insensitive",
            },
          },
        },
        {
          candidate: {
            phoneNumber: {
              search: searchQuery,
              mode: "insensitive",
            },
          },
        },

        // Loose search for first and last name
        {
          candidate: {
            firstName: {
              search: looseSearchQuery,
              mode: "insensitive",
            },
          },
        },
        {
          candidate: {
            lastName: {
              search: looseSearchQuery,
              mode: "insensitive",
            },
          },
        },

        // Perfectly matches
        {
          id: {
            equals: trimmedQuery,
            mode: "insensitive",
          },
        },
        {
          atsId: {
            equals: trimmedQuery,
            mode: "insensitive",
          },
        },
      ],
    });
  }

  const actions = (opts.columnFilters?.find((filter) => filter.id === "action")
    ?.value ?? []) as string[];
  const action = actions[0];

  const actionWhereInput: Prisma.OpportunityWhereInput[] = [];

  // We only allow one action filter at a time
  if (action) {
    if (
      Object.values(OpportunityAction).includes(action as OpportunityAction)
    ) {
      actionWhereInput.push({
        action: action as unknown as OpportunityAction,
      });
    } else if (action === "needsReview") {
      actionWhereInput.push({
        action: null,
      });
    }
  }

  if (actionWhereInput.length > 0) {
    whereInputs.push({
      OR: actionWhereInput,
    });
  }

  const statuses = (opts.columnFilters?.find((filter) => filter.id === "status")
    ?.value ?? []) as string[];

  const statusWhereInput: Prisma.OpportunityWhereInput[] = [];

  statuses.forEach((status) => {
    if (
      Object.values(OpportunityStatus).includes(status as OpportunityStatus)
    ) {
      statusWhereInput.push({
        status: status as unknown as OpportunityStatus,
      });
    }
  });

  if (statusWhereInput.length > 0) {
    whereInputs.push({
      OR: statusWhereInput,
    });
  }

  // Completed opportunities include both qualified and unqualified opportunities so we ignore qualified and unqualified filters
  if (!statuses.includes(OpportunityStatus.completed)) {
    if (statuses.includes("qualified")) {
      whereInputs.push({
        status: OpportunityStatus.completed,
        unmetMandatoryRequirementCount: {
          equals: 0,
        },
      });
    }

    if (statuses.includes("unqualified")) {
      whereInputs.push({
        status: OpportunityStatus.completed,
        unmetMandatoryRequirementCount: {
          gt: 0,
        },
      });
    }
  }

  const engagementStatuses = (opts.columnFilters?.find(
    (filter) => filter.id === "lastEngagement_subStatus",
  )?.value ?? []) as string[];
  const engagementStatusWhereInput: Prisma.OpportunityWhereInput[] = [];
  engagementStatuses.forEach((engagementStatus) => {
    if (
      Object.values(CallSubStatus).includes(engagementStatus as CallSubStatus)
    ) {
      engagementStatusWhereInput.push({
        lastEngagement: {
          subStatus: engagementStatus as CallSubStatus,
        },
      });
    } else if (engagementStatus === "conversation") {
      engagementStatusWhereInput.push({
        lastEngagement: {
          subStatus: {
            in: [
              CallSubStatus.candidate_declined,
              CallSubStatus.completed,
              CallSubStatus.partial,
              CallSubStatus.rejected,
            ],
          },
        },
      });
    }
  });

  if (engagementStatusWhereInput.length > 0) {
    whereInputs.push({
      OR: engagementStatusWhereInput,
    });
  }

  const orderBy: Prisma.OpportunityOrderByWithRelationInput[] = [];

  // If a sorting item.id is in this set,
  // we interpret it as the name of a column in the Opportunity table
  // and just order by that column
  const sortableColumns = new Set([
    "createdAt",
    "updatedAt",
    "candidateApplied",
    "recruiterAtsId",
    "recruiterId",
    "candidateId",
    "jobId",
    "salaryRequirementCents",
    "action",
    "actionedAt",
    "paused",
    "pausedReason",
    "assignedToEmail",
    "status",
    "mandatoryRequirementCount",
    "unmetMandatoryRequirementCount",
    "metMandatoryRequirementCount",
    "noDataMandatoryRequirementCount",
    "metPreferredRequirementCount",
  ] as const satisfies (keyof Opportunity)[]);

  // Process sorting options
  const sortingItems =
    opts.sorting
      ?.filter((item) => !item.id.startsWith("lastEngagement"))
      .filter((item) => item.id !== "callScheduledAt") ?? [];

  for (const item of sortingItems) {
    if (item.id === "name") {
      orderBy.push({
        candidate: {
          firstName: item.desc ? "desc" : "asc",
        },
      });
    } else if (item.id === "status") {
      // Handle status sorting by scorecard metrics
      // IMPORTANT: Treat "do not call" candidates as having no scorecard data
      // They should appear at the end when sorting by scorecard

      // First, sort by do not call status (false first, true last)
      orderBy.push({
        candidate: {
          doNotCall: item.desc ? "asc" : "desc",
        },
      });

      // Then sort by scorecard metrics for those without "do not call"
      // When desc is true (down arrow), we want BEST first
      // When desc is false (up arrow), we want WORST first

      // More met requirements = better
      orderBy.push({
        metMandatoryRequirementCount: item.desc ? "desc" : "asc",
      });
      // Fewer unmet requirements = better
      orderBy.push({
        unmetMandatoryRequirementCount: item.desc ? "asc" : "desc",
      });
      // Fewer no data requirements = better
      orderBy.push({
        noDataMandatoryRequirementCount: item.desc ? "asc" : "desc",
      });
      // More met preferred requirements = better
      orderBy.push({
        metPreferredRequirementCount: item.desc ? "desc" : "asc",
      });
      // Use lastEngagement_createdAt as fallback
      orderBy.push({
        lastEngagement: {
          createdAt: item.desc ? "desc" : "asc",
        },
      });
    } else if ((sortableColumns as Set<string>).has(item.id)) {
      orderBy.push({
        [item.id]: item.desc ? "desc" : "asc",
      });
    } else if (item.id.startsWith("scorecard_")) {
      // Handle individual scorecard requirement sorting
      // First sort by do not call status (push do not call to the end)
      orderBy.push({
        candidate: {
          doNotCall: item.desc ? "asc" : "desc",
        },
      });
      // Note: We can't sort by the actual scorecard values at the database level
      // since they're stored in JSON. The sorting happens in memory on the client side.
      // But we ensure "do not call" candidates appear at the end.
    } else {
      console.warn(`Invalid sort field for Opportunity: ${item.id}`);
    }
  }

  const lastEngagementCreatedAtSorting = opts.sorting?.find(
    (filter) => filter.id === "lastEngagement_createdAt",
  );
  if (lastEngagementCreatedAtSorting) {
    orderBy.unshift({
      lastEngagement: {
        createdAt: lastEngagementCreatedAtSorting.desc ? "desc" : "asc",
      },
    });
  }

  const lastEngagementDurationSecondsSorting = opts.sorting?.find(
    (filter) => filter.id === "lastEngagement_durationSeconds",
  );
  if (lastEngagementDurationSecondsSorting) {
    orderBy.unshift({
      lastEngagement: {
        durationSeconds: lastEngagementDurationSecondsSorting.desc
          ? "desc"
          : "asc",
      },
    });
  }

  const callScheduledAtSorting = opts.sorting?.find(
    (filter) => filter.id === "callScheduledAt",
  );

  // TODO Figure this out
  if (callScheduledAtSorting) {
    orderBy.unshift({
      nextOpportunitySequenceItem: {
        scheduledAt: callScheduledAtSorting.desc ? "desc" : "asc",
      },
    });
  }

  // TODO fix order by
  /* if (searchQuery) {
    orderBy.unshift({
      _relevance: {
        fields: ["firstName", "lastName", "email", "phoneNumber"],
        search: searchQuery,
        sort: "desc",
      },
    });
  }

  if (looseSearchQuery) {
    orderBy.unshift({
      _relevance: {
        fields: ["firstName", "lastName"],
        search: looseSearchQuery,
        sort: "desc",
      },
    });
  } */

  const totalCount = opts.skipCount
    ? 0
    : await db.opportunity.count({
        where: {
          AND: whereInputs,
        },
      });

  const groupedByStage = await db.opportunity.groupBy({
    where: {
      jobId: {
        in: jobIds,
      },
    },
    by: ["currentStageId"],
    _count: true,
  });

  const stageCounts = groupedByStage.reduce<Record<string, number>>(
    (acc, curr) => {
      if (curr.currentStageId) {
        acc[curr.currentStageId] = curr._count;
      }
      return acc;
    },
    {},
  );

  // If the page index is out of bounds, return null
  if (pageIndex > 0 && pageIndex * pageSize >= totalCount) {
    return {
      opportunities: null,
      totalCount,
      stageCounts,
    };
  }

  const opportunities = await db.opportunity.findMany({
    where: {
      AND: whereInputs,
    },
    select: {
      id: true,
      candidate: {
        select: {
          id: true,
          firstName: true,
          lastName: true,
          email: true,
          phoneNumber: true,
          addedById: true,
          addedBy: {
            select: {
              firstName: true,
              lastName: true,
            },
          },
          isBot: true,
          doNotCall: true,
        },
      },
      jobId: true,
      createdAt: true,
      candidateApplied: true,
      assignedToEmail: true,
      atsId: true,
      recruiterAtsId: true,
      action: true,
      status: true,
      candidateDeclineReason: true,
      rejectionReason: true,
      currentStageId: true,
      tags: {
        select: {
          tag: {
            select: {
              name: true,
              id: true,
            },
          },
          taggedBy: {
            select: {
              email: true,
              firstName: true,
              lastName: true,
            },
          },
          systemReason: true,
        },
      },
      job: {
        select: {
          id: true,
          organizationId: true,
        },
      },
      lastEngagement: {
        select: {
          createdAt: true,
          durationSeconds: true,
          scoreCard: true,
          id: true,
          status: true,
          subStatus: true,
          roomName: true,
        },
      },
      sequenceItems: {
        select: {
          id: true,
          scheduledAt: true,
          triggeredAt: true,
          cancelledAt: true,
          channel: true,
        },
        orderBy: {
          scheduledAt: "asc",
        },
        where: {
          cancelledAt: null,
        },
      },
      atsCandidateMapping: {
        select: {
          atsExternalId: true,
        },
      },
      source: true,
    },
    orderBy: [
      ...orderBy,
      {
        createdAt: "desc",
      },
    ],
    skip: pageIndex * pageSize,
    take: pageSize,
  });

  const lastAuditLogs = await db.auditLog.groupBy({
    by: ["recordId"],
    where: {
      modelName: "Opportunity",
      recordId: {
        in: opportunities.map((o) => o.id),
      },
    },
    _max: {
      createdAt: true,
    },
  });

  const lastAuditLogReasons = await db.auditLog.findMany({
    where: {
      modelName: "Opportunity",
      recordId: {
        in: opportunities.map((o) => o.id),
      },
      createdAt: {
        in: lastAuditLogs.map((log) => log._max.createdAt!),
      },
    },
    select: {
      recordId: true,
      reason: true,
    },
  });

  const lastAuditLogReasonMap = new Map(
    lastAuditLogReasons.map((log) => [log.recordId, log.reason]),
  );

  const formattedOpportunities = await Promise.all(
    opportunities.map(async (opportunity) => {
      const allSequenceItems = opportunity.sequenceItems;
      const activeSequenceItems = allSequenceItems.filter(
        (item) =>
          item.scheduledAt !== null &&
          item.triggeredAt === null &&
          item.cancelledAt === null,
      );

      const firstActiveItem = activeSequenceItems[0];
      const currentScheduledCallNumber = firstActiveItem
        ? allSequenceItems.findIndex((item) => item.id === firstActiveItem.id) +
          1
        : null;

      return {
        ...opportunity,
        callScheduledAt: activeSequenceItems[0]?.scheduledAt ?? null,
        callScheduledChannel: activeSequenceItems[0]?.channel ?? null,
        numScheduledCalls: activeSequenceItems.length,
        totalSequenceItems: allSequenceItems.length,
        currentScheduledCallNumber,
        lastEngagement: opportunity.lastEngagement
          ? {
              ...opportunity.lastEngagement,
              scoreCard:
                opportunity.lastEngagement.scoreCard != null
                  ? await formatScoreCard(
                      opportunity.lastEngagement.scoreCard as IScoreCard,
                    )
                  : undefined,
            }
          : null,
      };
    }),
  );

  return {
    opportunities: formattedOpportunities.map((opportunity) => {
      return {
        id: opportunity.id,
        job: {
          id: opportunity.jobId,
        },
        callScheduledAt: opportunity.callScheduledAt,
        callScheduledChannel: opportunity.callScheduledChannel,
        numScheduledCalls: opportunity.numScheduledCalls,
        totalSequenceItems: opportunity.totalSequenceItems,
        currentScheduledCallNumber: opportunity.currentScheduledCallNumber,
        candidate: {
          id: opportunity.candidate.id,
          firstName: opportunity.candidate.firstName,
          lastName: opportunity.candidate.lastName,
          email: opportunity.candidate.email,
          phoneNumber: opportunity.candidate.phoneNumber,
          addedBy: null,
          isBot: opportunity.candidate.isBot,
          doNotCall: opportunity.candidate.doNotCall,
          atsId: opportunity.atsCandidateMapping?.atsExternalId ?? null,
        },
        atsCandidateMapping: opportunity.atsCandidateMapping
          ? {
              atsExternalId: opportunity.atsCandidateMapping.atsExternalId,
            }
          : null,
        currentStageId: opportunity.currentStageId,
        lastAuditLogReason: lastAuditLogReasonMap.get(opportunity.id) || null,
        createdAt: opportunity.createdAt,
        assignedToEmail: opportunity.assignedToEmail,
        atsId: opportunity.atsId,
        recruiterAtsId: opportunity.recruiterAtsId,
        addedBy:
          opportunity.candidate.addedBy && opportunity.candidate.addedById
            ? {
                id: opportunity.candidate.addedById,
                firstName: opportunity.candidate.addedBy.firstName || "",
                lastName: opportunity.candidate.addedBy.lastName || "",
              }
            : null,
        candidateApplied: opportunity.candidateApplied || false,
        status: opportunity.status,
        action: opportunity.action as OpportunityAction | null,
        lastEngagement: opportunity.lastEngagement
          ? {
              createdAt: opportunity.lastEngagement.createdAt,
              durationSeconds: opportunity.lastEngagement.durationSeconds,
              scoreCard: opportunity.lastEngagement.scoreCard,
              id: opportunity.lastEngagement.id,
              status: opportunity.lastEngagement.status,
              subStatus: opportunity.lastEngagement.subStatus,
              direction: opportunity.lastEngagement.roomName?.startsWith(
                "profileId:",
              )
                ? "outbound"
                : "inbound",
            }
          : null,
        source: opportunity.source || "",
        jobId: opportunity.job.id,
        organizationId: opportunity.job.organizationId,
        tags: opportunity.tags.map((tag) => ({
          ...tag,
          taggedBy: tag.taggedBy ?? {
            email: "",
            firstName: null,
            lastName: null,
          },
        })),
        candidateDeclineReason: opportunity.candidateDeclineReason,
        rejectionReason: opportunity.rejectionReason,
      };
    }),
    totalCount,
    stageCounts,
  };
};

