export async function callOpportunityImmediately(
  opportunityId: string,
  force = false,
): Promise<{
  called: boolean;
  roomName?: string;
  reason?: string;
} | null> {
  const opportunity = await db.opportunity.findUnique({
    where: {
      id: opportunityId,
    },
    include: {
      candidate: {
        select: {
          id: true,
          phoneNumber: true,
          isBot: true,
          doNotCall: true,
          engagements: {
            select: {
              roomName: true,
            },
            where: {
              createdAt: {
                gte: new Date(Date.now() - 1000 * 60 * 24), // 24 hours
              },
            },
          },
        },
      },
      job: {
        select: {
          id: true,
          status: true,
          resumeCallsEnabled: true,
        },
      },
      tags: {
        include: {
          tag: true,
        },
      },
      engagements: true,
    },
  });

  if (!opportunity) {
    throw new Error(`Opportunity ${opportunityId} not found`);
  }
  if (!opportunity.candidate.phoneNumber) {
    console.info(
      `Opportunity phone number not found for opportunityId: ${opportunityId}, not calling.`,
    );
    return { called: false, reason: "No Phone Number" };
  }

  if (opportunity.candidate.doNotCall) {
    console.warn(
      `Opportunity ${opportunityId} is marked as Do Not Call, not proceeding with call.`,
    );
    return { called: false, reason: "Do Not Call" };
  }

  // If force is false, we need to check if the opportunity is in a valid state to be called
  if (!force) {
    // Add some protection against too many outbound calls.
    if (
      opportunity.engagements.filter(
        (e) => e.roomName?.startsWith("profileId:") === true,
      ).length >= MAX_OUTBOUND_CALLS_PER_OPPORTUNITY
    ) {
      console.log(
        `Opportunity ${opportunityId} has too many outbound engagements, not calling.`,
      );
      return { called: false, reason: "Too Many Outbound Calls" };
    }
    if (
      opportunity.candidate.engagements.filter(
        (e) => e.roomName?.startsWith("profileId:") === true,
      ).length >= MAX_OUTBOUND_CALLS_PER_CANDIDATE_PER_DAY
    ) {
      console.log(
        `Candidate ${opportunity.candidate.id} has too many outbound engagements, not calling.`,
      );
      return { called: false, reason: "Too Many Outbound Calls" };
    }
    // if the opportunity state is success then we no longer need to call this opportunity
    if (
      opportunity.status === OpportunityStatus.completed &&
      !opportunity.candidate.isBot &&
      opportunity.job.resumeCallsEnabled
    ) {
      console.warn(
        `Opportunity ${opportunityId} is already in a success state, not calling.`,
      );
      return { called: false, reason: "Opportunity Already Called" };
    }

    // Only check job status if force is false
    if (opportunity.job.status !== JobStatus.ACTIVE.toString()) {
      console.log(
        "Scheduled call ignored since job is not active for opportunityId",
        opportunityId,
      );
      return { called: false, reason: "Job Not Active" };
    }

    if (!opportunity.candidate.isBot) {
      const engagement = await db.engagement.findFirst({
        where: {
          opportunityId,
        },
        orderBy: {
          createdAt: "desc",
        },
      });

      if (engagement?.status === CallStatus.in_progress) {
        console.log(
          `Another call: ${engagement.id} is already in progress for opportunityId ${opportunityId}, not calling.`,
        );
        return { called: false, reason: "Call Already In Progress" };
      }
    }
  }

  const name = generateRoomName(opportunity.id);

  const roomService = new RoomServiceClient(
    env.LIVEKIT_URL,
    env.LIVEKIT_API_KEY,
    env.LIVEKIT_API_SECRET,
  );

  const room = await roomService.createRoom({ name, emptyTimeout: 60 * 60 });

  console.log(
    `Calling opportunity ${opportunityId} for job ${opportunity.job.id} (room: ${room.name})`,
  );
  return { called: true, roomName: room.name };
}

const scheduleToCallOpportunity = async (
  opportunityId: string,
  scheduledTime: Date,
  opts?: {
    userId?: string;
    skipJitter?: boolean;
  },
) => {
  const opportunity = await db.opportunity.findUniqueOrThrow({
    where: {
      id: opportunityId,
    },
    select: {
      job: {
        select: {
          organizationId: true,
          id: true,
        },
      },
    },
  });

  const existingPendingSequenceItem = await getNextPendingSequenceItem(
    opportunityId,
    SequenceItemChannel.phone,
  );

  let newScheduledDate = scheduledTime;

  // Only add jitter for bulk calls (when skipJitter is false)
  // For single opportunity calls (skipJitter true), use exact requested time
  if (!opts?.skipJitter) {
    newScheduledDate = addRandomMinutesToDate(newScheduledDate, 10);
    console.log(
      `Adding jitter to bulk call for ${opportunityId}. Original time: ${scheduledTime.toISOString()}, New time with jitter: ${newScheduledDate.toISOString()}`,
    );
  }

  // If there is an existing pending sequence item, update it with the new scheduled time
  if (existingPendingSequenceItem) {
    if (opts?.userId) {
      await db.opportunitySequenceItem.update({
        where: { id: existingPendingSequenceItem.id },
        data: {
          triggeredByUserId: opts.userId,
        },
      });
    }

    console.log(
      `Scheduling phone call for opportunity ${opportunityId} at ${newScheduledDate.toISOString()} for job ${opportunity.job.id}`,
    );
    return rescheduleSequenceItem(
      existingPendingSequenceItem.id,
      newScheduledDate,
    );
  } else {
    // Otherwise, create a new sequence item
    // Mark sequenceInitializedAt to prevent automatic full sequence creation
    await db.opportunity.update({
      where: { id: opportunityId },
      data: {
        sequenceInitializedAt: new Date(),
      },
    });

    return createSequenceItem({
      opportunityId,
      channel: SequenceItemChannel.phone,
      scheduledAt: newScheduledDate,
      triggeredByUserId: opts?.userId,
    });
  }
};

export const scheduleToCallOpportunities = async ({
  organizationId,
  opportunityIds,
  scheduledTime,
  userId,
}: {
  organizationId: string;
  opportunityIds: string[];
  scheduledTime: Date | null;
  userId?: string;
}) => {
  const scheduleFullSequence = scheduledTime === null;
  const context = scheduleFullSequence ? "Full sequence" : "Single call";

  console.log(
    `${context} manually scheduled by userId: ${userId} for opportunityId(s): ${opportunityIds.map((id) => id).join(", ")}`,
  );
  await Promise.all(
    opportunityIds.map(async (opportunityId) => {
      // Validate that the opportunity belongs to the organization
      const opportunity = await db.opportunity.findUniqueOrThrow({
        where: {
          id: opportunityId,
          job: {
            organizationId,
          },
        },
      });

      return scheduleFullSequence
        ? populateSequenceItems(opportunity.id)
        : scheduleToCallOpportunity(opportunity.id, scheduledTime, {
            userId,
            skipJitter: opportunityIds.length === 1,
          });
    }),
  );
  return true;
};

export async function cancelScheduledCalls(
  organizationId: string,
  opportunityIds: string[],
  cancelledReason: string,
) {
  await Promise.all(
