async function getOpportunityStatus(
  opportunityId: string,
): Promise<OpportunityStatus> {
  // Compute the status of the opportunity based on the latest engagement
  const engagements = await db.engagement.findMany({
    where: { opportunityId },
    orderBy: { createdAt: "desc" },
  });

  // If there are no engagements, the opportunity is not contacted
  if (engagements.length < 1) {
    return OpportunityStatus.not_contacted;
  }

  // A opportunity is considered completed if it has at least one completed engagement
  const completedEngagements = engagements.filter(
    (e) => e.status === CallStatus.completed,
  );

  if (completedEngagements.length > 0) {
    // If the candidate has not recently declined the job in the most recent call, the opportunity is considered completed
    if (
      completedEngagements[0]?.subStatus !== CallSubStatus.candidate_declined
    ) {
      return OpportunityStatus.completed;
    } else {
      // Otherwise, consider that the candidate declined the job
      return OpportunityStatus.candidate_declined;
    }
  }

  const remainingSequenceItems = await getRemainingSequenceItems(opportunityId);

  if (remainingSequenceItems === 0) {
    return OpportunityStatus.sequence_ended;
  }

  return OpportunityStatus.in_progress;
}

export async function computeOpportunityStatus(
  opportunityId: string,
): Promise<OpportunityStatus> {
  // Capture previous status for audit logging
  const prev = await db.opportunity.findUnique({
    where: { id: opportunityId },
    select: { status: true },
  });

  const status = await getOpportunityStatus(opportunityId);

  const lastEngagement = await db.engagement.findFirst({
    where: { opportunityId },
    orderBy: { createdAt: "desc" },
  });

  await db.opportunity.update({
    where: { id: opportunityId },
    data: { status, lastEngagementId: lastEngagement?.id },
  });

  // Audit status change if it changed
  if (prev && prev.status !== status) {
    await createAuditLog({
      userId: null,
      action: "UPDATE",
      modelName: "Opportunity",
      recordId: opportunityId,
      reason: "Status recomputed from engagements",
      changes: {
        title: "Status updated",
        from: prev.status,
        to: status,
        lastEngagementId: lastEngagement?.id ?? null,
      },
    });
  }

  // If the opportunity is completed, check if the candidate was rejected
  // If so, review the opportunity as rejected
  if (status === OpportunityStatus.completed) {
    const rejectedEngagement = await db.engagement.findFirst({
      where: {
        opportunityId,
        subStatus: CallSubStatus.rejected,
      },
      select: {
        opportunity: {
          select: {
            id: true,
            job: {
              select: { organizationId: true },
            },
          },
        },
      },
    });
    if (rejectedEngagement?.opportunity) {
      const opportunity = await db.opportunity.findUniqueOrThrow({
        where: { id: rejectedEngagement.opportunity.id },
      });

      // Avoid auto-reviewing opportunities that have already been actioned
      if (!opportunity.actionedAt) {
        await reviewOpportunity(
          rejectedEngagement.opportunity.job.organizationId,
          rejectedEngagement.opportunity.id,
          OpportunityAction.REJECTED,
        );
      }
    }
  }

  return status;
}

export async function computeOpportunityRequirementCounts(
  opportunityId: string,
): Promise<{
  mandatoryRequirementCount: number;
  unmetMandatoryRequirementCount: number;
  metMandatoryRequirementCount: number;
  noDataMandatoryRequirementCount: number;
  metPreferredRequirementCount: number;
}> {
  // Compute the status of the profile based on the latest engagement
  const engagements = await db.engagement.findMany({
    where: { opportunityId },
    orderBy: { createdAt: "desc" },
  });

  const completedEngagement = engagements.find(
    (e) => e.status === CallStatus.completed,
  );

  // If there are no completed engagements, return 0 for all counts
  if (!completedEngagement) {
    return {
      mandatoryRequirementCount: 0,
      unmetMandatoryRequirementCount: 0,
      metMandatoryRequirementCount: 0,
      noDataMandatoryRequirementCount: 0,
      metPreferredRequirementCount: 0,
    };
  }

  let mandatoryRequirementCount = 0;
  let unmetMandatoryRequirementCount = 0;
  let metMandatoryRequirementCount = 0;
  let noDataMandatoryRequirementCount = 0;
  let metPreferredRequirementCount = 0;

  const lastEngagement = engagements[0];
  if (lastEngagement) {
    const scoreCard = lastEngagement.scoreCard as IScoreCard | null;
    const scores = scoreCard?.scores ?? [];

    const mandatoryScores = scores.filter(
      (s) => s.type === JobQualificationType.MANDATORY,
    );
    const metMandatoryScores = mandatoryScores.filter((s) => s.score === "Met");
    const unmetMandatoryScores = mandatoryScores.filter(
      (s) => s.score === "Did not meet",
    );
    const noDataMandatoryScores = mandatoryScores.filter(
      (s) => s.score === "No data",
    );
    const preferredScores = scores.filter(
      (s) => s.type === JobQualificationType.PREFERRED,
    );
    const metPreferredScores = preferredScores.filter((s) => s.score === "Met");

    mandatoryRequirementCount = mandatoryScores.length;
    unmetMandatoryRequirementCount = unmetMandatoryScores.length;
    metMandatoryRequirementCount = metMandatoryScores.length;
    noDataMandatoryRequirementCount = noDataMandatoryScores.length;
    metPreferredRequirementCount = metPreferredScores.length;
  }

  return {
    mandatoryRequirementCount,
    unmetMandatoryRequirementCount,
    metMandatoryRequirementCount,
    noDataMandatoryRequirementCount,
    metPreferredRequirementCount,
  };
}

export async function createOpportunityForInboundCall(
  candidateNumber: string,
  agentNumber: string | null,
): Promise<OpportunityWithRelations | null> {
  // Find the agent's phone number and its default job
  const agentPhoneNumber = agentNumber
    ? await db.agentPhoneNumber.findFirst({
        where: {
          number: agentNumber,
          defaultJobId: { not: null },
        },
        include: {
          defaultJob: true,
        },
      })
    : null;

  if (!agentPhoneNumber?.defaultJob) {
    // No default job, so ignore.
    return null;
  }

  // Create a new opportunity
  console.log(
    `Creating new opportunity for inbound call for agentNumber ${agentPhoneNumber.number} and candidateNumber ${candidateNumber}`,
  );

  const candidateResult = await createCandidate({
    organizationId: agentPhoneNumber.defaultJob.organizationId,
    data: {
      phoneNumber: candidateNumber,
      firstName: "Unknown",
      lastName: "Caller",
      organization: {
        connect: {
          id: agentPhoneNumber.defaultJob.organizationId,
        },
      },
    },
  });

  const opportunity = await createOpportunity({
    organizationId: agentPhoneNumber.defaultJob.organizationId,
    data: {
      candidate: {
        connect: {
          id: candidateResult.candidate.id,
        },
      },
      job: {
        connect: { id: agentPhoneNumber.defaultJob.id },
      },
      source: "cold call",
      agentPhoneNumber: {
        connect: {
          id: agentPhoneNumber.id,
        },
      },
    },
  });

  // Get the full opportunity data
  return await getOpportunityWithRelations({ opportunityId: opportunity.id });
}

export async function getOpportunityLastInProgressScriptNodeId(
  opportunityId: string,
  isBot: boolean,
  resumeCallsEnabled: boolean,
  scriptNodes: ScriptNode[],
) {
  if (isBot || !resumeCallsEnabled) {
    // Treat every engagement as new.
    return null;
  }

  // Filter to only top level nodes.
  scriptNodes = scriptNodes.filter((node) => !node.conditionToEnter);

  // Find all the tasks we popped.
  const completedEvents = await db.engagementAgentTaskEvent.findMany({
    where: {
      engagement: {
        opportunityId,
      },
      type: EngagementAgentTaskEventType.task_popped,
    },
  });

  // If we didn't pop any tasks, resume from the very beginning.
  if (completedEvents.length === 0) {
    return null;
  }

  // Otherwise, find the _first_ node we didn't pop.
  for (const scriptNode of scriptNodes) {
    const completedEvent = completedEvents.find(
      (event) => event.taskId === scriptNode.id,
    );
    if (!completedEvent) {
      return scriptNode.id;
    }
  }

  // If we popped everything, just resume from the very end so the agent says something.
  return scriptNodes[scriptNodes.length - 1]?.id || null;
}

// Remove an opportunity and all its related data
/**
 * Checks if a sequence has completed and handles the opportunity status accordingly.
 * A sequence is considered complete when all items are either triggered or cancelled.
 *
 * @param opportunityId - The ID of the opportunity to check
 * @param lastProcessedItemId - The ID of the sequence item that was just processed
 * @returns true if the sequence was marked as ended, false otherwise
 */
export const checkAndHandleSequenceCompletion = async ({
  opportunityId,
  lastProcessedItemId,
}: {
  opportunityId: string;
  lastProcessedItemId: string;
}): Promise<boolean> => {
  // Get all sequence items for this opportunity
  // Order by scheduledAt to get them in sequence order
  const sequenceItems = await db.opportunitySequenceItem.findMany({
    where: { opportunityId },
    orderBy: { scheduledAt: "asc" },
  });

  if (sequenceItems.length === 0) {
    return false;
  }

  // Check if all items are either triggered or cancelled
  const allItemsProcessed = sequenceItems.every(
    (item) => item.triggeredAt !== null || item.cancelledAt !== null,
  );

  if (!allItemsProcessed) {
    return false;
  }

  // Find the last sequence item that was just processed
  const lastProcessedItem = sequenceItems.find(
    (item) => item.id === lastProcessedItemId,
  );

  if (!lastProcessedItem) {
    return false;
  }

  // Get the last item in the sequence by order
  const lastSequenceItem = sequenceItems[sequenceItems.length - 1];
  if (!lastSequenceItem) {
    return false;
  }
  const isLastItem = lastProcessedItem.id === lastSequenceItem.id;

  // Determine if we should end the sequence based on the rules:
  // 1. If it's the last item and it's email/SMS, end immediately
  // 2. If it's the last item and it's phone that was cancelled (missing number), end immediately
  // 3. If all items are processed but last item was phone with number, let engagement handle it
  const shouldEndSequence =
    isLastItem &&
    (lastProcessedItem.channel === "email" ||
      lastProcessedItem.channel === "sms" ||
      lastProcessedItem.cancelledAt !== null);

  // Also end sequence if all items are cancelled (no successful outreach)
  const allItemsCancelled = sequenceItems.every(
    (item) => item.cancelledAt !== null,
  );

  if (shouldEndSequence || allItemsCancelled) {
    // Get the opportunity with job info for organization context
    const opportunity = await db.opportunity.findUnique({
      where: { id: opportunityId },
      select: {
        status: true,
        job: {
          select: {
            organizationId: true,
          },
        },
      },
    });

    if (!opportunity) {
      return false;
    }

    // Only update if not already in a terminal state
    if (
      opportunity.status !== OpportunityStatus.sequence_ended &&
      opportunity.status !== OpportunityStatus.completed &&
      opportunity.status !== OpportunityStatus.candidate_declined
    ) {
      console.log(
        `Marking opportunity ${opportunityId} as sequence_ended after processing last item ${lastProcessedItemId}`,
      );

      await updateOpportunity({
        organizationId: opportunity.job.organizationId,
        opportunityId,
        data: {
          status: OpportunityStatus.sequence_ended,
        },
      });

      // Trigger the stage transition which will archive the opportunity
      await moveOpportunityToNextStage({ opportunityId });

      return true;
    }
  }

  return false;
};

export const removeOpportunity = async ({
  organizationId,
  opportunityId,
}: {
  organizationId: string;
  opportunityId: string;
}) => {
  const opportunity = await db.opportunity.findUniqueOrThrow({
    where: { id: opportunityId },
    include: {
      job: {
        select: {
          organizationId: true,
        },
      },
    },
  });

  if (opportunity.job.organizationId !== organizationId) {
    throw new Error(
      "Unauthorized - opportunity does not belong to this organization",
    );
  }

  await db.opportunity.delete({
    where: { id: opportunityId },
  });

  return true;
};

