import { z } from "zod";

import { OpportunityStatus } from "@purplefish-ai/db";
import { db } from "@purplefish-ai/db/server";

import {
  bulkAddOpportunities,
  cancelScheduledCalls,
  createOpportunity,
  findExistingOpportunity,
  removeOpportunity,
  reviewOpportunities,
  reviewOpportunity,
  scheduleToCallOpportunities,
  updateOpportunity,
} from "@/server/libs/opportunities";
import { OpportunityAction } from "@/server/libs/types";

import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { router } from "../trpc";

export const opportunityRouter = router({
  getOpportunity: organizationMemberProcedure
    .input(z.object({ opportunityId: z.string() }))
    .query(async ({ input }) => {
      const { opportunityId, organizationId } = input;

      const opportunity = await db.opportunity.findUnique({
        where: {
          id: opportunityId,
          job: {
            organizationId,
          },
        },
        include: {
          candidate: {
            select: {
              phoneNumber: true,
              firstName: true,
              lastName: true,
              doNotCall: true,
            },
          },
          tags: {
            select: {
              tag: {
                select: {
                  name: true,
                  id: true,
                },
              },
              taggedBy: {
                select: {
                  email: true,
                  firstName: true,
                  lastName: true,
                },
              },
              systemReason: true,
            },
          },
        },
      });

      if (!opportunity) {
        throw new Error(`Opportunity ${opportunityId} not found`);
      }

      return opportunity;
    }),

  createOpportunity: organizationMemberProcedure
    .input(
      z.object({
        candidateId: z.string(),
        jobId: z.string(),
        data: z.object({
          recruiterAtsId: z.string().nullable().optional(),
          assignedToEmail: z.string().nullable().optional(),
          atsId: z.string().nullable().optional(),
          atsCandidateMappingId: z.string().nullable().optional(),
        }),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { candidateId, jobId, data, organizationId } = input;
      const { user } = ctx;

      const existingOpportunity = await findExistingOpportunity({
        candidateId,
        jobId,
      });

      if (existingOpportunity) {
        throw new Error("Opportunity already exists for this candidate");
      }

      const { atsCandidateMappingId, ...opportunityData } = data;
      const result = await createOpportunity({
        organizationId,
        data: {
          ...opportunityData,
          candidate: {
            connect: {
              id: candidateId,
            },
          },
          job: {
            connect: { id: jobId },
          },
          addedBy: {
            connect: { id: user.id },
          },
        },
        atsCandidateMappingId: atsCandidateMappingId || undefined,
      });

      console.log(
        `Manually created opportunityId ${result.id} for candidateId ${candidateId} and jobId ${jobId} by user ${user.id}`,
      );

      return result;
    }),

  updateOpportunity: organizationMemberProcedure
    .input(
      z.object({
        opportunityId: z.string(),
        data: z.object({
          recruiterAtsId: z.string().nullable().optional(),
          assignedToEmail: z.string().nullable().optional(),
          atsId: z.string().nullable().optional(),
          atsCandidateMappingId: z.string().nullable().optional(),
          status: z.nativeEnum(OpportunityStatus).optional(),
        }),
      }),
    )
    .mutation(async ({ input }) => {
      const { opportunityId, data, organizationId } = input;
      const { atsCandidateMappingId, ...updateData } = data;

      const result = await updateOpportunity({
        organizationId,
        opportunityId,
        data: {
          ...updateData,
          ...(atsCandidateMappingId !== undefined && {
            atsCandidateMapping: atsCandidateMappingId
              ? { connect: { id: atsCandidateMappingId } }
              : { disconnect: true },
          }),
        },
      });

      return result;
    }),

  removeOpportunity: organizationMemberProcedure
    .input(z.object({ opportunityId: z.string() }))
    .mutation(async ({ input }) => {
      const { opportunityId, organizationId } = input;

      const result = await removeOpportunity({
        organizationId,
        opportunityId,
      });

      return result;
    }),

  bulkAddOpportunities: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        opportunities: z.array(
          z.object({
            firstName: z.string(),
            lastName: z.string(),
            email: z.string().nullish(),
            phoneNumber: z.string().nullish(),
            candidateAtsId: z.string().nullish(),
            recruiterAtsId: z.string().nullish(),
            assignedToEmail: z.string().nullish(),
            opportunityAtsId: z.string().nullish(),
            source: z.string().nullish(),
            timezone: z.string().nullish(),
          }),
        ),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { user } = ctx;
      const { jobId, opportunities, organizationId } = input;

      return await bulkAddOpportunities({
        organizationId,
        jobId,
        opportunities: opportunities.map((opportunity) => ({
          ...opportunity,
          email: opportunity.email ?? undefined,
          phoneNumber: opportunity.phoneNumber ?? undefined,
          candidateAtsId: opportunity.candidateAtsId ?? undefined,
          recruiterAtsId: opportunity.recruiterAtsId ?? undefined,
          assignedToEmail: opportunity.assignedToEmail ?? undefined,
          opportunityAtsId: opportunity.opportunityAtsId ?? undefined,
          source: opportunity.source ?? undefined,
          timezone: opportunity.timezone ?? undefined,
        })),
        addedByUserId: user.id,
      });
    }),

  scheduleToCallOpportunities: organizationMemberProcedure
    .input(
      z.object({
        opportunityIds: z.array(z.string()),
        scheduledTime: z.date().optional(),
      }),
    )
    .output(z.boolean())
    .mutation(async ({ input, ctx }) => {
      const { opportunityIds, scheduledTime, organizationId } = input;
      const { user } = ctx;

      return await scheduleToCallOpportunities({
        organizationId,
        opportunityIds,
        scheduledTime: scheduledTime ?? null,
        userId: user.id,
      });
    }),

  cancelScheduledCalls: organizationMemberProcedure
    .input(
      z.object({
        opportunityIds: z.array(z.string()),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { opportunityIds, organizationId } = input;
      const { user } = ctx;
      return await cancelScheduledCalls(
        organizationId,
        opportunityIds,
        `"Cancelled by ${user.email} (${user.id})"`,
      );
    }),

  reviewOpportunity: organizationMemberProcedure
    .input(
      z.object({
        opportunityId: z.string(),
        action: z.nativeEnum(OpportunityAction).nullable(),
      }),
    )
    .mutation(async ({ input }) => {
      const { opportunityId, action, organizationId } = input;

      return await reviewOpportunity(organizationId, opportunityId, action);
    }),

  reviewOpportunities: organizationMemberProcedure
    .input(
      z.object({
        opportunityIds: z.array(z.string()),
        action: z.enum(["advanced", "rejected"]).nullable(),
      }),
    )
    .mutation(async ({ input }) => {
      const { opportunityIds, action, organizationId } = input;

      return await reviewOpportunities(organizationId, opportunityIds, action);
    }),

  bulkUpdateOpportunities: organizationMemberProcedure
    .input(
      z.object({
        opportunityIds: z.array(z.string()),
        data: z.object({
          status: z.nativeEnum(OpportunityStatus).optional(),
        }),
      }),
    )
    .mutation(async ({ input }) => {
      const { opportunityIds, data, organizationId } = input;

      const results = await Promise.all(
        opportunityIds.map((opportunityId) =>
          updateOpportunity({
            organizationId,
            opportunityId,
            data,
          }),
        ),
      );

      return results;
    }),
});

