import { z } from "zod";

import { CallSubStatus } from "@purplefish-ai/db";
import { db } from "@purplefish-ai/db/server";

import { getCallStatusFromSubstatus } from "@/common/libs/get-call-status-from-substatus";
import { createAuditLog, toSafeJson } from "@/server/libs/audit-trail";
import { computeOpportunityStatus } from "@/server/libs/opportunities";

import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { router } from "../trpc";

export const engagementRouter = router({
  updateEngagementStatus: organizationMemberProcedure
    .input(
      z.object({
        engagementId: z.string(),
        newSubStatus: z.nativeEnum(CallSubStatus),
        reason: z.string().optional(),
      }),
    )
    .output(z.boolean())
    .mutation(async ({ input, ctx }) => {
      const { reason, newSubStatus, engagementId, organizationId } = input;
      const userId = ctx.user.id;

      // Find the engagement and verify it exists and belongs to the organization
      const engagement = await db.engagement.findUniqueOrThrow({
        where: {
          id: engagementId,
          opportunity: { job: { organizationId } },
        },
        include: {
          opportunity: {
            select: {
              id: true,
              status: true,
            },
          },
        },
      });

      if (!engagement.opportunity) {
        throw new Error(
          `Opportunity not found for engagementId: ${engagementId}`,
        );
      }

      const currentStatus = engagement.status;
      const currentSubStatus = engagement.subStatus;

      // If status is not changing and subStatus is not changing, do nothing
      if (currentSubStatus === newSubStatus) {
        return true;
      }

      // Calculate new status from substatus
      const newStatus = getCallStatusFromSubstatus(newSubStatus);

      // Update the engagement
      await db.engagement.update({
        where: { id: engagementId },
        data: {
          status: newStatus,
          subStatus: newSubStatus,
        },
      });

      // Create audit log for the status change
      const changes: Record<string, unknown> = {};

      if (currentStatus !== newStatus) {
        changes.status = {
          from: currentStatus,
          to: newStatus,
        };
      }

      if (currentSubStatus !== newSubStatus) {
        changes.subStatus = {
          from: currentSubStatus,
          to: newSubStatus,
        };
      }

      if (Object.keys(changes).length > 0) {
        await createAuditLog({
          userId,
          action: "UPDATE",
          modelName: "Engagement",
          recordId: engagementId,
          reason:
            reason ||
            `Substatus changed from ${currentSubStatus} to ${newSubStatus}. Status changed from ${currentStatus} to ${newStatus}`,
          changes: toSafeJson(changes),
        });
      }

      // Recompute the opportunity status after the engagement status change
      await computeOpportunityStatus(engagement.opportunity.id);

      return true;
    }),
});

