      return await updateJobIntegration({
        organizationId,
        jobId,
        atsId,
        clientId,
        source,
      });
    }),

  updateWebScreeningSteps: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        steps: z.array(webScreeningStepSchema).nullable(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, steps } = input;

      // Verify the job exists and belongs to the organization
      const job = await db.job.findFirst({
        where: {
          id: jobId,
          organizationId,
        },
        select: {
          publicAccessEnabledAt: true,
        },
      });

      if (!job) {
        throw new Error("Job not found");
      }

      if (!job.publicAccessEnabledAt) {
        throw new Error(
          "Public access must be enabled to configure web conversation steps",
        );
      }

      // Update the job with the new steps
      await db.job.update({
        where: { id: jobId },
        data: {
          webScreeningSteps: steps,
        },
      });

      return { success: true };
    }),

  updateWebScreeningAuthSettings: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        allowedEmailDomains: z.array(z.string()).optional(),
        allowedVerificationMethods: z
          .array(z.enum(["email", "sms"]))
          .min(1, "At least one verification method must be selected")
          .optional(),
      }),
    )
    .mutation(async ({ input }) => {
      const {
        organizationId,
        jobId,
        allowedEmailDomains,
        allowedVerificationMethods,
      } = input;

      // Verify the job exists and belongs to the organization
      const job = await db.job.findFirst({
        where: {
          id: jobId,
          organizationId,
        },
        select: {
          publicAccessEnabledAt: true,
        },
      });

      if (!job) {
        throw new Error("Job not found");
      }

      if (!job.publicAccessEnabledAt) {
        throw new Error(
          "Public access must be enabled to configure authentication settings",
        );
      }

      // Update the job with the new authentication settings
      // Convert empty arrays to null to properly clear the restrictions
      await db.job.update({
        where: { id: jobId },
        data: {
          allowedEmailDomains:
            allowedEmailDomains && allowedEmailDomains.length > 0
              ? allowedEmailDomains
              : null,
          allowedVerificationMethods:
            allowedVerificationMethods && allowedVerificationMethods.length > 0
              ? allowedVerificationMethods
              : null,
        },
      });

      return { success: true };
    }),
});

