import { z } from "zod";

import { db } from "@purplefish-ai/db/server";

import { createSession } from "@/auth";
import { sanitizeRedirectPath } from "@/common/libs/utils";
import { sendMagicLinkEmail } from "@/server/libs/emails";
import { validateOtp, validateToken } from "@/server/libs/tokens";

import { publicProcedure } from "../procedures/public-procedure";
import { router } from "../trpc";

export const authRouter = router({
  requestAuthToken: publicProcedure
    .input(
      z.object({
        email: z.string().email(),
        redirectPath: z.string().optional(),
      }),
    )
    .mutation(async ({ input }) => {
      const { email, redirectPath } = input;

      const user = await db.user.findUnique({
        where: {
          email: email.trim().toLowerCase(),
        },
        include: {
          organization: true,
        },
      });

      if (!user) {
        return null;
      }

      const { tokenId } = await sendMagicLinkEmail(user, user.organization);

      return {
        destination: `/verify-request?tokenId=${tokenId}&redirectPath=${encodeURIComponent(
          redirectPath ?? "/",
        )}`,
      };
    }),
  signInWithMagicLinkToken: publicProcedure
    .input(z.object({ token: z.string() }))
    .mutation(async ({ input }) => {
      const { token } = input;
      const user = await validateToken(token);
      await createSession(user);
      return {
        destination: "/",
      };
    }),

  signInWithOtp: publicProcedure
    .input(
      z.object({
        tokenId: z.string(),
        otp: z.string(),
        redirectPath: z.string().optional(),
      }),
    )
    .mutation(async ({ input }) => {
      const { tokenId, otp, redirectPath } = input;

      const sanitizedRedirectPath = sanitizeRedirectPath(redirectPath);
      const user = await validateOtp(tokenId, otp);
      await createSession(user);
      return {
        destination: sanitizedRedirectPath,
      };
    }),
});

