import { z } from "zod";

import { db } from "@purplefish-ai/db/server";

import { isOrganizationAdmin, isSystemAdmin } from "@/server/libs/permissions";
import {
  createUser,
  deleteUser,
  updateUser,
  updateUserById,
} from "@/server/libs/users";

import { authedProcedure } from "../procedures/authed-procedure";
import { organizationAdminProcedure } from "../procedures/organization-admin-procedure";
import { router } from "../trpc";

export const userRouter = router({
  createUser: organizationAdminProcedure
    .input(
      z.object({
        email: z.string().email(),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { organizationId, email } = input;
      const userId = ctx.user.id;
      return await createUser(organizationId, email, userId);
    }),

  deleteUser: organizationAdminProcedure
    .input(
      z.object({
        id: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, id } = input;
      return await deleteUser(organizationId, id);
    }),

  updateUser: authedProcedure
    .input(
      z.object({
        firstName: z.string().optional(),
        lastName: z.string().optional(),
        atsId: z.string().optional(),
        phoneNumber: z.string().optional(),
        optIn10DLCAt: z.date().nullable().optional(),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { firstName, lastName, atsId, phoneNumber, optIn10DLCAt } = input;
      return await updateUser(ctx.user.id, {
        firstName,
        lastName,
        atsId,
        phoneNumber,
        optIn10DLCAt,
      });
    }),

  updateUserById: authedProcedure
    .input(
      z.object({
        organizationId: z.string(),
        userId: z.string(),
        data: z.object({
          firstName: z.string().optional(),
          lastName: z.string().optional(),
          atsId: z.string().optional(),
          phoneNumber: z.string().optional(),
        }),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { organizationId, userId, data } = input;

      // Check permissions
      const isSystem = await isSystemAdmin(ctx.user);
      const isOrgAdmin = await isOrganizationAdmin(organizationId, ctx.user);
      const isSelf = userId === ctx.user.id;

      if (!isSystem && !isOrgAdmin && !isSelf) {
        throw new Error("You don't have permission to edit this user");
      }

      // If not admin, can only edit self
      if (!isSystem && !isOrgAdmin && userId !== ctx.user.id) {
        throw new Error("You can only edit your own information");
      }

      // If org admin, can only edit users in their org
      if (!isSystem && isOrgAdmin) {
        const targetUser = await db.user.findUnique({
          where: { id: userId },
        });
        if (!targetUser || targetUser.organizationId !== organizationId) {
          throw new Error("User not found in your organization");
        }
      }

      return await updateUserById(userId, data);
    }),

  updateUserCloser: organizationAdminProcedure
    .input(
      z.object({
        userId: z.string(),
        closerId: z.string().nullable(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, userId, closerId } = input;

      const user = await db.user.update({
        where: {
          id: userId,
          organizationId,
        },
        data: {
          closerId: closerId,
        },
        include: {
          organization: true,
        },
      });

      return user;
    }),
});

