import jwt from "jsonwebtoken";
import { z } from "zod";

import { db } from "@purplefish-ai/db/server";

import { env } from "@/env";
import {
  deleteAtsCandidateMappingById,
  findOrCreateAtsCandidateMapping,
  getCandidateAtsMappings,
} from "@/server/libs/ats-candidate-mappings";
import {
  createAuditLog,
  getAuditLogsForCandidate,
} from "@/server/libs/audit-trail";
import {
  createCandidate,
  getCandidate,
  setCandidateDoNotCall,
  updateCandidate,
} from "@/server/libs/candidates";

import { authedProcedure } from "../procedures/authed-procedure";
import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { router } from "../trpc";

export const candidateRouter = router({
  getCandidate: organizationMemberProcedure
    .input(z.object({ candidateId: z.string() }))
    .query(async ({ input }) => {
      const { candidateId, organizationId } = input;

      return await getCandidate({ organizationId, candidateId });
    }),

  createCandidate: organizationMemberProcedure
    .input(
      z.object({
        data: z.object({
          firstName: z.string(),
          lastName: z.string(),
          email: z.string().nullish(),
          phoneNumber: z.string().nullish(),
        }),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { data, organizationId } = input;
      const { user } = ctx;

      return await createCandidate({
        organizationId,
        data: {
          ...data,
          organization: {
            connect: { id: organizationId },
          },
          addedBy: {
            connect: { id: user.id },
          },
        },
        userId: user.id,
      });
    }),

  updateCandidate: organizationMemberProcedure
    .input(
      z.object({
        candidateId: z.string(),
        data: z.object({
          firstName: z.string(),
          lastName: z.string(),
          email: z.string().nullish(),
          phoneNumber: z.string().nullish(),
          doNotCall: z.boolean(),
        }),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { candidateId, data, organizationId } = input;
      const { user } = ctx;

      if (data.phoneNumber) {
        const candidate = await db.candidate.findFirst({
          where: {
            organizationId,
            phoneNumber: data.phoneNumber,
          },
        });

        if (candidate && candidate.id !== candidateId) {
          throw new Error("Candidate already exists with this phone number");
        }
      }

      return await updateCandidate({
        organizationId,
        candidateId,
        data,
        userId: user.id,
      });
    }),

  setCandidateDoNotCall: organizationMemberProcedure
    .input(z.object({ candidateId: z.string(), doNotCall: z.boolean() }))
    .mutation(async ({ input, ctx }) => {
      const { candidateId, doNotCall, organizationId } = input;
      const { user } = ctx;

      const candidate = await setCandidateDoNotCall({
        organizationId,
        candidateId,
        userId: user.id,
        doNotCall,
        reason: "Candidate was manually marked as do not call",
      });

      return candidate;
    }),

  searchCandidates: organizationMemberProcedure
    .input(z.object({ query: z.string() }))
    .query(async ({ input }) => {
      const { query, organizationId } = input;

      const candidates = await db.candidate.findMany({
        where: {
          organizationId,
          OR: [
            {
              firstName: {
                contains: query,
                mode: "insensitive",
              },
            },
            {
              lastName: {
                contains: query,
                mode: "insensitive",
              },
            },
            {
              email: {
                contains: query,
                mode: "insensitive",
              },
            },
            {
              phoneNumber: {
                contains: query,
                mode: "insensitive",
              },
            },
          ],
        },
        take: 10,
      });

      return candidates;
    }),

  getCandidateAtsMappings: organizationMemberProcedure
    .input(z.object({ candidateId: z.string() }))
    .query(async ({ input }) => {
      const { candidateId } = input;

      return await getCandidateAtsMappings(candidateId);
    }),

  getCandidateAuditLogs: organizationMemberProcedure
    .input(z.object({ candidateId: z.string() }))
    .query(async ({ input }) => {
      const { candidateId } = input;
      return await getAuditLogsForCandidate(candidateId);
    }),

  getAvailableAtsIntegrations: organizationMemberProcedure.query(
    async ({ input }) => {
      const { organizationId } = input;

      return await db.atsIntegration.findMany({
        where: {
          organizationId,
        },
        select: {
          id: true,
          name: true,
        },
        orderBy: {
          name: "asc",
        },
      });
    },
  ),

  addAtsCandidateMapping: organizationMemberProcedure
    .input(
      z.object({
        candidateId: z.string(),
        atsIntegrationId: z.string(),
        atsExternalId: z.string(),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { candidateId, atsIntegrationId, atsExternalId, organizationId } =
        input;
      const { user } = ctx;

      // Verify the ATS integration belongs to the organization
      const atsIntegration = await db.atsIntegration.findFirst({
        where: {
          id: atsIntegrationId,
          organizationId,
        },
      });

      if (!atsIntegration) {
        throw new Error("ATS integration not found or unauthorized");
      }

      // Check if another candidate already has this ATS ID
      const existingMapping = await db.atsCandidateMapping.findFirst({
        where: {
          atsIntegrationId,
          atsExternalId,
        },
      });

      if (existingMapping && existingMapping.candidateId !== candidateId) {
        throw new Error(
          "Another candidate already has this ATS ID for this integration",
        );
      }

      return await findOrCreateAtsCandidateMapping({
        candidateId,
        atsIntegrationId,
        atsExternalId,
        userId: user.id,
      });
    }),

  updateAtsCandidateMapping: organizationMemberProcedure
    .input(
      z.object({
        candidateId: z.string(),
        atsIntegrationId: z.string(),
        atsExternalId: z.string(),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { candidateId, atsIntegrationId, atsExternalId, organizationId } =
        input;
      const { user } = ctx;

      console.log("[UPDATE] Starting update with:", {
        candidateId,
        atsIntegrationId,
        atsExternalId,
        organizationId,
      });

      // Verify the mapping exists and the ATS integration belongs to the organization
      const existingMapping = await db.atsCandidateMapping.findFirst({
        where: {
          candidateId,
          atsIntegrationId,
        },
        include: {
          atsIntegration: {
            select: {
              id: true,
              organizationId: true,
            },
          },
        },
      });

      if (!existingMapping) {
        throw new Error("ATS mapping not found");
      }

      if (existingMapping.atsIntegration.organizationId !== organizationId) {
        throw new Error("ATS mapping not found or unauthorized");
      }

      // Check if another candidate already has this ATS ID
      const conflictingMapping = await db.atsCandidateMapping.findFirst({
        where: {
          atsIntegrationId,
          atsExternalId,
        },
      });

      if (
        conflictingMapping &&
        conflictingMapping.candidateId !== candidateId
      ) {
        throw new Error(
          "Another candidate already has this ATS ID for this integration",
        );
      }

      // Update the existing mapping with the new atsExternalId
      console.log("[UPDATE] Updating mapping:", {
        mappingId: existingMapping.id,
        oldAtsExternalId: existingMapping.atsExternalId,
        newAtsExternalId: atsExternalId,
      });

      const updatedMapping = await db.atsCandidateMapping.update({
        where: {
          id: existingMapping.id,
        },
        data: {
          atsExternalId,
        },
        include: {
          atsIntegration: {
            select: {
              name: true,
            },
          },
        },
      });

      // Create audit log for updated ATS mapping
      await createAuditLog({
        userId: user.id,
        action: "UPDATE",
        modelName: "Candidate",
        recordId: candidateId,
        reason: "ATS mapping updated",
        changes: {
          atsMappingUpdated: {
            atsIntegration: updatedMapping.atsIntegration.name,
            oldAtsExternalId: existingMapping.atsExternalId,
            newAtsExternalId: atsExternalId,
          },
        },
      });

      console.log("[UPDATE] Successfully updated mapping:", updatedMapping);
      return updatedMapping;
    }),

  deleteAtsCandidateMapping: organizationMemberProcedure
    .input(
      z.object({
        candidateId: z.string(),
        atsIntegrationId: z.string(),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      try {
        const { candidateId, atsIntegrationId, organizationId } = input;
        const { user } = ctx;

        console.log("[DELETE] Starting delete with:", {
          candidateId,
          atsIntegrationId,
          organizationId,
        });

        // Verify the mapping exists and the ATS integration belongs to the organization
        const existingMapping = await db.atsCandidateMapping.findFirst({
          where: {
            candidateId,
            atsIntegrationId,
          },
          include: {
            atsIntegration: {
              select: {
                id: true,
                organizationId: true,
              },
            },
          },
        });

        console.log("[DELETE] Found mapping:", existingMapping);

        if (!existingMapping) {
          console.error("[DELETE] Mapping not found");
          throw new Error("ATS mapping not found");
        }

        if (existingMapping.atsIntegration.organizationId !== organizationId) {
          console.error("[DELETE] Organization mismatch:", {
            expected: organizationId,
            actual: existingMapping.atsIntegration.organizationId,
          });
          throw new Error("ATS mapping not found or unauthorized");
        }

        console.log("[DELETE] Deleting mapping:", {
          mappingId: existingMapping.id,
          candidateId: existingMapping.candidateId,
          atsExternalId: existingMapping.atsExternalId,
        });

        const result = await deleteAtsCandidateMappingById(
          existingMapping.id,
          user.id,
        );

        console.log("[DELETE] Successfully deleted mapping:", result);
        // Return a simple success response instead of the full deleted object
        // to avoid potential serialization issues
        return { success: true, deletedId: existingMapping.id };
      } catch (error) {
        console.error("[DELETE] Error in deleteAtsCandidateMapping:", error);
        throw error;
      }
    }),

  resubscribeCandidate: authedProcedure
    .input(z.object({ token: z.string() }))
    .output(z.object({ success: z.boolean() }))
    .mutation(async ({ input }) => {
      const { token } = input;

      try {
        // Verify and decode the JWT token
        const decoded = jwt.verify(token, env.EMAIL_SUBSCRIBE_JWT_SECRET) as {
          candidateId: string;
        };

        if (!decoded.candidateId) {
          throw new Error("Invalid token");
        }

        // Set emailUnsubscribed to false for the candidate
        await db.candidate.update({
          where: {
            id: decoded.candidateId,
          },
          data: {
            emailUnsubscribed: false,
          },
        });

        console.log("Candidate resubscribed to communications", {
          candidateId: decoded.candidateId,
        });

        return { success: true };
      } catch (error) {
        console.error("Failed to resubscribe:", error);
        throw new Error("Invalid or expired token");
      }
    }),
});

