import { z } from "zod";

import { db } from "@purplefish-ai/db/server";

import { CeipalJobResponseSchema } from "@/common/libs/ats/ceipal";
import { scheduleRuleSchema } from "@/common/libs/schedule";
import { JobSource } from "@/common/models/jobs";
import { ScriptNodeSchema } from "@/common/models/script-nodes";
import { IInterviewPlan } from "@/common/models/stages";
import { webScreeningStepSchema } from "@/common/schemas/web-screening";
import {
  changeJobTemplate,
  copyJob,
  createJob,
  createJobFromCeipal,
  generateNodesFromQualifications,
  insertVariablesInFlow,
  saveCallScript,
  saveJobQualifications,
  setAgentInterruptionMinWords,
  setAllowCallTransfers,
  setAllowedLanguages,
  setCanResumeCalls,
  setJobPublicAccess,
  setJobSource,
  setJobStatus,
  trackJobQualificationChanges,
  trackJobVariableChanges,
  triggerPipelineSyncPriorMonth,
  updateJob,
  updateJobCallingHours,
  updateJobCommsSequence,
  updateJobIntegration,
  updateJobTimezone,
  updateJobVariables,
} from "@/server/libs/jobs";

import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { router } from "../trpc";

export const jobRouter = router({
  createJob: organizationMemberProcedure
    .input(
      z.object({
        title: z.string().optional(),
        description: z.string(),
        scriptTemplateId: z.string().optional(),
        atsId: z.string(),
        clientId: z.string(),
        source: z.nativeEnum(JobSource),
        schemaVersion: z.string().optional(),
      }),
    )
    .mutation(async ({ ctx, input }) => {
      const {
        organizationId,
        title,
        description,
        scriptTemplateId,
        atsId,
        clientId,
        source,
        schemaVersion,
      } = input;
      const { user } = ctx;

      const { job } = await createJob({
        organizationId,
        originalTitle: title,
        unformattedDescription: description,
        scriptTemplateId,
        atsId,
        clientId,
        source,
        createdByUserId: user.id,
        schemaVersion,
      });

      return job;
    }),

  createJobFromCeipal: organizationMemberProcedure
    .input(
      z.object({
        ceipalJob: CeipalJobResponseSchema,
        scriptTemplateId: z.string(),
      }),
    )
    .mutation(async ({ ctx, input }) => {
      const { organizationId, ceipalJob, scriptTemplateId } = input;
      const { user } = ctx;
      const { jobId } = await createJobFromCeipal({
        organizationId,
        ceipalJob,
        scriptTemplateId,
        createdByUserId: user.id,
      });
      return jobId;
    }),

  updateJob: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        data: z.object({
          title: z.string(),
          description: z.string(),
          atsId: z.string(),
          clientId: z.string(),
          useAgentInstructions: z.boolean().optional(),
          agentInstructions: z.string().optional(),
          headline: z.string().optional(),
          knowledgeBase: z.string().optional(),
          callLanguage: z.string().optional(),
          transcriptSummaryInstructions: z.string().optional(),
        }),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, data } = input;
      return await updateJob({ organizationId, jobId, data });
    }),

  setCanResumeCalls: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        canResumeCalls: z.boolean(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, canResumeCalls } = input;
      return await setCanResumeCalls(organizationId, jobId, canResumeCalls);
    }),

  setJobSource: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        source: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, source } = input;
      return await setJobSource({
        organizationId,
        jobId,
        source: source as JobSource,
      });
    }),

  setJobStatus: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        status: z.string(),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { organizationId, jobId, status } = input;
      const { user } = ctx;
      return await setJobStatus({
        organizationId,
        jobId,
        status,
        userId: user.id,
      });
    }),

  generateNodesFromQualifications: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId } = input;
      return await generateNodesFromQualifications(organizationId, jobId);
    }),

  insertVariablesInFlow: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId } = input;
      return await insertVariablesInFlow(organizationId, jobId);
    }),

  saveCallScript: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        nodes: z.array(ScriptNodeSchema),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, nodes } = input;
      return await saveCallScript(organizationId, jobId, nodes);
    }),

  changeJobTemplate: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        scriptTemplateId: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, scriptTemplateId } = input;
      return await changeJobTemplate({
        organizationId,
        jobId,
        scriptTemplateId,
      });
    }),

  triggerCeipalSync: organizationMemberProcedure.mutation(async () => {
    return await triggerPipelineSyncPriorMonth();
  }),

  updateJobCommsSequence: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        commsSequence: z
          .object({
            maxAttempts: z.number(),
            intervalHours: z.number(),
          })
          .or(
            z.object({
              firstAction: z
                .object({
                  channel: z.enum(["phone", "sms", "email"]),
                  templateId: z.string().optional(),
                })
                .optional(),
              retryIntervals: z.array(
                z.object({
                  unit: z.enum(["hours", "days", "minutes"]),
                  value: z.number(),
                  action: z
                    .object({
                      channel: z.enum(["phone", "sms", "email"]),
                      templateId: z.string().optional(),
                    })
                    .optional(),
                }),
              ),
            }),
          ),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, commsSequence } = input;
      return await updateJobCommsSequence(organizationId, jobId, commsSequence);
    }),

  updateJobCallingHours: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        scheduleRule: scheduleRuleSchema,
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, scheduleRule } = input;
      return await updateJobCallingHours(organizationId, jobId, scheduleRule);
    }),

  updateJobTimezone: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        timezone: z
          .string()
          .refine(
            async (tz) =>
              Intl.DateTimeFormat(undefined, { timeZone: tz }).resolvedOptions()
                .timeZone === tz,
            { message: "Invalid timezone" },
          ),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, timezone } = input;
      return await updateJobTimezone(organizationId, jobId, timezone);
    }),

  trackJobVariableChanges: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        changedVariables: z.array(
          z.object({
            jobVariableName: z.string(),
            oldValue: z.string(),
            newValue: z.string(),
          }),
        ),
      }),
    )
    .mutation(async ({ input }) => {
      const { jobId, changedVariables } = input;
      return await trackJobVariableChanges({
        jobId,
        changedVariables,
      });
    }),

  trackJobQualificationChanges: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        changedQualifications: z.array(
          z.object({
            oldValue: z.string().optional(),
            newValue: z.string().optional(),
            oldShouldIncludeInFlow: z.boolean().optional(),
            newShouldIncludeInFlow: z.boolean().optional(),
            oldShouldIncludeInEmail: z.boolean().optional(),
            newShouldIncludeInEmail: z.boolean().optional(),
            oldType: z.string().optional(),
            newType: z.string().optional(),
          }),
        ),
      }),
    )
    .mutation(async ({ input }) => {
      const { jobId, changedQualifications } = input;
      return await trackJobQualificationChanges({
        jobId,
        changedQualifications,
      });
    }),

  updateJobVariables: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        variables: z.array(
          z.object({
            id: z.string(),
            createdAt: z.date(),
            updatedAt: z.date(),
            value: z.string(),
            jobId: z.string(),
            templateVariableId: z.string(),
          }),
        ),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, variables } = input;
      return await updateJobVariables({ organizationId, jobId, variables });
    }),

  saveJobQualifications: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        qualifications: z.array(
          z.object({
            id: z.string(),
            createdAt: z.date(),
            updatedAt: z.date(),
            type: z.string(),
            value: z.string(),
            jobId: z.string(),
            shouldIncludeInEmail: z.boolean(),
            shouldIncludeInFlow: z.boolean(),
            order: z.number(),
          }),
        ),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, qualifications } = input;
      return await saveJobQualifications({
        organizationId,
        jobId,
        qualifications,
      });
    }),

  copyJob: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
      }),
    )
    .mutation(async ({ ctx, input }) => {
      const { organizationId, jobId } = input;
      const { user } = ctx;

      try {
        const newJob = await copyJob({
          organizationId,
          sourceJobId: jobId,
          createdByUserId: user.id,
        });

        return {
          success: true,
          data: {
            id: newJob.id,
            title: newJob.title,
          },
        };
      } catch (error) {
        console.error("Error copying job:", error);
        return { success: false, error: "Failed to copy job" };
      }
    }),

  getJob: organizationMemberProcedure
    .input(z.object({ jobId: z.string() }))
    .query(async ({ input }) => {
      const { organizationId, jobId } = input;
      const job = await db.job.findUniqueOrThrow({
        where: {
          id: jobId,
          organizationId,
        },
      });
      return job;
    }),

  setJobAgentVoiceOverrides: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        agentVoiceOverrides: z.record(z.string(), z.string()),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, agentVoiceOverrides } = input;
      return await db.job.update({
        where: {
          id: jobId,
          organizationId,
        },
        data: { selectedAgentVoiceIds: agentVoiceOverrides },
        select: {
          id: true,
          selectedAgentVoiceIds: true,
        },
      });
    }),

  setAllowCallTransfers: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        allowCallTransfers: z.boolean(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, allowCallTransfers } = input;
      return await setAllowCallTransfers(
        organizationId,
        jobId,
        allowCallTransfers,
      );
    }),

  setAllowedLanguages: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        allowedLanguages: z.array(z.string()),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, allowedLanguages } = input;
      return await setAllowedLanguages(organizationId, jobId, allowedLanguages);
    }),

  setAgentInterruptionMinWords: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        agentInterruptionMinWords: z.number().min(0).max(5),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, agentInterruptionMinWords } = input;
      return await setAgentInterruptionMinWords(
        organizationId,
        jobId,
        agentInterruptionMinWords,
      );
    }),

  setJobPublicAccess: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        publicAccessEnabled: z.boolean(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, publicAccessEnabled } = input;
      return await setJobPublicAccess(
        organizationId,
        jobId,
        publicAccessEnabled,
      );
    }),

  updateInterviewPlan: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        initialInactiveStageId: z.string(),
        initialActiveStageId: z.string(),
        initialActiveStageIdWhenNoPhoneNumber: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const {
        organizationId,
        jobId,
        initialInactiveStageId,
        initialActiveStageId,
        initialActiveStageIdWhenNoPhoneNumber,
      } = input;

      const job = await db.job.findUniqueOrThrow({
        where: { id: jobId, organizationId },
        select: { interviewPlan: true },
      });

      const currentPlan = job.interviewPlan as IInterviewPlan | null;
      if (!currentPlan) {
        throw new Error("Interview plan not found");
      }

      const updatedPlan = {
        ...currentPlan,
        initialInactiveStageId,
        initialActiveStageId,
        initialActiveStageIdWhenNoPhoneNumber,
        updatedAt: new Date().toISOString(),
      };

      return await db.job.update({
        where: { id: jobId, organizationId },
        data: { interviewPlan: updatedPlan },
        select: { id: true, interviewPlan: true },
      });
    }),

  updateJobIntegration: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        atsId: z.string(),
        clientId: z.string(),
        source: z.nativeEnum(JobSource),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, atsId, clientId, source } = input;
      return await updateJobIntegration({
        organizationId,
        jobId,
        atsId,
        clientId,
        source,
      });
    }),

  updateWebScreeningSteps: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        steps: z.array(webScreeningStepSchema).nullable(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, steps } = input;

      // Verify the job exists and belongs to the organization
      const job = await db.job.findFirst({
        where: {
          id: jobId,
          organizationId,
        },
        select: {
          publicAccessEnabledAt: true,
        },
      });

      if (!job) {
        throw new Error("Job not found");
      }

      if (!job.publicAccessEnabledAt) {
        throw new Error(
          "Public access must be enabled to configure web conversation steps",
        );
      }

      // Update the job with the new steps
      await db.job.update({
        where: { id: jobId },
        data: {
          webScreeningSteps: steps,
        },
      });

      return { success: true };
    }),

  updateWebScreeningAuthSettings: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        allowedEmailDomains: z.array(z.string()).optional(),
        allowedVerificationMethods: z
          .array(z.enum(["email", "sms"]))
          .min(1, "At least one verification method must be selected")
          .optional(),
      }),
    )
    .mutation(async ({ input }) => {
      const {
        organizationId,
        jobId,
        allowedEmailDomains,
        allowedVerificationMethods,
      } = input;

      // Verify the job exists and belongs to the organization
      const job = await db.job.findFirst({
        where: {
          id: jobId,
          organizationId,
        },
        select: {
          publicAccessEnabledAt: true,
        },
      });

      if (!job) {
        throw new Error("Job not found");
      }

      if (!job.publicAccessEnabledAt) {
        throw new Error(
          "Public access must be enabled to configure authentication settings",
        );
      }

      // Update the job with the new authentication settings
      // Convert empty arrays to null to properly clear the restrictions
      await db.job.update({
        where: { id: jobId },
        data: {
          allowedEmailDomains:
            allowedEmailDomains && allowedEmailDomains.length > 0
              ? allowedEmailDomains
              : null,
          allowedVerificationMethods:
            allowedVerificationMethods && allowedVerificationMethods.length > 0
              ? allowedVerificationMethods
              : null,
        },
      });

      return { success: true };
    }),
});

