import { z } from "zod";

import { db } from "@purplefish-ai/db/server";

import { sendSMSImmediately as sendOpportunitySmsImmediately } from "@/server/libs/opportunities";

import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { router } from "../trpc";

export const smsMessageRouter = router({
  sendOpportunitySms: organizationMemberProcedure
    .input(
      z.object({
        opportunityId: z.string(),
        message: z.string(),
        suggestedSmsMessageId: z.string().optional(),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { organizationId, opportunityId, message, suggestedSmsMessageId } =
        input;

      const opportunity = await db.opportunity.findUnique({
        where: {
          id: opportunityId,
        },
        select: {
          candidate: {
            select: {
              phoneNumber: true,
            },
          },
          job: {
            select: {
              organizationId: true,
            },
          },
          smsMessages: true,
        },
      });

      if (!opportunity) {
        throw new Error("Opportunity not found");
      }

      if (opportunity.job.organizationId !== organizationId) {
        throw new Error(
          "You are not authorized to send SMS to this opportunity",
        );
      }

      return await sendOpportunitySmsImmediately({
        opportunityId,
        message,
        force: true,
        sentById: ctx.user.id,
        suggestedSmsMessageId,
      });
    }),
});

