import { z } from "zod";

import { scheduleRuleSchema } from "@/common/libs/schedule";
import { ScriptNodeSchema } from "@/common/models/script-nodes";
import {
  createScriptTemplate,
  deleteScriptTemplate,
  duplicateScriptTemplate,
  updateScriptTemplateDetails,
  updateScriptTemplateScheduleRule,
  updateScriptTemplateScript,
} from "@/server/libs/script-templates";

import { organizationAdminProcedure } from "../procedures/organization-admin-procedure";
import { router } from "../trpc";

export const scriptTemplateRouter = router({
  create: organizationAdminProcedure
    .input(
      z.object({
        name: z.string(),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { organizationId, name } = input;
      const userId = ctx.user.id;
      return await createScriptTemplate(organizationId, { name }, userId);
    }),

  updateDetails: organizationAdminProcedure
    .input(
      z.object({
        scriptTemplateId: z.string(),
        data: z.object({
          name: z.string(),
          description: z.string(),
        }),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, scriptTemplateId, data } = input;
      return await updateScriptTemplateDetails({
        organizationId,
        id: scriptTemplateId,
        data,
      });
    }),

  updateScript: organizationAdminProcedure
    .input(
      z.object({
        scriptTemplateId: z.string(),
        nodes: z.array(ScriptNodeSchema),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, scriptTemplateId, nodes } = input;
      return await updateScriptTemplateScript(
        organizationId,
        scriptTemplateId,
        nodes,
      );
    }),

  updateScheduleRule: organizationAdminProcedure
    .input(
      z.object({
        scriptTemplateId: z.string(),
        scheduleRule: scheduleRuleSchema,
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, scriptTemplateId, scheduleRule } = input;
      return await updateScriptTemplateScheduleRule(
        organizationId,
        scriptTemplateId,
        scheduleRule,
      );
    }),

  duplicate: organizationAdminProcedure
    .input(
      z.object({
        scriptTemplateId: z.string(),
        name: z.string(),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { organizationId, scriptTemplateId, name } = input;
      const userId = ctx.user.id;
      return await duplicateScriptTemplate(
        organizationId,
        scriptTemplateId,
        name,
        userId,
      );
    }),

  delete: organizationAdminProcedure
    .input(
      z.object({
        scriptTemplateId: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, scriptTemplateId } = input;
      return await deleteScriptTemplate(organizationId, scriptTemplateId);
    }),
});

