import { z } from "zod";

import { type Email } from "@purplefish-ai/db";
import { db } from "@purplefish-ai/db/server";

import { getCurrentSession } from "@/auth";
import { env } from "@/env";
import { makeDevEmailSubject } from "@/server/libs/emails";
import { getCandidateEmailAssociatedWithEmailID } from "@/server/resource_access/email-resource-accessor";
import { EmailProviderSelector } from "@/server/services/email/provider-selector";
import { sendEmailNotification } from "@/server/services/notification-email-sender";

import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { router } from "../trpc";

async function overrideEmailIfNeedBe(emailId: string, email: Email) {
  // if this email is a candidate notification, and if the candidate's email has changed since this email was sent,
  // override the email to be sent to the candidate's new email
  const candidateEmailResponse =
    await getCandidateEmailAssociatedWithEmailID(emailId);

  const maybeCandidateEmail =
    candidateEmailResponse?.opportunityNotification?.opportunity.candidate
      .email;
  if (
    maybeCandidateEmail &&
    email.to.length > 0 &&
    maybeCandidateEmail !== email.to[0]
  ) {
    console.log(
      `Email with id ${emailId} was sent to a candidate whose current email is now ${maybeCandidateEmail} - overriding candidate email to new email`,
    );
    email.to[0] = maybeCandidateEmail;
  }
}

export const emailRouter = router({
  resendEmail: organizationMemberProcedure
    .input(
      z.object({
        emailId: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { emailId, organizationId } = input;
      const email = await db.email.findUnique({
        where: { id: emailId },
      });

      if (!email) {
        throw new Error("Email not found");
      }
      const { user } = await getCurrentSession();
      console.log(
        `User ${user?.firstName} ${user?.lastName} (${user?.id}) is resending email ${emailId}`,
      );

      await overrideEmailIfNeedBe(emailId, email);

      const emailProvider = await new EmailProviderSelector().selectProvider(
        email.to,
        organizationId,
      );

      if (env.NODE_ENV !== "production") {
        console.log(
          "This server is running in dev mode, so emails will be sent to dev mailboxes",
        );

        email.subject = await makeDevEmailSubject({
          to: email.to,
          cc: email.cc,
          bcc: email.bcc,
          subject: email.subject,
        });

        email.to = ["development@purplefish.com"];
      }

      return await emailProvider.sendEmail({
        to: email.to,
        subject: email.subject,
        html: email.html,
        text: email.text,
        options: {
          replyTo: email.replyTo ?? undefined,
          cc: email.cc,
          bcc: email.bcc,
        },
        organizationId,
        opportunityNotificationId: email.opportunityNotificationId,
      });
    }),

  sendEmail: organizationMemberProcedure
    .input(
      z.object({
        subject: z.string(),
        message: z.string(),
        opportunityId: z.string(),
        nylasEmailId: z.string().optional(),
        recruiterEmail: z.string().optional(),
        previousMessageHTML: z.string().optional(),
        previousMessageText: z.string().optional(),
      }),
    )
    .mutation(async ({ input }) => {
      const {
        organizationId,
        subject,
        message,
        opportunityId,
        nylasEmailId,
        recruiterEmail,
        previousMessageHTML,
        previousMessageText,
      } = input;

      const opportunity = await db.opportunity.findUniqueOrThrow({
        where: { id: opportunityId },
        include: {
          candidate: true,
        },
      });

      if (opportunity.candidate.emailUnsubscribed) {
        throw new Error("Candidate has unsubscribed from emails");
      }

      await sendEmailNotification({
        subject,
        body: message,
        organizationId,
        to: opportunity.candidate.email,
        opportunityId,
        opportunityNotificationId: null,
        candidateId: opportunity.candidateId,
        options: {
          nylasEmailId: nylasEmailId,
          cc: recruiterEmail ? [recruiterEmail] : [],
        },
        previousMessage: {
          html: previousMessageHTML,
          text: previousMessageText,
        },
      });

      return {
        success: true,
      };
    }),
});

