import { z } from "zod";

import { db } from "@purplefish-ai/db/server";

import { BASE_URL } from "@/common/libs/base-url";
import { encryptAtsData } from "@/server/libs/ats-encryption";
import {
  generateCodeChallenge,
  generateCodeVerifier,
  generateState,
} from "@/server/libs/oauth-utils";

import { organizationAdminProcedure } from "../procedures/organization-admin-procedure";
import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { router } from "../trpc";

export const integrationRouter = router({
  getCeipalIntegration: organizationMemberProcedure
    .output(
      z
        .object({
          id: z.string(),
          organizationId: z.string(),
          name: z.string(),
          config: z.unknown(),
          syncConfig: z.unknown().nullable(),
          encryptedCredentials: z.unknown().nullable(),
          authTokenExpiresAt: z.date().nullable(),
          atsJobSyncUrl: z.string().nullable(),
          createdAt: z.date(),
          updatedAt: z.date(),
        })
        .nullable(),
    )
    .query(async ({ input }) => {
      const { organizationId } = input;

      const integration = await db.atsIntegration.findFirst({
        where: {
          organizationId,
          name: "ceipal",
        },
      });

      return integration;
    }),

  initiateSalesforceOAuth: organizationAdminProcedure
    .input(
      z.object({
        organizationId: z.string(),
        instanceUrl: z.string().url(),
        clientId: z.string().min(1),
        clientSecret: z.string().min(1),
      }),
    )
    .output(
      z.object({
        url: z.string(),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { organizationId, instanceUrl, clientId, clientSecret } = input;
      const userId = ctx.user.id;

      // Encrypt sensitive config data
      const configData = {
        instanceUrl,
        clientId,
        clientSecret,
      };

      const encrypted = encryptAtsData({ config: configData });

      // Store config in AtsIntegration
      const integration = await db.atsIntegration.upsert({
        where: {
          organizationId_name: {
            organizationId,
            name: "salesforce",
          },
        },
        create: {
          organizationId,
          name: "salesforce",
          config: encrypted.config,
          encryptedCredentials: encrypted.encryptedCredentials,
        },
        update: {
          config: encrypted.config,
          encryptedCredentials: encrypted.encryptedCredentials,
        },
      });

      // Generate PKCE parameters
      const codeVerifier = generateCodeVerifier();
      const codeChallenge = generateCodeChallenge(codeVerifier);
      const state = generateState();

      // Store OAuth state in database
      await db.oAuthState.create({
        data: {
          state,
          codeVerifier,
          atsIntegrationId: integration.id,
          userId,
          expiresAt: new Date(Date.now() + 10 * 60 * 1000), // 10 minutes
        },
      });

      const redirectUri = `${BASE_URL}/auth/oauth/salesforce/callback`;

      // Build Salesforce OAuth URL
      const authUrl = new URL(`${instanceUrl}/services/oauth2/authorize`);
      authUrl.searchParams.append("response_type", "code");
      authUrl.searchParams.append("client_id", clientId);
      authUrl.searchParams.append("redirect_uri", redirectUri);
      authUrl.searchParams.append("code_challenge", codeChallenge);
      authUrl.searchParams.append("code_challenge_method", "S256");
      authUrl.searchParams.append("state", state);
      authUrl.searchParams.append("scope", "api refresh_token");

      return { url: authUrl.toString() };
    }),
});

