    15→import { findOpportunityForCandidateAndJob } from "@/server/resource_access/opportunity-resource-accessor";
    16→
    17→import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
    18→import { router } from "../trpc";
    19→
    20→// ============= SCHEMAS =============
    21→const timeSlotSchema = z.object({
    22→  startTime: z.string(),
    23→  endTime: z.string(),
    24→});
    25→
    26→const participantSchema = z.object({
    27→  id: z.string(),
    28→  firstName: z.string(),
    29→  lastName: z.string(),
    30→  email: z.string().optional(),
    31→  phoneNumber: z.string().optional(),
    32→  type: z.enum(["candidate", "user"]),
    33→  purplefishParticipantId: z.string(),
    34→  contactForAdditionalAvailability: z.boolean().default(true),
    35→});
    36→
    37→const scheduleEventSchema = z.object({
    38→  meetingName: z.string().min(1, "Meeting name is required"),
    39→  purpose: z.string().min(1, "Purpose is required"),
    40→  duration: z.number().min(1, "Duration must be at least 1 minute"),
    41→  timeframe: z.string().min(1, "Timeframe is required"),
    42→  timezone: z.string().min(1, "Timezone is required"),
    43→  jobId: z.string().optional(), // New field for job selection
    44→  participants: z
    45→    .array(participantSchema)
    46→    .min(1, "At least one participant is required"),
    47→  knownAvailabilities: z
    48→    .record(
    49→      z.string(),
    50→      z.object({
    51→        timezone: z.string(),
    52→        slots: z.array(timeSlotSchema),
    53→      }),
    54→    )
    55→    .optional(),
    56→});
    57→
    58→// ============= HELPER FUNCTIONS =============
    59→
    60→/**
    61→ * Converts a local datetime string from HTML datetime-local input
    62→ * to an ISO 8601 string with timezone offset
    63→ * @param localDateTime - DateTime string from datetime-local input (e.g., "2024-01-15T14:30")
    64→ * @param timezone - IANA timezone string (e.g., "America/New_York")
    65→ * @returns ISO 8601 datetime string with timezone offset (e.g., "2024-01-15T14:30:00-05:00")
    66→ */
    67→function convertLocalDateTimeToTimezone(
    68→  localDateTime: string,
    69→  timezone: string,
    70→): string {
    71→  if (!localDateTime) {
    72→    return "";
    73→  }
    74→
    75→  try {
    76→    // Parse the local datetime string
    77→    const [datePart, timePart] = localDateTime.split("T");
    78→    if (!datePart || !timePart) {
    79→      throw new Error("Invalid datetime format");
    80→    }
    81→
    82→    // Add seconds if not present
    83→    const timeWithSeconds = timePart.length === 5 ? `${timePart}:00` : timePart;
    84→
    85→    // Parse date components
    86→    const dateParts = datePart.split("-").map(Number);
    87→    const timeParts = timeWithSeconds.split(":").map(Number);
    88→
    89→    if (dateParts.length < 3 || timeParts.length < 2) {
    90→      throw new Error("Invalid date or time components");
    91→    }
    92→
    93→    const [year, month, day] = dateParts as [number, number, number];
    94→    const [hours, minutes, seconds = 0] = timeParts as [
    95→      number,
    96→      number,
    97→      number?,
    98→    ];
    99→
   100→    // Create a date object for the exact local time
   101→    // Then format it with the target timezone to get the offset
   102→    const localDate = new Date(
   103→      year,
   104→      month - 1,
   105→      day,
   106→      hours,
   107→      minutes,
   108→      seconds || 0,
   109→    );
   110→
   111→    // Use a formatter to extract the timezone offset
   112→    // We format the same moment in time to get the offset
   113→    const formatter = new Intl.DateTimeFormat("en-US", {
   114→      timeZone: timezone,
   115→      year: "numeric",
   116→      month: "2-digit",
   117→      day: "2-digit",
   118→      hour: "2-digit",
   119→      minute: "2-digit",
   120→      second: "2-digit",
   121→      timeZoneName: "longOffset", // This gives us the offset like "GMT-05:00"
   122→      hour12: false,
   123→    });
   124→
   125→    const formattedParts = formatter.formatToParts(localDate);
   126→    const timeZoneName =
   127→      formattedParts.find((part) => part.type === "timeZoneName")?.value || "";
   128→
   129→    // Extract offset from the timezone name (e.g., "GMT-05:00" -> "-05:00")
   130→    let offset = "Z"; // Default to UTC
   131→    if (timeZoneName.includes("GMT")) {
   132→      const match = /GMT([+-]\d{2}:\d{2})/.exec(timeZoneName);
   133→      if (match?.[1]) {
   134→        offset = match[1];
   135→      } else if (timeZoneName === "GMT") {
   136→        offset = "Z";
   137→      }
   138→    }
   139→
   140→    // Return the ISO 8601 format with the extracted offset
   141→    return `${datePart}T${timeWithSeconds}${offset}`;
   142→  } catch (error) {
   143→    console.error("Error converting datetime to ISO 8601:", error);
   144→    // Fallback: return with UTC indicator
   145→    const hasSeconds = localDateTime.split(":").length >= 3;
   146→    return hasSeconds ? `${localDateTime}Z` : `${localDateTime}:00Z`;
   147→  }
   148→}
