   245→async function buildScheduleEventRequest(
   246→  organization: {
   247→    id: string;
   248→    agentName: string | null;
   249→    agentPhoneNumbers: { id: string }[];
   250→    mailboxId: string;
   251→  },
   252→  input: z.infer<typeof scheduleEventSchema>,
   253→  organizationId: string,
   254→  opportunityId?: string,
   255→) {
   256→  const { mailboxId, agentPhoneNumbers } = organization;
   257→  const smsContactMethodId = agentPhoneNumbers[0]?.id;
   258→
   259→  if (!smsContactMethodId) {
   260→    throw new Error("No SMS contact method available");
   261→  }
   262→
   263→  // Group participants by type
   264→  const participantsByType = input.participants.reduce(
   265→    (acc, p) => {
   266→      if (!acc[p.type]) {
   267→        acc[p.type] = [];
   268→      }
   269→      acc[p.type]!.push(p);
   270→      return acc;
   271→    },
   272→    {} as Record<string, typeof input.participants>,
   273→  );
   274→
   275→  // Build precedence levels (candidates first, then users)
   276→  const precedenceLevels = [];
   277→
   278→  const candidates = participantsByType.candidate;
   279→  if (candidates && candidates.length > 0) {
   280→    precedenceLevels.push({
   281→      role_description: "Candidate",
   282→      participants: candidates.map((p) =>
   283→        buildParticipantWithContact(
   284→          p,
   285→          mailboxId,
   286→          smsContactMethodId,
   287→          organizationId,
   288→          input.timezone,
   289→        ),
   290→      ),
   291→    });
   292→  }
   293→
   294→  const users = participantsByType.user;
   295→  if (users && users.length > 0) {
   296→    precedenceLevels.push({
   297→      role_description: "User",
   298→      participants: users.map((p) =>
   299→        buildParticipantWithContact(
   300→          p,
   301→          mailboxId,
   302→          smsContactMethodId,
   303→          organizationId,
   304→          input.timezone,
   305→        ),
   306→      ),
   307→    });
   308→  }
   309→
   310→  // Transform known availabilities to API format with per-participant timezone
   311→  const knownAvailabilities = input.knownAvailabilities
   312→    ? Object.entries(input.knownAvailabilities).reduce(
   313→        (acc, [participantId, participantAvailability]) => {
   314→          if (participantAvailability.slots.length > 0) {
   315→            // Use the participant's specific timezone for their availability
   316→            acc[participantId] = participantAvailability.slots.map((slot) => {
   317→              // Convert local datetime strings to ISO format with the participant's timezone
   318→              const startDateTime = convertLocalDateTimeToTimezone(
   319→                slot.startTime,
   320→                participantAvailability.timezone,
   321→              );
   322→              const endDateTime = convertLocalDateTimeToTimezone(
   323→                slot.endTime,
   324→                participantAvailability.timezone,
   325→              );
   326→
   327→              return {
   328→                start_time: startDateTime,
   329→                end_time: endDateTime,
   330→              };
   331→            });
   332→          }
   333→          return acc;
   334→        },
   335→        {} as Record<string, { start_time: string; end_time: string }[]>,
   336→      )
   337→    : undefined;
   338→
   339→  return {
   340→    agent: {
   341→      purplefish_id: organization.id,
   342→      name: organization.agentName || "Purplefish AI",
   343→    },
   344→    meeting_name: input.meetingName,
   345→    purpose: input.purpose,
   346→    duration_minutes: input.duration,
   347→    timeframe: input.timeframe,
   348→    participant_precedence_levels: precedenceLevels,
   349→    known_availabilities:
   350→      knownAvailabilities && Object.keys(knownAvailabilities).length > 0
   351→        ? knownAvailabilities
   352→        : undefined,
   353→    messaging_thread_id: uuidv4(),
   354→    organization_id: organizationId,
   355→    ...(opportunityId && { opportunity_id: opportunityId }),
   356→  };
   357→}
   358→
   359→function buildParticipantWithContact(
   360→  participant: z.infer<typeof participantSchema>,
   361→  mailboxId: string,
   362→  smsContactMethodId: string,
   363→  organizationId: string,
   364→  timezone: string,
   365→) {
   366→  const contactMethods = [];
   367→
   368→  if (participant.email) {
   369→    contactMethods.push({
   370→      type: "Email" as const,
   371→      value: participant.email,
   372→      purplefish_contact_method_id: mailboxId,
   373→    });
   374→  }
   375→
   376→  if (participant.phoneNumber) {
   377→    contactMethods.push({
   378→      type: "SMS" as const,
   379→      value: participant.phoneNumber,
   380→      purplefish_contact_method_id: smsContactMethodId,
   381→    });
   382→  }
   383→
   384→  return {
   385→    id: participant.id,
   386→    first_name: participant.firstName,
   387→    last_name: participant.lastName,
   388→    purplefish_participant_id: participant.purplefishParticipantId,
   389→    purplefish_organization_id: organizationId,
   390→    contact_methods: contactMethods,
   391→    timezone,
   392→    contact_for_additional_availability:
   393→      participant.contactForAdditionalAvailability,
   394→  };
   395→}
