   445→      let warning: string | undefined = undefined;
   446→
   447→      try {
   448→        const messagingClient = getMessagingAgentsClient();
   449→        if (messagingClient) {
   450→          // Use the custom client's request method to call the API
   451→          const response = await messagingClient.request<{
   452→            participants: ParticipantOutput[];
   453→            pagination: { total: number; limit: number; offset: number };
   454→            search_criteria: Record<string, string>;
   455→          }>({
