   473→      ]);
   474→
   475→      // Deduplicate and merge
   476→      const phoneSet = new Set<string>();
   477→      const emailSet = new Set<string>();
   478→      const mergedParticipants: {
   479→        id: string;
   480→        firstName: string;
   481→        lastName: string;
   482→        email: string | null;
   483→        phoneNumber: string | null;
   484→        type?: "participant" | "candidate" | "user";
   485→        source: "api" | "candidate" | "user";
   486→        purplefishParticipantId: string;
   487→        contactForAdditionalAvailability: boolean;
   488→        opportunity?: {
