   490→          status: string;
   491→          jobTitle: string;
   492→        };
   493→      }[] = [];
   494→
   495→      // Helper to normalize phone numbers for comparison
   496→      const normalizePhone = (phone: string | null | undefined) => {
   497→        if (!phone) {
   498→          return null;
   499→        }
   500→        return phone.replace(/\D/g, ""); // Remove non-digits
   501→      };
   502→
   503→      // Add API participants first (highest priority)
   504→      apiParticipants.forEach((participant) => {
   505→        const normalizedPhone = normalizePhone(participant.phone);
   506→
   507→        if (normalizedPhone) {
