   525→      });
   526→
   527→      // Add local candidates (skip duplicates by phone first, then email)
   528→      candidates.forEach((candidate) => {
   529→        const normalizedPhone = normalizePhone(candidate.phoneNumber);
   530→        const isDuplicatePhone =
   531→          normalizedPhone !== null && phoneSet.has(normalizedPhone);
   532→        const isDuplicateEmail =
