   552→        }
   553→      });
   554→
   555→      // Add local users (skip duplicates by phone first, then email)
   556→      users.forEach((user) => {
   557→        const normalizedPhone = normalizePhone(user.phoneNumber);
   558→        const isDuplicatePhone =
