   745→      );
   746→
   747→      // Send to messaging service
   748→      const messagingClient = getMessagingAgentsClient();
   749→
   750→      if (!messagingClient) {
   751→        throw new Error(
   752→          "Messaging service is not configured. Please check API configuration.",
