   756→      try {
   757→        const response = await messagingClient.scheduleEvent({
   758→          body: request,
   759→          url: "/agents/schedule_event" as const,
   760→        });
   761→
   762→        return { success: true, data: response };
   763→      } catch (error) {
   764→        console.error("Error scheduling event:", error);
   765→        throw new Error("Failed to schedule event. Please try again.");
   766→      }
   767→    }),
   768→});
