import { z } from "zod";

import {
  NotificationChannel,
  NotificationTemplateGroup,
} from "@purplefish-ai/db";

import { getCurrentSession } from "@/auth";
import {
  createJobTemplateNotifications,
  createOrgNotificationTemplate,
  deleteOrgNotificationTemplate,
  updateJobNotificationTemplate,
  updateOrgNotificationTemplate,
} from "@/server/libs/notification-templates";

import { organizationAdminProcedure } from "../procedures/organization-admin-procedure";
import { router } from "../trpc";

export const notificationTemplateRouter = router({
  createOrgNotificationTemplate: organizationAdminProcedure
    .input(
      z.object({
        name: z.string(),
        channel: z.nativeEnum(NotificationChannel),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, name, channel } = input;
      const result = await createOrgNotificationTemplate(organizationId, {
        name,
        channel,
      });
      return result;
    }),

  generateJobNotifications: organizationAdminProcedure
    .input(z.object({ jobId: z.string() }))
    .mutation(async ({ input }) => {
      const { organizationId, jobId } = input;

      const { user } = await getCurrentSession();
      console.log(
        `User ${user?.firstName} ${user?.lastName} (${user?.id}) is generating notifications for job ${jobId} in organization ${organizationId}`,
      );
      const result = await createJobTemplateNotifications({
        organizationId: organizationId,
        jobId,
      });
      return result;
    }),

  updateOrgNotificationTemplate: organizationAdminProcedure
    .input(
      z.object({
        notificationTemplateId: z.string(),
        data: z.object({
          name: z.string(),
          channel: z.nativeEnum(NotificationChannel),
          subject: z.string().optional(),
          body: z.string().optional(),
          enabled: z.boolean(),
          triggeredByState: z.string(),
          group: z.nativeEnum(NotificationTemplateGroup).nullable().optional(),
          replyToRecruiter: z.boolean().optional(),
        }),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, notificationTemplateId, data } = input;
      const result = await updateOrgNotificationTemplate({
        organizationId: organizationId,
        id: notificationTemplateId,
        data,
      });
      return result;
    }),

  deleteOrgNotificationTemplate: organizationAdminProcedure
    .input(z.object({ notificationTemplateId: z.string() }))
    .mutation(async ({ input }) => {
      const { organizationId, notificationTemplateId } = input;
      const result = await deleteOrgNotificationTemplate(
        organizationId,
        notificationTemplateId,
      );
      return result;
    }),

  updateJobNotificationTemplate: organizationAdminProcedure
    .input(
      z.object({
        notificationTemplateId: z.string(),
        data: z.object({
          subject: z.string().optional(),
          body: z.string().optional(),
          replyToRecruiter: z.boolean().optional(),
        }),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, notificationTemplateId, data } = input;
      const result = await updateJobNotificationTemplate({
        organizationId: organizationId,
        id: notificationTemplateId,
        data,
      });
      return result;
    }),

  toggleJobNotificationTemplate: organizationAdminProcedure
    .input(
      z.object({
        templateId: z.string(),
        enabled: z.boolean(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, templateId, enabled } = input;
      const result = await updateJobNotificationTemplate({
        organizationId: organizationId,
        id: templateId,
        data: {
          enabled,
        },
      });
      return result;
    }),
});

