import { z } from "zod";

import { db } from "@purplefish-ai/db/server";

import { stages } from "@/common/models/stages";
import { findValidOpportunityPublicLinkToken } from "@/server/libs/opportunity-public-link-tokens";
import { changeStage } from "@/server/libs/stages";

import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { procedure, router } from "../trpc";

export const stageRouter = router({
  changeStages: organizationMemberProcedure
    .input(
      z.object({
        opportunityIds: z.array(z.string()),
        currentStageId: z.string(),
        nextStageId: z.string(),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { organizationId, opportunityIds, currentStageId, nextStageId } =
        input;
      const { user } = ctx;
      const reason = `${opportunityIds.length > 1 ? "Bulk" : ""} stage changed by user action`;

      const result = await Promise.all(
        opportunityIds.map((opportunityId) =>
          changeStage({
            organizationId,
            opportunityId,
            currentStageId,
            nextStageId,
            userId: user.id,
            reason,
          }),
        ),
      );

      return result;
    }),

  processOptOut: procedure
    .input(
      z.object({
        secret: z.string(),
      }),
    )
    .output(
      z.object({
        success: z.boolean(),
      }),
    )
    .mutation(async ({ input }) => {
      const { secret } = input;

      const opportunityPublicLinkToken =
        await findValidOpportunityPublicLinkToken({
          token: secret,
        });

      if (!opportunityPublicLinkToken) {
        throw new Error("Invalid or expired link");
      }

      const opportunity = await db.opportunity.findUnique({
        where: {
          id: opportunityPublicLinkToken.opportunityId,
        },
        include: {
          job: {
            include: {
              organization: true,
            },
          },
        },
      });

      if (!opportunity) {
        throw new Error(
          "Opportunity not found or does not belong to this candidate",
        );
      }

      await changeStage({
        organizationId: opportunity.job.organizationId,
        opportunityId: opportunity.id,
        currentStageId: opportunity.currentStageId,
        nextStageId: stages.ARCHIVED,
        userId: null,
        reason: "Opted out of AI screen via email link",
      });

      console.log(
        "Candidate opted out of AI screen for traditional scheduling",
        {
          opportunityId: opportunity.id,
        },
      );

      return { success: true };
    }),
});

