import { z } from "zod";

import { db } from "@purplefish-ai/db/server";

import { CallLanguage } from "@/common/constants/call-languages";
import {
  removeOrganizationLogo,
  uploadOrganizationLogo,
} from "@/server/libs/organization-logo";
import {
  createOrganization,
  updateOrganization,
  updateOrganizationAgentVoiceOverrides,
} from "@/server/libs/organizations";

import { organizationAdminProcedure } from "../procedures/organization-admin-procedure";
import { systemAdminProcedure } from "../procedures/system-admin-procedure";
import { router } from "../trpc";

export const organizationRouter = router({
  createOrganization: systemAdminProcedure
    .input(
      z.object({
        name: z.string(),
        url: z.string().url(),
      }),
    )
    .mutation(async ({ input }) => {
      const { name, url } = input;
      const result = await createOrganization({ name, url });
      return result;
    }),

  updateOrganization: organizationAdminProcedure
    .input(
      z.object({
        name: z.string(),
        namePronunciation: z.string().trim().nullable().optional(),
        url: z.string().url(),
        contactUrl: z.string(),
        llmModel: z.string().nullable(),
        agentName: z.string().trim().nullable(),
        agentNamePronunciation: z.string().trim().nullable().optional(),
        agentCallerId: z.string().nullable(),
        defaultRecruiterId: z.string().nullable(),
        agentInstructions: z.string().nullable(),
        qualificationInstructions: z.string().nullable(),
        transcriptSummaryInstructions: z.string().nullable(),
        isDemo: z.boolean(),
        slackChannelName: z.string().nullable(),
        autoLaunchJobsEnabled: z.boolean(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, ...updateData } = input;
      const result = await updateOrganization(organizationId, updateData);
      return result;
    }),

  updateOrganizationAgentVoiceOverrides: organizationAdminProcedure
    .input(
      z.object({
        agentVoiceOverrides: z.record(z.nativeEnum(CallLanguage), z.string()),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, ...updateData } = input;
      const result = await updateOrganizationAgentVoiceOverrides(
        organizationId,
        updateData,
      );
      return result;
    }),

  updateOrganizationCommsSequence: organizationAdminProcedure
    .input(
      z.object({
        commsSequence: z.object({
          retryIntervals: z.array(
            z.object({
              unit: z.enum(["hours", "days", "minutes"]),
              value: z.number().int().positive(),
              action: z
                .object({
                  channel: z.enum(["phone", "email", "sms"]),
                  templateId: z.string().optional(),
                })
                .optional(),
            }),
          ),
          firstAction: z
            .object({
              channel: z.enum(["phone", "email", "sms"]),
              templateId: z.string().optional(),
            })
            .optional(),
        }),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, commsSequence } = input;
      const result = await db.organization.update({
        where: { id: organizationId },
        data: {
          commsSequence,
        },
      });
      return result;
    }),

  uploadOrganizationLogo: organizationAdminProcedure
    .input(
      z.object({
        fileBase64: z.string(),
        contentType: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, fileBase64, contentType } = input;
      const fileBuffer = Buffer.from(fileBase64, "base64");
      const logoUrl = await uploadOrganizationLogo(
        organizationId,
        fileBuffer,
        contentType,
      );
      return { logoUrl };
    }),

  removeOrganizationLogo: organizationAdminProcedure.mutation(
    async ({ input }) => {
      const { organizationId } = input;
      await removeOrganizationLogo(organizationId);
      return { success: true };
    },
  ),
});

