import { v4 as uuidv4 } from "uuid";
import { z } from "zod";

import { db } from "@purplefish-ai/db/server";
import {
  type ParticipantOutput,
  type SchedulingAttemptDetailResponse,
  type SchedulingAttemptStatusResponse,
  getMessagingAgentsClient,
} from "@purplefish-ai/messaging-api-client";

import { searchCandidatesWithJobFilter } from "@/server/resource_access/candidate-resource-accessor";
import { searchOrganizationJobs } from "@/server/resource_access/job-resource-accessor";
import { findLeastUsedMailbox } from "@/server/resource_access/mailbox-resource-accessor";
import { findOpportunityForCandidateAndJob } from "@/server/resource_access/opportunity-resource-accessor";

import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { router } from "../trpc";

// ============= SCHEMAS =============
const timeSlotSchema = z.object({
  startTime: z.string(),
  endTime: z.string(),
});

const participantSchema = z.object({
  id: z.string(),
  firstName: z.string(),
  lastName: z.string(),
  email: z.string().optional(),
  phoneNumber: z.string().optional(),
  type: z.enum(["candidate", "user"]),
  purplefishParticipantId: z.string(),
  contactForAdditionalAvailability: z.boolean().default(true),
});

const scheduleEventSchema = z.object({
  meetingName: z.string().min(1, "Meeting name is required"),
  purpose: z.string().min(1, "Purpose is required"),
  duration: z.number().min(1, "Duration must be at least 1 minute"),
  timeframe: z.string().min(1, "Timeframe is required"),
  timezone: z.string().min(1, "Timezone is required"),
  jobId: z.string().optional(), // New field for job selection
  participants: z
    .array(participantSchema)
    .min(1, "At least one participant is required"),
  knownAvailabilities: z
    .record(
      z.string(),
      z.object({
        timezone: z.string(),
        slots: z.array(timeSlotSchema),
      }),
    )
    .optional(),
});

// ============= HELPER FUNCTIONS =============

/**
 * Converts a local datetime string from HTML datetime-local input
 * to an ISO 8601 string with timezone offset
 * @param localDateTime - DateTime string from datetime-local input (e.g., "2024-01-15T14:30")
 * @param timezone - IANA timezone string (e.g., "America/New_York")
 * @returns ISO 8601 datetime string with timezone offset (e.g., "2024-01-15T14:30:00-05:00")
 */
function convertLocalDateTimeToTimezone(
  localDateTime: string,
  timezone: string,
): string {
  if (!localDateTime) {
    return "";
  }

  try {
    // Parse the local datetime string
    const [datePart, timePart] = localDateTime.split("T");
    if (!datePart || !timePart) {
      throw new Error("Invalid datetime format");
    }

    // Add seconds if not present
    const timeWithSeconds = timePart.length === 5 ? `${timePart}:00` : timePart;

    // Parse date components
    const dateParts = datePart.split("-").map(Number);
    const timeParts = timeWithSeconds.split(":").map(Number);

    if (dateParts.length < 3 || timeParts.length < 2) {
      throw new Error("Invalid date or time components");
    }

    const [year, month, day] = dateParts as [number, number, number];
    const [hours, minutes, seconds = 0] = timeParts as [
      number,
      number,
      number?,
    ];

    // Create a date object for the exact local time
    // Then format it with the target timezone to get the offset
    const localDate = new Date(
      year,
      month - 1,
      day,
      hours,
      minutes,
      seconds || 0,
    );

    // Use a formatter to extract the timezone offset
    // We format the same moment in time to get the offset
    const formatter = new Intl.DateTimeFormat("en-US", {
      timeZone: timezone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      timeZoneName: "longOffset", // This gives us the offset like "GMT-05:00"
      hour12: false,
    });

    const formattedParts = formatter.formatToParts(localDate);
    const timeZoneName =
      formattedParts.find((part) => part.type === "timeZoneName")?.value || "";

    // Extract offset from the timezone name (e.g., "GMT-05:00" -> "-05:00")
    let offset = "Z"; // Default to UTC
    if (timeZoneName.includes("GMT")) {
      const match = /GMT([+-]\d{2}:\d{2})/.exec(timeZoneName);
      if (match?.[1]) {
        offset = match[1];
      } else if (timeZoneName === "GMT") {
        offset = "Z";
      }
    }

    // Return the ISO 8601 format with the extracted offset
    return `${datePart}T${timeWithSeconds}${offset}`;
  } catch (error) {
    console.error("Error converting datetime to ISO 8601:", error);
    // Fallback: return with UTC indicator
    const hasSeconds = localDateTime.split(":").length >= 3;
    return hasSeconds ? `${localDateTime}Z` : `${localDateTime}:00Z`;
  }
}

// Removed searchCandidates - now using searchCandidatesWithJobFilter from resource accessor

async function searchUsers(organizationId: string, query: string) {
  return db.user.findMany({
    where: {
      organizationId,
      OR: [
        { firstName: { contains: query, mode: "insensitive" } },
        { lastName: { contains: query, mode: "insensitive" } },
        { email: { contains: query } },
      ],
    },
    select: {
      id: true,
      firstName: true,
      lastName: true,
      email: true,
      phoneNumber: true,
    },
    take: 10,
  });
}

function candidateToParticipant(candidate: {
  id: string;
  firstName: string | null;
  lastName: string | null;
  email: string | null;
  phoneNumber: string | null;
}) {
  return {
    id: candidate.id,
    firstName: candidate.firstName || "",
    lastName: candidate.lastName || "",
    email: candidate.email || undefined,
    phoneNumber: candidate.phoneNumber || undefined,
    type: "candidate" as const,
    purplefishParticipantId: candidate.id,
    contactForAdditionalAvailability: true,
  };
}

function userToParticipant(user: {
  id: string;
  firstName: string | null;
  lastName: string | null;
  email: string;
  phoneNumber: string | null;
}) {
  return {
    id: user.id,
    firstName: user.firstName || "",
    lastName: user.lastName || "",
    email: user.email,
    phoneNumber: user.phoneNumber || undefined,
    type: "user" as const,
    purplefishParticipantId: user.id,
    contactForAdditionalAvailability: true,
  };
}

async function getOrganizationWithResources(organizationId: string) {
  const organization = await db.organization.findUnique({
    where: { id: organizationId },
    select: {
      id: true,
      agentName: true,
      agentPhoneNumbers: {
        select: { id: true },
        take: 1,
      },
    },
  });

  if (!organization) {
    throw new Error("Organization not found");
  }

  // Validate phone number exists
  if (!organization.agentPhoneNumbers[0]?.id) {
    throw new Error("No SMS phone number configured for organization");
  }

  // Find available mailbox
  const since = new Date();
  since.setDate(since.getDate() - 7);
  const mailboxId = await findLeastUsedMailbox(organizationId, since);

  if (!mailboxId) {
    throw new Error("No email mailbox available for organization");
  }

  return { ...organization, mailboxId };
}

async function buildScheduleEventRequest(
  organization: {
    id: string;
    agentName: string | null;
    agentPhoneNumbers: { id: string }[];
    mailboxId: string;
  },
  input: z.infer<typeof scheduleEventSchema>,
  organizationId: string,
  opportunityId?: string,
) {
  const { mailboxId, agentPhoneNumbers } = organization;
  const smsContactMethodId = agentPhoneNumbers[0]?.id;

  if (!smsContactMethodId) {
    throw new Error("No SMS contact method available");
  }

  // Group participants by type
  const participantsByType = input.participants.reduce(
    (acc, p) => {
      if (!acc[p.type]) {
        acc[p.type] = [];
      }
      acc[p.type]!.push(p);
      return acc;
    },
    {} as Record<string, typeof input.participants>,
  );

  // Build precedence levels (candidates first, then users)
  const precedenceLevels = [];

  const candidates = participantsByType.candidate;
  if (candidates && candidates.length > 0) {
    precedenceLevels.push({
      role_description: "Candidate",
      participants: candidates.map((p) =>
        buildParticipantWithContact(
          p,
          mailboxId,
          smsContactMethodId,
          organizationId,
          input.timezone,
        ),
      ),
    });
  }

  const users = participantsByType.user;
  if (users && users.length > 0) {
    precedenceLevels.push({
      role_description: "User",
      participants: users.map((p) =>
        buildParticipantWithContact(
          p,
          mailboxId,
          smsContactMethodId,
          organizationId,
          input.timezone,
        ),
      ),
    });
  }

  // Transform known availabilities to API format with per-participant timezone
  const knownAvailabilities = input.knownAvailabilities
    ? Object.entries(input.knownAvailabilities).reduce(
        (acc, [participantId, participantAvailability]) => {
          if (participantAvailability.slots.length > 0) {
            // Use the participant's specific timezone for their availability
            acc[participantId] = participantAvailability.slots.map((slot) => {
              // Convert local datetime strings to ISO format with the participant's timezone
              const startDateTime = convertLocalDateTimeToTimezone(
                slot.startTime,
                participantAvailability.timezone,
              );
              const endDateTime = convertLocalDateTimeToTimezone(
                slot.endTime,
                participantAvailability.timezone,
              );

              return {
                start_time: startDateTime,
                end_time: endDateTime,
              };
            });
          }
          return acc;
        },
        {} as Record<string, { start_time: string; end_time: string }[]>,
      )
    : undefined;

  return {
    agent: {
      purplefish_id: organization.id,
      name: organization.agentName || "Purplefish AI",
    },
    meeting_name: input.meetingName,
    purpose: input.purpose,
    duration_minutes: input.duration,
    timeframe: input.timeframe,
    participant_precedence_levels: precedenceLevels,
    known_availabilities:
      knownAvailabilities && Object.keys(knownAvailabilities).length > 0
        ? knownAvailabilities
        : undefined,
    messaging_thread_id: uuidv4(),
    organization_id: organizationId,
    ...(opportunityId && { opportunity_id: opportunityId }),
  };
}

function buildParticipantWithContact(
  participant: z.infer<typeof participantSchema>,
  mailboxId: string,
  smsContactMethodId: string,
  organizationId: string,
  timezone: string,
) {
  const contactMethods = [];

  if (participant.email) {
    contactMethods.push({
      type: "Email" as const,
      value: participant.email,
      purplefish_contact_method_id: mailboxId,
    });
  }

  if (participant.phoneNumber) {
    contactMethods.push({
      type: "SMS" as const,
      value: participant.phoneNumber,
      purplefish_contact_method_id: smsContactMethodId,
    });
  }

  return {
    id: participant.id,
    first_name: participant.firstName,
    last_name: participant.lastName,
    purplefish_participant_id: participant.purplefishParticipantId,
    purplefish_organization_id: organizationId,
    contact_methods: contactMethods,
    timezone,
    contact_for_additional_availability:
      participant.contactForAdditionalAvailability,
  };
}

export const schedulingRouter = router({
  searchJobs: organizationMemberProcedure
    .input(
      z.object({
        query: z.string().optional(),
      }),
    )
    .query(async ({ input }) => {
      const { organizationId, query } = input;
      return await searchOrganizationJobs(organizationId, query);
    }),

  searchParticipants: organizationMemberProcedure
    .input(
      z.object({
        query: z.string().min(1, "Search query required"),
        jobId: z.string().optional(),
      }),
    )
    .query(async ({ input }) => {
      const { organizationId, query, jobId } = input;

      // Skip messaging API when job filtering is active
      if (jobId) {
        const [candidates, users] = await Promise.all([
          searchCandidatesWithJobFilter(organizationId, query, jobId),
          searchUsers(organizationId, query),
        ]);

        const candidateParticipants = candidates.map((candidate) => ({
          ...candidateToParticipant(candidate),
          opportunity: candidate.opportunity,
          source: "candidate" as const,
        }));

        return {
          participants: [
            ...candidateParticipants,
            ...users.map((u) => ({
              ...userToParticipant(u),
              source: "user" as const,
            })),
          ],
        };
      }

      // Include messaging API when no job filter
      let apiParticipants: ParticipantOutput[] = [];
      let warning: string | undefined = undefined;

      try {
        const messagingClient = getMessagingAgentsClient();
        if (messagingClient) {
          // Use the custom client's request method to call the API
          const response = await messagingClient.request<{
            participants: ParticipantOutput[];
            pagination: { total: number; limit: number; offset: number };
            search_criteria: Record<string, string>;
          }>({
            method: "GET",
            url: `/organizations/${organizationId}/participants/search`,
            params: { q: query },
          });

          apiParticipants = response.participants.slice(0, 10);
        }
      } catch (error) {
        console.error("Messaging API search failed:", error);
        warning =
          "Participant search service unavailable. Showing local results only.";
      }

      // Fetch local results
      const [candidates, users] = await Promise.all([
        searchCandidatesWithJobFilter(organizationId, query),
        searchUsers(organizationId, query),
      ]);

      // Deduplicate and merge
      const phoneSet = new Set<string>();
      const emailSet = new Set<string>();
      const mergedParticipants: {
        id: string;
        firstName: string;
        lastName: string;
        email: string | null;
        phoneNumber: string | null;
        type?: "participant" | "candidate" | "user";
        source: "api" | "candidate" | "user";
        purplefishParticipantId: string;
        contactForAdditionalAvailability: boolean;
        opportunity?: {
          id: string;
          status: string;
          jobTitle: string;
        };
      }[] = [];

      // Helper to normalize phone numbers for comparison
      const normalizePhone = (phone: string | null | undefined) => {
        if (!phone) {
          return null;
        }
        return phone.replace(/\D/g, ""); // Remove non-digits
      };

      // Add API participants first (highest priority)
      apiParticipants.forEach((participant) => {
        const normalizedPhone = normalizePhone(participant.phone);

        if (normalizedPhone) {
          phoneSet.add(normalizedPhone);
        }
        if (participant.email) {
          emailSet.add(participant.email.toLowerCase());
        }

        mergedParticipants.push({
          id: participant.id,
          firstName: participant.first_name,
          lastName: participant.last_name,
          email: participant.email,
          phoneNumber: participant.phone,
          type: "participant" as const,
          source: "api" as const,
          purplefishParticipantId: participant.id,
          contactForAdditionalAvailability: true,
        });
      });

      // Add local candidates (skip duplicates by phone first, then email)
      candidates.forEach((candidate) => {
        const normalizedPhone = normalizePhone(candidate.phoneNumber);
        const isDuplicatePhone =
          normalizedPhone !== null && phoneSet.has(normalizedPhone);
        const isDuplicateEmail =
          candidate.email !== null &&
          emailSet.has(candidate.email.toLowerCase());

        if (!isDuplicatePhone && !isDuplicateEmail) {
          if (normalizedPhone) {
            phoneSet.add(normalizedPhone);
          }
          if (candidate.email) {
            emailSet.add(candidate.email.toLowerCase());
          }

          const participantData = candidateToParticipant(candidate);
          mergedParticipants.push({
            ...participantData,
            email: participantData.email ?? null,
            phoneNumber: participantData.phoneNumber ?? null,
            opportunity: candidate.opportunity,
            source: "candidate" as const,
          });
        }
      });

      // Add local users (skip duplicates by phone first, then email)
      users.forEach((user) => {
        const normalizedPhone = normalizePhone(user.phoneNumber);
        const isDuplicatePhone =
          normalizedPhone !== null && phoneSet.has(normalizedPhone);
        const isDuplicateEmail = emailSet.has(user.email.toLowerCase());

        if (!isDuplicatePhone && !isDuplicateEmail) {
          if (normalizedPhone) {
            phoneSet.add(normalizedPhone);
          }
          emailSet.add(user.email.toLowerCase());

          const userData = userToParticipant(user);
          mergedParticipants.push({
            ...userData,
            phoneNumber: userData.phoneNumber ?? null,
            source: "user" as const,
          });
        }
      });

      return {
        participants: mergedParticipants,
        warning,
      };
    }),

  getSchedulingAttempts: organizationMemberProcedure
    .input(
      z.object({
        cursor: z.string().nullish(),
        limit: z.number().min(1).max(100).default(20),
        status: z.string().optional(),
        startDate: z.string().optional(),
        endDate: z.string().optional(),
        participantEmail: z.string().optional(),
      }),
    )
    .query(async ({ input }) => {
      const {
        organizationId,
        cursor,
        limit,
        status,
        startDate,
        endDate,
        participantEmail,
      } = input;

      const messagingClient = getMessagingAgentsClient();

      if (!messagingClient) {
        throw new Error(
          "Messaging service is not configured. Please check API configuration.",
        );
      }

      try {
        const params = new URLSearchParams();
        params.append("organization_id", organizationId);
        params.append("limit", limit.toString());

        if (cursor) {
          params.append("cursor", cursor);
        }
        if (status) {
          params.append("status", status);
        }
        if (startDate) {
          params.append("start_date", startDate);
        }
        if (endDate) {
          params.append("end_date", endDate);
        }
        if (participantEmail) {
          params.append("participant_email", participantEmail);
        }

        const response =
          await messagingClient.request<SchedulingAttemptStatusResponse>({
            method: "GET",
            url: `/scheduling_attempt_status/?${params.toString()}`,
          });

        return response;
      } catch (error) {
        console.error("Error fetching scheduling attempts:", error);
        throw new Error(
          "Failed to fetch scheduling attempts. Please try again.",
        );
      }
    }),

  getSchedulingAttemptDetail: organizationMemberProcedure
    .input(
      z.object({
        attemptId: z.string(),
      }),
    )
    .query(async ({ input }) => {
      const { organizationId, attemptId } = input;

      const messagingClient = getMessagingAgentsClient();

      if (!messagingClient) {
        throw new Error(
          "Messaging service is not configured. Please check API configuration.",
        );
      }

      try {
        const response =
          await messagingClient.request<SchedulingAttemptDetailResponse>({
            method: "GET",
            url: `/scheduling_attempt_status/${attemptId}`,
          });

        // Verify organization access
        // eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment
        const responseData = response as any;
        // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
        if (responseData.organization_id !== organizationId) {
          throw new Error("Unauthorized access to this scheduling attempt");
        }

        return response;
      } catch (error) {
        console.error("Error fetching scheduling attempt detail:", error);
        throw new Error(
          "Failed to fetch scheduling attempt details. Please try again.",
        );
      }
    }),

  scheduleEvent: organizationMemberProcedure
    .input(scheduleEventSchema)
    .mutation(async ({ input }) => {
      const { organizationId, jobId, participants } = input;

      // Get organization details and validate resources
      const organization = await getOrganizationWithResources(organizationId);

      // If job is selected, find opportunities for all candidates
      // We'll use the first valid opportunity found as the primary one
      let opportunityId: string | undefined;
      if (jobId) {
        const candidates = participants.filter((p) => p.type === "candidate");

        if (candidates.length > 0) {
          // Try to find an opportunity for each candidate
          for (const candidate of candidates) {
            const opportunity = await findOpportunityForCandidateAndJob(
              candidate.id,
              jobId,
              organizationId,
            );

            if (opportunity?.id) {
              opportunityId = opportunity.id;
              console.info(
                `Using opportunity ${opportunity.id} for candidate ${candidate.id} and job ${jobId}`,
              );
              break; // Use the first valid opportunity found
            } else {
              console.warn(
                `No opportunity found for candidate ${candidate.id} and job ${jobId}`,
              );
            }
          }

          // Log if no opportunities were found for any candidate
          if (!opportunityId && candidates.length > 0) {
            console.warn(
              `No opportunities found for any of the ${candidates.length} candidates with job ${jobId}`,
            );
          }
        } else if (jobId) {
          console.info(
            `Job ${jobId} selected but no candidates in participant list`,
          );
        }
      }

      // Prepare the scheduling request with opportunity_id
      const request = await buildScheduleEventRequest(
        organization,
        input,
        organizationId,
        opportunityId,
      );

      // Send to messaging service
      const messagingClient = getMessagingAgentsClient();

      if (!messagingClient) {
        throw new Error(
          "Messaging service is not configured. Please check API configuration.",
        );
      }

      try {
        const response = await messagingClient.scheduleEvent({
          body: request,
          url: "/agents/schedule_event" as const,
        });

        return { success: true, data: response };
      } catch (error) {
        console.error("Error scheduling event:", error);
        throw new Error("Failed to schedule event. Please try again.");
      }
    }),
});

