import Nylas from "nylas";
import { z } from "zod";

import { BASE_URL } from "@/common/libs/base-url";
import { env } from "@/env";
import {
  deleteMailbox,
  findMailboxById,
} from "@/server/resource_access/mailbox-resource-accessor";
import { verifyResendDomainKey } from "@/server/services/dns-verification";

import { organizationAdminProcedure } from "../procedures/organization-admin-procedure";
import { router } from "../trpc";

interface StateData {
  organizationId: string;
  userId: string;
}

function encodeState(data: StateData): string {
  return Buffer.from(JSON.stringify(data)).toString("base64");
}

export const mailboxRouter = router({
  initiateNylasAuth: organizationAdminProcedure
    .input(
      z.object({
        userId: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, userId } = input;

      const nylas = new Nylas({
        apiKey: env.NYLAS_API_KEY,
        apiUri: env.NYLAS_API_URL,
      });

      const state = encodeState({ organizationId, userId });

      const url = nylas.auth.urlForOAuth2({
        clientId: env.NYLAS_CLIENT_ID,
        provider: "google",
        redirectUri: `${BASE_URL}/auth/oauth/exchange`,
        loginHint: "",
        accessType: "offline",
        state,
      });

      return { url };
    }),

  deleteMailbox: organizationAdminProcedure
    .input(
      z.object({
        mailboxId: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { mailboxId } = input;
      const mailbox = await findMailboxById(mailboxId);
      if (!mailbox) {
        throw new Error(`Mailbox with ID ${mailboxId} not found`);
      }

      const nylas = new Nylas({
        apiKey: env.NYLAS_API_KEY,
        apiUri: env.NYLAS_API_URL,
      });

      if (!mailbox.nylasGrantId) {
        console.error(
          `Grant ID not defined on mailbox ${mailboxId} slated for deletion`,
        );
      } else {
        try {
          await nylas.grants.destroy({ grantId: mailbox.nylasGrantId });
          console.log(`Deleted Nylas grant ${mailbox.nylasGrantId}`);
        } catch (error: unknown) {
          // If grant doesn't exist, log and continue
          if (
            typeof error === "object" &&
            error !== null &&
            "statusCode" in error &&
            error.statusCode === 404
          ) {
            console.log(`Nylas grant ${mailbox.nylasGrantId} already deleted`);
          } else {
            throw error;
          }
        }
      }

      try {
        await deleteMailbox(mailboxId);
        return { success: true };
      } catch (error) {
        console.error("Error deleting mailbox:", error);
        throw new Error("Failed to delete mailbox");
      }
    }),

  updateMailboxUseResend: organizationAdminProcedure
    .input(
      z.object({
        mailboxId: z.string(),
        useResendForInitialContact: z.boolean(),
      }),
    )
    .mutation(async ({ input }) => {
      const { mailboxId, useResendForInitialContact } = input;

      const mailbox = await findMailboxById(mailboxId);
      if (!mailbox) {
        throw new Error(`Mailbox with ID ${mailboxId} not found`);
      }

      // If enabling Resend, verify DNS first
      if (useResendForInitialContact) {
        const dnsResult = await verifyResendDomainKey(mailbox.email);

        if (!dnsResult.verified) {
          throw new Error(
            `DNS verification failed: ${dnsResult.error}. Please ensure resend._domainkey TXT record is configured for your domain.`,
          );
        }
      }

      // Update the mailbox setting
      const { db } = await import("@purplefish-ai/db/server");
      const updatedMailbox = await db.mailbox.update({
        where: { id: mailboxId },
        data: { useResendForInitialContact },
      });

      return { success: true, mailbox: updatedMailbox };
    }),

  checkResendDns: organizationAdminProcedure
    .input(
      z.object({
        mailboxId: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { mailboxId } = input;

      const mailbox = await findMailboxById(mailboxId);
      if (!mailbox) {
        throw new Error(`Mailbox with ID ${mailboxId} not found`);
      }

      const dnsResult = await verifyResendDomainKey(mailbox.email);

      return dnsResult;
    }),
});

