import { z } from "zod";

import { env } from "@/env";

import { systemAdminProcedure } from "../procedures/system-admin-procedure";
import { router } from "../trpc";

const fetchDatadogLogsSchema = z.object({
  livekitJobId: z.string(),
  startTime: z.string(),
  endTime: z.string(),
});

interface DatadogLogAttributes {
  timestamp: string;
  message?: string;
  status?: string;
  attributes?: Record<string, unknown>;
}

interface DatadogLog {
  attributes: DatadogLogAttributes;
}

interface DatadogResponse {
  data?: DatadogLog[];
  meta?: {
    page?: {
      total_count?: number;
    };
  };
}

interface TransformedLog {
  timestamp: string;
  message: string;
  level: string;
  attributes: Record<string, unknown>;
}

export const debugRouter = router({
  fetchDatadogLogs: systemAdminProcedure
    .input(fetchDatadogLogsSchema)
    .query(async ({ input }) => {
      const { livekitJobId, startTime, endTime } = input;

      // Check if Datadog API credentials are configured
      const apiKey = env.DATADOG_API_KEY;
      const appKey = env.DATADOG_APP_KEY;

      if (!apiKey || !appKey) {
        console.warn("Datadog API credentials not configured");
        return {
          logs: [] as TransformedLog[],
          error: "Datadog API credentials not configured",
        };
      }

      try {
        // Convert times to ISO 8601 format for Datadog API
        const fromTime = new Date(startTime).toISOString();
        const toTime = new Date(endTime).toISOString();

        // Construct the Datadog logs query
        const query = `@job_id:"${livekitJobId}"`;

        // Datadog logs API endpoint
        const url = new URL(
          "https://api.datadoghq.com/api/v2/logs/events/search",
        );

        const body = {
          filter: {
            query,
            from: fromTime,
            to: toTime,
          },
          sort: "timestamp",
          page: {
            limit: 1000,
          },
        };

        const response = await fetch(url.toString(), {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "DD-API-KEY": apiKey,
            "DD-APPLICATION-KEY": appKey,
          },
          body: JSON.stringify(body),
        });

        if (!response.ok) {
          const errorText = await response.text();
          console.error("Datadog API error:", response.status, errorText);
          throw new Error(`Datadog API error: ${response.status}`);
        }

        const data = (await response.json()) as DatadogResponse;

        // Transform the logs into a simpler format
        const logs: TransformedLog[] =
          data.data?.map((log) => ({
            timestamp: log.attributes.timestamp,
            message:
              log.attributes.message ||
              (log.attributes.attributes?.message as string) ||
              "",
            level:
              log.attributes.status ||
              (log.attributes.attributes?.level as string) ||
              "info",
            attributes: log.attributes.attributes || {},
          })) || [];

        return {
          logs,
          totalCount: data.meta?.page?.total_count ?? logs.length,
        };
      } catch (error) {
        console.error("Error fetching Datadog logs:", error);
        return {
          logs: [] as TransformedLog[],
          error:
            error instanceof Error ? error.message : "Failed to fetch logs",
        };
      }
    }),
});

