import { z } from "zod";

import { db } from "@purplefish-ai/db/server";

import {
  formResponseSchema,
  videoResponseSchema,
} from "@/common/schemas/web-screening";
import { findValidOpportunityPublicLinkToken } from "@/server/libs/opportunity-public-link-tokens";

import { procedure, router } from "../trpc";

export const webScreeningRouter = router({
  saveResponse: procedure
    .input(
      z.object({
        token: z.string(),
        stepId: z.string(),
        stepType: z.enum(["form", "video", "screening"]),
        data: z.record(z.any()),
      }),
    )
    .mutation(async ({ input }) => {
      const { token, stepId, stepType, data } = input;

      // Validate the token and get the opportunity
      const opportunityToken = await findValidOpportunityPublicLinkToken({
        token,
      });

      if (!opportunityToken) {
        throw new Error("Invalid or expired token");
      }

      // Validate step-specific data
      if (stepType === "form") {
        formResponseSchema.parse(data);
      } else if (stepType === "video") {
        videoResponseSchema.parse(data);
      }

      // Save the response
      const response = await db.webScreeningResponse.create({
        data: {
          opportunityId: opportunityToken.opportunityId,
          stepId,
          stepType,
          responseData: data,
          completedAt: new Date(),
        },
      });

      return { success: true, responseId: response.id };
    }),

  getResponses: procedure
    .input(
      z.object({
        token: z.string(),
      }),
    )
    .query(async ({ input }) => {
      const { token } = input;

      // Validate the token and get the opportunity
      const opportunityToken = await findValidOpportunityPublicLinkToken({
        token,
      });

      if (!opportunityToken) {
        throw new Error("Invalid or expired token");
      }

      // Get all responses for this opportunity
      const responses = await db.webScreeningResponse.findMany({
        where: {
          opportunityId: opportunityToken.opportunityId,
        },
        orderBy: {
          createdAt: "asc",
        },
      });

      return {
        success: true,
        responses: responses.map((r) => ({
          stepId: r.stepId,
          stepType: r.stepType,
          completedAt: r.completedAt,
          data: r.responseData,
        })),
      };
    }),

  getJobConfig: procedure
    .input(
      z.object({
        token: z.string(),
      }),
    )
    .query(async ({ input }) => {
      const { token } = input;

      // Validate the token and get the opportunity
      const opportunityToken = await findValidOpportunityPublicLinkToken({
        token,
      });

      if (!opportunityToken) {
        throw new Error("Invalid or expired token");
      }

      // Get the job configuration
      const opportunity = await db.opportunity.findUniqueOrThrow({
        where: {
          id: opportunityToken.opportunityId,
        },
        select: {
          job: {
            select: {
              webScreeningSteps: true,
            },
          },
        },
      });

      return {
        success: true,
        steps: opportunity.job.webScreeningSteps,
      };
    }),
});

