import * as keytermsService from "@/server/services/keyterms";

import { organizationAdminProcedure } from "../procedures/organization-admin-procedure";
import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { router } from "../trpc";

const keytermEntrySchema = z.object({
  keyterm: z
    .string()
    .min(1, "Keyterm is required")
    .max(100, "Keyterm is too long"),
});

export const keytermsRouter = router({
  getKeyterms: organizationMemberProcedure.query(async ({ input }) => {
    const { organizationId } = input;
    return await keytermsService.getKeyterms(organizationId);
  }),

  createKeyterm: organizationAdminProcedure
    .input(keytermEntrySchema)
    .mutation(async ({ input }) => {
      const { organizationId, keyterm } = input;
      return await keytermsService.createKeyterm({ organizationId, keyterm });
    }),

  updateKeyterm: organizationAdminProcedure
    .input(
      z.object({
        id: z.string(),
        keyterm: z
          .string()
          .min(1, "Keyterm is required")
          .max(100, "Keyterm is too long"),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, id, keyterm } = input;
      return await keytermsService.updateKeyterm({
        id,
        organizationId,
        keyterm,
      });
    }),

  deleteKeyterm: organizationAdminProcedure
    .input(z.object({ id: z.string() }))
    .mutation(async ({ input }) => {
      const { organizationId, id } = input;
      return await keytermsService.deleteKeyterm({ id, organizationId });
    }),
});

