import { z } from "zod";

import { db } from "@purplefish-ai/db/server";

import { CallLanguage } from "@/common/constants/call-languages";
import { getAgentVoiceOverrides } from "@/server/libs/agent-voices";
import { generateVoicePreview } from "@/server/libs/voice-generation";

import { organizationAdminProcedure } from "../procedures/organization-admin-procedure";
import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { router } from "../trpc";

const pronunciationEntrySchema = z.object({
  word: z.string().min(1, "Word is required"),
  pronunciation: z.string().min(1, "Pronunciation is required"),
  matchCase: z.boolean(),
});

export const pronunciationDictionaryRouter = router({
  getPronunciationDictionary: organizationAdminProcedure.query(
    async ({ input }) => {
      const { organizationId } = input;

      const entries = await db.orgPronunciationEntry.findMany({
        where: { organizationId },
        orderBy: { word: "asc" },
      });

      return entries;
    },
  ),

  createPronunciationEntry: organizationAdminProcedure
    .input(pronunciationEntrySchema)
    .mutation(async ({ input }) => {
      const { organizationId, ...data } = input;

      const entry = await db.orgPronunciationEntry.create({
        data: {
          ...data,
          organizationId,
        },
      });

      return entry;
    }),

  updatePronunciationEntry: organizationAdminProcedure
    .input(
      z.object({
        id: z.string(),
        word: z.string().min(1, "Word is required"),
        pronunciation: z.string().min(1, "Pronunciation is required"),
        matchCase: z.boolean(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, id, ...data } = input;

      const entry = await db.orgPronunciationEntry.update({
        where: {
          id,
          organizationId, // Ensure the entry belongs to the organization
        },
        data,
      });

      return entry;
    }),

  deletePronunciationEntry: organizationAdminProcedure
    .input(z.object({ id: z.string() }))
    .mutation(async ({ input }) => {
      const { organizationId, id } = input;

      await db.orgPronunciationEntry.delete({
        where: {
          id,
          organizationId, // Ensure the entry belongs to the organization
        },
      });

      return { success: true };
    }),

  previewPronunciation: organizationMemberProcedure
    .input(
      z.object({
        text: z.string().min(1).max(500),
        language: z.nativeEnum(CallLanguage),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, text, language } = input;
      // Get voice settings for the organization and language
      const voiceOverrides = await getAgentVoiceOverrides({
        organizationId,
        fallbackToDefault: true,
      });

      const voiceId = voiceOverrides[language];
      if (!voiceId) {
        throw new Error("No voice configured for this language");
      }

      // Get voice details
      const voice = await db.agentVoice.findUnique({
        where: { id: voiceId },
        select: {
          provider: true,
          externalId: true,
        },
      });

      if (!voice) {
        throw new Error("Voice not found");
      }

      // Generate TTS using the unified utility
      return await generateVoicePreview(voice, { text, language });
    }),
});

import { z } from "zod";

import * as schemaService from "@/server/services/candidate-data-point-schemas";

import { systemAdminProcedure } from "../procedures/system-admin-procedure";
import { router } from "../trpc";

// Define metadata schema for input validation
const schemaMetadataSchema = z.object({
  propertyOrder: z.array(z.string()).optional(),
});

export const candidateDataPointSchemaRouter = router({
  list: systemAdminProcedure
    .input(
      z
        .object({
          activeOnly: z.boolean().optional().default(true),
        })
        .optional(),
    )
    .query(async ({ input }) => {
      return await schemaService.listSchemas({
        activeOnly: input?.activeOnly ?? true,
      });
    }),

  get: systemAdminProcedure
    .input(
      z.object({
        id: z.string(),
      }),
    )
    .query(async ({ input }) => {
      return await schemaService.getSchemaById(input.id);
    }),

  create: systemAdminProcedure
    .input(
      z.object({
        schemaKey: z
          .string()
          .min(1, "Schema key is required")
          .regex(
            /^[a-z0-9_]+$/,
            "Schema key must be lowercase with underscores",
          ),
        title: z.string().min(1, "Title is required"),
        description: z.string(),
        defaultPrompt: z.string(),
        jsonSchema: z.record(z.unknown()),
        metadata: schemaMetadataSchema.optional(),
      }),
    )
    .mutation(async ({ input }) => {
      return await schemaService.createSchema({
        schemaKey: input.schemaKey,
        title: input.title,
        description: input.description,
        defaultPrompt: input.defaultPrompt,
        jsonSchema: input.jsonSchema,
        metadata: input.metadata,
      });
    }),

  // Update only metadata, prompt, title, description and non-structural changes
  updateMetadata: systemAdminProcedure
    .input(
      z.object({
        id: z.string(),
        title: z.string().optional(),
        description: z.string().optional(),
        defaultPrompt: z.string().optional(),
        metadata: schemaMetadataSchema.optional(),
      }),
    )
    .mutation(async ({ input }) => {
      return await schemaService.updateSchemaMetadata(input.id, {
        title: input.title,
        description: input.description,
        defaultPrompt: input.defaultPrompt,
        metadata: input.metadata,
      });
    }),

  // Create a new version of an existing schema
  createNewVersion: systemAdminProcedure
    .input(
      z.object({
        previousSchemaId: z.string(),
        title: z.string().min(1, "Title is required"),
        description: z.string(),
        defaultPrompt: z.string(),
        jsonSchema: z.record(z.unknown()),
        metadata: schemaMetadataSchema.optional(),
      }),
    )
    .mutation(async ({ input }) => {
      return await schemaService.createSchemaVersion({
        previousSchemaId: input.previousSchemaId,
        title: input.title,
        description: input.description,
        defaultPrompt: input.defaultPrompt,
        jsonSchema: input.jsonSchema,
        metadata: input.metadata,
      });
    }),

  // Get version history for a schema
  getVersionHistory: systemAdminProcedure
    .input(
      z.object({
        schemaKey: z.string(),
      }),
    )
    .query(async ({ input }) => {
      return await schemaService.getSchemaVersionHistory(input.schemaKey);
    }),

  // Mark schema as inactive (soft delete)
  delete: systemAdminProcedure
    .input(
      z.object({
        id: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      return await schemaService.deactivateSchema(input.id);
    }),
});

