      // Check if SMS verification is allowed
      const allowedMethods = job.allowedVerificationMethods as
        | string[]
        | null
        | undefined;
      if (allowedMethods && !allowedMethods.includes("sms")) {
        throw new Error("SMS verification is not allowed for this job");
      }

      // Check email domain restrictions (for the email provided during SMS verification)
      const allowedDomains = job.allowedEmailDomains as
        | string[]
        | null
        | undefined;
      throwIfEmailNotFromValidDomain(email, allowedDomains);

      const agentPhoneNumber = await db.agentPhoneNumber.findFirstOrThrow({
        where: {
          organizationId: "cm575xma40000lc03c16whsu3", // Purplefish org
          countryCode: "US",
          telnyxCampaignId: {
            not: null,
          },
          telnyxCampaignAssignmentStatus: "ASSIGNED",
        },
      });

      // Normalize phone number
      const normalizedPhoneNumber =
        validateAndNormalizePhoneNumber(phoneNumber);
      if (!normalizedPhoneNumber) {
        throw new Error("Invalid phone number");
      }

      // Generate OTP
      const otpCode = String(Math.floor(100000 + Math.random() * 900000));
      const expiresAt = new Date(Date.now() + 15 * 60 * 1000); // 15 minutes

      // Delete any existing verification records for this phone number
      await db.candidatePhoneVerification.deleteMany({
        where: {
          phoneNumber: normalizedPhoneNumber,
        },
      });

      // Create new verification record with candidate information
      const verification = await db.candidatePhoneVerification.create({
        data: {
          phoneNumber: normalizedPhoneNumber,
          otpCode,
          expiresAt,
          firstName,
          lastName,
          email,
        },
      });

      // Send SMS with OTP
      const message = `Your Purplefish interview code is ${otpCode}. This code will expire in 15 minutes.`;

      try {
        await sendSMS(agentPhoneNumber.number, normalizedPhoneNumber, message);
      } catch (error) {
        console.error("Failed to send SMS:", error);
        throw new Error("Failed to send verification code");
      }

      return { success: true, id: verification.id };
    }),

