import { z } from "zod";

import { BASE_URL } from "@/common/libs/base-url";
import { env } from "@/env";
import { inngest } from "@/server/inngest/client";
import {
  getFullCalendarInvite,
  updateCalendarInviteDownload,
} from "@/server/resource_access/calendar-invite-resource-accessor";
import { CalendarService } from "@/server/services/calendar/calendar-service";

import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { publicProcedure } from "../procedures/public-procedure";
import { router } from "../trpc";

const sendCalendarInviteSmsSchema = z.object({
  opportunityId: z.string(),
  candidateId: z.string(),
  candidatePhoneNumber: z.string(),
  eventTitle: z.string(),
  eventDescription: z.string().optional(),
  startDateTime: z.string(),
  endDateTime: z.string(),
  location: z.string().optional(),
  message: z.string(),
});

const sendCalendarInviteEmailSchema = z.object({
  opportunityId: z.string(),
  candidateId: z.string(),
  candidateEmail: z.string().email(),
  eventTitle: z.string(),
  eventDescription: z.string().optional(),
  startDateTime: z.string(),
  endDateTime: z.string(),
  location: z.string().optional(),
  subject: z.string(),
  body: z.string(),
});

export const calendarInviteRouter = router({
  sendSms: organizationMemberProcedure
    .input(sendCalendarInviteSmsSchema)
    .mutation(async ({ input }) => {
      const { organizationId } = input;

      const response = await fetch(
        `${BASE_URL}/api/calendar-invites/send-sms`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${env.MESSAGING_API_KEY}`,
          },
          body: JSON.stringify({
            opportunity_id: input.opportunityId,
            purplefish_organization_id: organizationId,
            purplefish_participant_id: input.candidateId,
            participant_role: "candidate",
            participant_phone_number: input.candidatePhoneNumber,
            event_title: input.eventTitle,
            event_description: input.eventDescription,
            start_date_time: input.startDateTime,
            end_date_time: input.endDateTime,
            location: input.location,
            message: input.message,
            other_participants: [],
          }),
        },
      );

      if (!response.ok) {
        const error = (await response.json()) as {
          error?: { message?: string };
        };
        throw new Error(
          error.error?.message || "Failed to send calendar invite",
        );
      }

      const result = (await response.json()) as {
        success: boolean;
        message_id: string;
        calendar_invite_id: string;
        calendar_link: string;
        expires_at: string;
      };

      return result;
    }),

  sendEmail: organizationMemberProcedure
    .input(sendCalendarInviteEmailSchema)
    .mutation(async ({ input }) => {
      const { organizationId } = input;

      const response = await fetch(
        `${BASE_URL}/api/calendar-invites/send-email`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${env.MESSAGING_API_KEY}`,
          },
          body: JSON.stringify({
            opportunity_id: input.opportunityId,
            purplefish_organization_id: organizationId,
            purplefish_participant_id: input.candidateId,
            participant_role: "candidate",
            participant_email: input.candidateEmail,
            event_title: input.eventTitle,
            event_description: input.eventDescription,
            start_date_time: input.startDateTime,
            end_date_time: input.endDateTime,
            location: input.location,
            message_subject: input.subject,
            message_body: input.body,
            other_participants: [],
          }),
        },
      );

      if (!response.ok) {
        const error = (await response.json()) as {
          error?: { message?: string };
        };
        throw new Error(
          error.error?.message || "Failed to send calendar invite",
        );
      }

      const result = (await response.json()) as {
        success: boolean;
        message_id: string;
        calendar_invite_id: string;
        calendar_link: string;
        expires_at: string;
      };

      return result;
    }),

  downloadIcs: publicProcedure
    .input(z.object({ inviteId: z.string() }))
    .mutation(async ({ input }) => {
      const invite = await getFullCalendarInvite(input.inviteId);

      if (!invite) {
        throw new Error("Calendar invite not found");
      }

      if (new Date() > invite.expiresAt) {
        throw new Error("Calendar invite has expired");
      }

      const calendarService = new CalendarService();

      // Parse attendees
      const attendees = invite.otherParticipants as {
        name?: string;
        email?: string;
        phone?: string;
      }[];

      const icsFile = calendarService.generateIcsFile({
        title: invite.eventTitle,
        startDateTime: invite.startDateTime.toISOString(),
        endDateTime: invite.endDateTime.toISOString(),
        description: invite.eventDescription || undefined,
        location: invite.location || undefined,
        participant_timezone: invite.participantTimezone,
        attendees,
      });

      // Track download
      const isFirstDownload = !invite.downloadedAt;
      await updateCalendarInviteDownload(input.inviteId, isFirstDownload);

      if (isFirstDownload) {
        // Emit download event
        await inngest.send({
          name: "calendar.invite.downloaded",
          data: {
            invite_id: input.inviteId,
            opportunity_id: invite.opportunityId || undefined,
            participant_id: invite.participantId,
            participant_type:
              invite.participantRole === "candidate" ? "candidate" : "user",
            organization_id: invite.organizationId,
            download_method: "ics_file",
            downloaded_at: new Date().toISOString(),
          },
        });
      }

      return icsFile.toString("base64");
    }),

  getGoogleCalendarUrl: publicProcedure
    .input(z.object({ inviteId: z.string() }))
    .mutation(async ({ input }) => {
      const invite = await getFullCalendarInvite(input.inviteId);

      if (!invite) {
        throw new Error("Calendar invite not found");
      }

      if (new Date() > invite.expiresAt) {
        throw new Error("Calendar invite has expired");
      }

      // Format dates for Google Calendar
      const startDate = invite.startDateTime
        .toISOString()
        .replace(/[-:]/g, "")
        .replace(/\.\d{3}/, "");
      const endDate = invite.endDateTime
        .toISOString()
        .replace(/[-:]/g, "")
        .replace(/\.\d{3}/, "");

      const params = new URLSearchParams({
        action: "TEMPLATE",
        text: invite.eventTitle,
        dates: `${startDate}/${endDate}`,
        details: invite.eventDescription || "",
        location: invite.location || "",
      });

      // Track add to calendar
      await inngest.send({
        name: "calendar.invite.added-to-calendar",
        data: {
          invite_id: input.inviteId,
          opportunity_id: invite.opportunityId || undefined,
          participant_id: invite.participantId,
          participant_type:
            invite.participantRole === "candidate" ? "candidate" : "user",
          organization_id: invite.organizationId,
          calendar_type: "google",
          added_at: new Date().toISOString(),
        },
      });

      return `https://calendar.google.com/calendar/render?${params.toString()}`;
    }),
});

