import { z } from "zod";

import {
  callFlowSchema,
  greetingConfigSchema,
  interviewBuilderSchema,
  outroConfigSchema,
  requirementScorecardSchema,
} from "@/common/models/interview-builder";
import { interviewBuilderService } from "@/server/services/interview-builder-service";

import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { router } from "../trpc";

export const interviewBuilderRouter = router({
  /**
   * Get the current interview builder state for a job
   */
  getBuilderState: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
      }),
    )
    .query(async ({ input }) => {
      const { organizationId, jobId } = input;
      return await interviewBuilderService.getBuilderState(
        organizationId,
        jobId,
      );
    }),

  /**
   * Update job setup (title and description)
   */
  updateJobSetup: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        data: z.object({
          title: z.string().min(1),
          description: z.string().min(1),
        }),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, data } = input;
      return await interviewBuilderService.updateJobSetup(
        organizationId,
        jobId,
        data,
      );
    }),

  /**
   * Update scorecard requirements
   */
  updateScorecard: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        data: requirementScorecardSchema,
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, data } = input;
      return await interviewBuilderService.updateScorecard(
        organizationId,
        jobId,
        data,
      );
    }),

  /**
   * Update call flow
   */
  updateCallFlow: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        data: callFlowSchema,
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, data } = input;
      return await interviewBuilderService.updateCallFlow(
        organizationId,
        jobId,
        data,
      );
    }),

  /**
   * Update greeting configuration
   */
  updateGreetingConfig: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        greetingConfig: greetingConfigSchema,
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, greetingConfig } = input;
      return await interviewBuilderService.updateGreetingConfig(
        organizationId,
        jobId,
        greetingConfig,
      );
    }),

  /**
   * Update outro configuration
   */
  updateOutroConfig: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        outroConfig: outroConfigSchema,
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, outroConfig } = input;
      return await interviewBuilderService.updateOutroConfig(
        organizationId,
        jobId,
        outroConfig,
      );
    }),

  /**
   * Mark interview builder as complete and activate job
   */
  completeBuilder: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId } = input;
      return await interviewBuilderService.completeBuilder(
        organizationId,
        jobId,
      );
    }),

  /**
   * Save draft (explicit save without completing step)
   */
  saveDraft: organizationMemberProcedure
    .input(
      z.object({
        jobId: z.string(),
        interviewBuilder: interviewBuilderSchema.partial(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, jobId, interviewBuilder } = input;
      return await interviewBuilderService.saveDraft(
        organizationId,
        jobId,
        interviewBuilder,
      );
    }),
});

