import { z } from "zod";

import { db } from "@purplefish-ai/db/server";

import { BASE_URL } from "@/common/libs/base-url";
import CandidateInterviewVerificationEmail from "@/emails/candidate-interview-verification";

import { publicProcedure } from "../procedures/public-procedure";
import { router } from "../trpc";

export const candidatePhoneNumberRouter = router({
  sendCandidateOtp: publicProcedure
    .input(
      z.object({
        jobId: z.string(),
        phoneNumber: z.string(),
        firstName: z.string(),
        lastName: z.string(),
        email: z.string().email(),
      }),
    )
    .mutation(async ({ input }) => {
      const { jobId, phoneNumber, firstName, lastName, email } = input;

      // Check if job has public access and get auth settings
      const job = await db.job.findUnique({
        where: { id: jobId },
        select: {
          id: true,
          title: true,
          publicAccessEnabledAt: true,
          organizationId: true,
          allowedEmailDomains: true,
          allowedVerificationMethods: true,
        },
      });

      if (!job?.publicAccessEnabledAt) {
        throw new Error("Job not found or public access not enabled");
      }

      // Check if SMS verification is allowed
      const allowedMethods = job.allowedVerificationMethods as
        | string[]
        | null
        | undefined;
      if (allowedMethods && !allowedMethods.includes("sms")) {
        throw new Error("SMS verification is not allowed for this job");
      }

      // Check email domain restrictions (for the email provided during SMS verification)
      const allowedDomains = job.allowedEmailDomains as
        | string[]
        | null
        | undefined;
      const { throwIfEmailNotFromValidDomain } = await import("@/common/libs/emails");
      throwIfEmailNotFromValidDomain(email, allowedDomains);

      const agentPhoneNumber = await db.agentPhoneNumber.findFirstOrThrow({
        where: {
          organizationId: "cm575xma40000lc03c16whsu3", // Purplefish org
          countryCode: "US",
          telnyxCampaignId: {
            not: null,
          },
          telnyxCampaignAssignmentStatus: "ASSIGNED",
        },
      });

      // Normalize phone number
      const { validateAndNormalizePhoneNumber } = await import("@/common/libs/phone");
      const normalizedPhoneNumber =
        validateAndNormalizePhoneNumber(phoneNumber);
      if (!normalizedPhoneNumber) {
        throw new Error("Invalid phone number");
      }

      // Generate OTP
      const otpCode = String(Math.floor(100000 + Math.random() * 900000));
      const expiresAt = new Date(Date.now() + 15 * 60 * 1000); // 15 minutes

      // Delete any existing verification records for this phone number
      await db.candidatePhoneVerification.deleteMany({
        where: {
          phoneNumber: normalizedPhoneNumber,
        },
      });

      // Create new verification record with candidate information
      const verification = await db.candidatePhoneVerification.create({
        data: {
          phoneNumber: normalizedPhoneNumber,
          otpCode,
          expiresAt,
          firstName,
          lastName,
          email,
        },
      });

      // Send SMS with OTP
      const message = `Your Purplefish interview code is ${otpCode}. This code will expire in 15 minutes.`;

      try {
        const { sendSMS } = await import("@/server/libs/sms");
        await sendSMS(agentPhoneNumber.number, normalizedPhoneNumber, message);
      } catch (error) {
        console.error("Failed to send SMS:", error);
        throw new Error("Failed to send verification code");
      }

      return { success: true, id: verification.id };
    }),

  verifyCandidateOtp: publicProcedure
    .input(
      z.object({
        jobId: z.string(),
        phoneNumber: z.string(),
        otpCode: z.string(),
        id: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { jobId, phoneNumber, otpCode, id } = input;

      // Check if job has public access
      const job = await db.job.findUnique({
        where: { id: jobId },
        select: {
          id: true,
          title: true,
          publicAccessEnabledAt: true,
          organizationId: true,
        },
      });

      if (!job?.publicAccessEnabledAt) {
        throw new Error("Job not found or public access not enabled");
      }

      // Normalize phone number
      const { validateAndNormalizePhoneNumber } = await import("@/common/libs/phone");
      const normalizedPhoneNumber =
        validateAndNormalizePhoneNumber(phoneNumber);
      if (!normalizedPhoneNumber) {
        throw new Error("Invalid phone number");
      }

      // Find verification record using ID and phone number
      const verification = await db.candidatePhoneVerification.findFirst({
        where: {
          id,
          phoneNumber: normalizedPhoneNumber,
          expiresAt: {
            gt: new Date(),
          },
        },
      });

      if (!verification) {
        throw new Error("Invalid or expired verification");
      }

      if (verification.attempts >= 10) {
        throw new Error("Too many verification attempts");
      }

      if (verification.otpCode !== otpCode) {
        // Increment attempts
        await db.candidatePhoneVerification.update({
          where: { id: verification.id },
          data: { attempts: verification.attempts + 1 },
        });
        throw new Error("Invalid verification code");
      }

      // Mark as verified
      await db.candidatePhoneVerification.update({
        where: { id: verification.id },
        data: { verifiedAt: new Date() },
      });

      // Get candidate information from verification record
      const { firstName, lastName, email } = verification;

      // Efficiently find or create candidate using upsert
      const candidate = await db.candidate.upsert({
        where: {
          organizationId_phoneNumber: {
            organizationId: job.organizationId,
            phoneNumber: normalizedPhoneNumber,
          },
        },
        update: {
          firstName,
          lastName,
          email,
        },
        create: {
          firstName,
          lastName,
          email,
          phoneNumber: normalizedPhoneNumber,
          organizationId: job.organizationId,
        },
      });

      // Efficiently find or create opportunity using upsert
      const opportunity = await db.opportunity.upsert({
        where: {
          candidateId_jobId: {
            candidateId: candidate.id,
            jobId: job.id,
          },
        },
        update: {
          // Update any fields if needed
        },
        create: {
          candidateId: candidate.id,
          jobId: job.id,
          source: "public_interview",
        },
      });

      // Create public link token for interview
      const publicLinkToken = await getOpportunityPublicLinkToken({
        opportunityId: opportunity.id,
      });

      return {
        success: true,
        candidateId: candidate.id,
        opportunityId: opportunity.id,
        interviewToken: publicLinkToken,
      };
    }),

  sendCandidateEmailOtp: publicProcedure
    .input(
      z.object({
        jobId: z.string(),
        firstName: z.string(),
        lastName: z.string(),
        email: z.string().email(),
