      }

      // Check if email verification is allowed
      const allowedMethods = job.allowedVerificationMethods as
        | string[]
        | null
        | undefined;
      if (allowedMethods && !allowedMethods.includes("email")) {
        throw new Error("Email verification is not allowed for this job");
      }

      // Check email domain restrictions
      const allowedDomains = job.allowedEmailDomains as
        | string[]
        | null
        | undefined;
      throwIfEmailNotFromValidDomain(email, allowedDomains);

      // Generate OTP
      const otpCode = String(Math.floor(100000 + Math.random() * 900000));
      const expiresAt = new Date(Date.now() + 15 * 60 * 1000); // 15 minutes

      // Delete any existing verification records for this email
      await db.candidatePhoneVerification.deleteMany({
        where: {
          email,
        },
      });

      // Create new verification record with candidate information
      const verification = await db.candidatePhoneVerification.create({
        data: {
          phoneNumber,
          otpCode,
          expiresAt,
          firstName,
          lastName,
          email,
        },
      });

      // Send email with OTP
      try {
        await resend.emails.send({
          from: "Purplefish <no-reply@purplefish.com>",
          to: email,
          subject: `Your Purplefish conversation verification code for ${job.title}`,
          react: CandidateInterviewVerificationEmail({
            firstName,
            jobTitle: job.title,
            organizationName: job.organization.name,
            otpCode,
            baseUrl: BASE_URL,
          }),
        });
      } catch (error) {
        console.error("Failed to send email:", error);
        throw new Error("Failed to send verification code");
      }

      return { success: true, id: verification.id };
    }),

  verifyCandidateEmailOtp: publicProcedure
    .input(
      z.object({
        jobId: z.string(),
        email: z.string().email(),
        otpCode: z.string(),
        id: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { jobId, email, otpCode, id } = input;

      // Check if job has public access
      const job = await db.job.findUnique({
        where: { id: jobId },
        select: {
          id: true,
          title: true,
          publicAccessEnabledAt: true,
          organizationId: true,
        },
      });

      if (!job?.publicAccessEnabledAt) {
        throw new Error("Job not found or public access not enabled");
      }

      // Find verification record using ID and email
      const verification = await db.candidatePhoneVerification.findFirst({
        where: {
          id,
          email,
          expiresAt: {
            gt: new Date(),
          },
        },
      });

      if (!verification) {
        throw new Error("Invalid or expired verification");
      }

      if (verification.attempts >= 10) {
        throw new Error("Too many verification attempts");
      }

      if (verification.otpCode !== otpCode) {
        // Increment attempts
        await db.candidatePhoneVerification.update({
          where: { id: verification.id },
          data: { attempts: verification.attempts + 1 },
        });
        throw new Error("Invalid verification code");
      }

      // Mark as verified
      await db.candidatePhoneVerification.update({
        where: { id: verification.id },
        data: { verifiedAt: new Date() },
      });

      // Get candidate information from verification record
      const { firstName, lastName } = verification;

      // Normalize phone number
      const normalizedPhoneNumber = validateAndNormalizePhoneNumber(
        verification.phoneNumber,
      );
      if (!normalizedPhoneNumber) {
        throw new Error("Invalid phone number");
      }

      // Efficiently find or create candidate using upsert
      const candidate = await db.candidate.upsert({
