import { z } from "zod";

import { db } from "@purplefish-ai/db/server";

import {
  createEngagementFlag,
  resolveEngagementFlag,
  updateEngagementFlag,
} from "@/server/libs/engagement-flags";

import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { router } from "../trpc";

export const engagementFlagRouter = router({
  getEngagementFlags: organizationMemberProcedure
    .input(z.object({ engagementId: z.string().min(1) }))
    .query(async ({ input }) => {
      const { engagementId, organizationId } = input;

      // Verify that the engagement belongs to the organization
      const engagement = await db.engagement.findUniqueOrThrow({
        where: { id: engagementId, opportunity: { job: { organizationId } } },
      });

      const engagementFlags = await db.engagementFlag.findMany({
        where: { engagementId: engagement.id },
        include: {
          createdBy: true,
          resolvedBy: true,
        },
      });

      return engagementFlags;
    }),

  createEngagementFlag: organizationMemberProcedure
    .input(
      z.object({
        engagementId: z.string().min(1),
        notes: z.string().min(1),
        category: z.string().min(1),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { engagementId, notes, category, organizationId } = input;
      const { user } = ctx;

      // Verify that the engagement belongs to the organization
      const engagement = await db.engagement.findUniqueOrThrow({
        where: { id: engagementId, opportunity: { job: { organizationId } } },
      });

      return await createEngagementFlag({
        engagementId: engagement.id,
        notes,
        category,
        userId: user.id,
      });
    }),

  updateEngagementFlag: organizationMemberProcedure
    .input(
      z.object({
        engagementFlagId: z.string(),
        notes: z.string(),
        category: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { engagementFlagId, notes, category, organizationId } = input;

      // Verify that the engagement flag belongs to the organization
      const engagementFlag = await db.engagementFlag.findUniqueOrThrow({
        where: {
          id: engagementFlagId,
          engagement: { opportunity: { job: { organizationId } } },
        },
      });

      return await updateEngagementFlag({
        engagementFlagId: engagementFlag.id,
        notes,
        category,
      });
    }),

  resolveEngagementFlag: organizationMemberProcedure
    .input(
      z.object({
        engagementFlagId: z.string(),
        resolutionNotes: z.string(),
        resolutionCategory: z.string(),
      }),
    )
    .mutation(async ({ input, ctx }) => {
      const { user } = ctx;
      const {
        engagementFlagId,
        resolutionNotes,
        resolutionCategory,
        organizationId,
      } = input;

      // Verify that the engagement flag belongs to the organization
      const engagementFlag = await db.engagementFlag.findUniqueOrThrow({
        where: {
          id: engagementFlagId,
          engagement: { opportunity: { job: { organizationId } } },
        },
      });

      return await resolveEngagementFlag({
        engagementFlagId: engagementFlag.id,
        userId: user.id,
        resolutionNotes,
        resolutionCategory,
      });
    }),
});

